CREATE SEQUENCE IF NOT EXISTS public.ct_alert_seq;
GRANT USAGE, SELECT ON SEQUENCE public.ct_alert_seq TO authenticated, service_role;
DO $$ BEGIN CREATE TYPE public.ai_action_class AS ENUM ('AUTO_SAFE','APPROVAL_REQUIRED','HUMAN_ONLY','BLOCKED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.ai_action_state AS ENUM ('PROPOSED','APPROVAL_PENDING','APPROVED','EXECUTING','EXECUTED','FAILED','REJECTED','EXPIRED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
