DO $$ BEGIN CREATE TYPE public.data_classification_level AS ENUM ('public','internal','confidential','restricted','regulated'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.etims_sync_event_type AS ENUM ('SUBMIT_ATTEMPT','SUBMIT_SUCCESS','SUBMIT_FAILURE', 'WEBHOOK_ACK','WEBHOOK_REJECT','MANUAL_RESYNC','VOID','REFUND'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.export_status AS ENUM ('PENDING','EXPORTED','FAILED','SKIPPED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.fraud_case_status AS ENUM ('OPEN','INVESTIGATING','ESCALATED','CONFIRMED','DISMISSED','RESOLVED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.fraud_signal_kind AS ENUM ('DEVICE_CHANGE','IP_CHANGE','VELOCITY','GEO_ANOMALY','PAYMENT_PATTERN','SUSPICIOUS_PHONE','SYNTHETIC_IDENTITY','DRIVER_COLLUSION'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.gps_integrity_signal AS ENUM ('mock_location','impossible_speed','teleport_jump','accel_gps_mismatch', 'frozen_coords','altitude_anomaly','indoor_high_accuracy','known_spoofer_app','emulator'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.ifrs_classification AS ENUM ('CURRENT_ASSET','NON_CURRENT_ASSET', 'CURRENT_LIABILITY','NON_CURRENT_LIABILITY', 'EQUITY', 'OPERATING_REVENUE','OTHER_INCOME', 'OPERATING_EXPENSE','FINANCE_COST','TAX_EXPENSE', 'CLEARING','CONTROL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.ocr_status AS ENUM ('PENDING','PROCESSING','SUCCEEDED','FAILED','REVIEW'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.opt_experiment_state AS ENUM ('DECLARED','RUNNING','CONCLUDED','ROLLED_BACK','ABANDONED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.opt_risk_class AS ENUM ('LOW_REVERSIBLE','MEDIUM','HIGH','FINANCIAL','PRICING'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.opt_state AS ENUM ('DRAFT','MEASURED','SIMULATED','APPROVAL_PENDING','APPROVED','ACTIVE','ADOPTED','ROLLED_BACK','REJECTED','BLOCKED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
