DO $$ BEGIN CREATE TYPE public.privacy_request_status AS ENUM ('received','verifying','processing','completed','rejected','partial'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.privacy_request_type AS ENUM ('access','rectification','erasure','portability','restrict','object','consent_withdraw'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.reg_export_format AS ENUM ('CSV','JSON','PDF','XML','XBRL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.reg_report_kind AS ENUM ('VAT','WHT','REVENUE','DRIVER_EARNINGS','CORPORATE_SPEND','SETTLEMENT','AUDIT','CUSTOM'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.reg_submission_status AS ENUM ('DRAFT','SUBMITTED','ACKNOWLEDGED','REJECTED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.regulator AS ENUM ('KRA','CBK','INTERNAL_AUDIT','EXTERNAL_AUDIT','CORPORATE_CLIENT','OTHER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.revenue_allocation_kind AS ENUM ('GROSS_REVENUE','VAT','WHT','DRIVER_LIABILITY','COMMISSION','DEFERRED','DISCOUNT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.st_result AS ENUM ('PASS','FAIL','BLOCKED','NOT_TESTED','DEPENDENCY_NOT_READY', 'OWNER_ACTION_REQUIRED','PROVIDER_CONFIGURATION_REQUIRED', 'EXTERNAL_EXECUTION_REQUIRED','LEGAL_APPROVAL_REQUIRED', 'PRODUCTION_TARGET_REFUSED','EVIDENCE_EXPIRED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.tlp_marking AS ENUM ('WHITE','GREEN','AMBER','RED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.trust_resolution_outcome AS ENUM ('no_action','warning','refund','partial_refund','account_suspended','account_banned', 'driver_deactivated','escalated_external','law_enforcement','dismissed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.access_denials ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, user_email text, user_roles text[] NOT NULL DEFAULT '{}', surface text NOT NULL, requested_path text, requested_command text, reason text NOT NULL, required_roles text[] DEFAULT '{}', ip text, user_agent text, risk_score integer DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.account_takeover_alerts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, trigger_event_id UUID REFERENCES public.authentication_events(id) ON DELETE SET NULL, status public.ato_alert_status NOT NULL DEFAULT 'detected', severity public.security_severity NOT NULL DEFAULT 'HIGH', signals JSONB NOT NULL DEFAULT '[]'::JSONB, countermeasures JSONB NOT NULL DEFAULT '[]'::JSONB, notified_user BOOLEAN NOT NULL DEFAULT false, acknowledged_by_user_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, resolved_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.admin_backup_codes ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, code_hash TEXT NOT NULL, used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.admin_device_registry ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, device_fingerprint TEXT NOT NULL, device_label TEXT, os TEXT, browser TEXT, trusted BOOLEAN NOT NULL DEFAULT false, trusted_at TIMESTAMPTZ, last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (user_id, device_fingerprint) );
CREATE TABLE IF NOT EXISTS public.admin_email_test_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), triggered_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, triggered_by_email TEXT, template_name TEXT, recipient_email TEXT, subject TEXT, payload JSONB NOT NULL DEFAULT '{}'::jsonb, edge_response JSONB, rendered_html TEXT, delivery_status TEXT NOT NULL DEFAULT 'pending', delivery_message_id TEXT, error_message TEXT, duration_ms INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.admin_login_attempts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, email TEXT NOT NULL, ip_address INET, user_agent TEXT, country TEXT, success BOOLEAN NOT NULL DEFAULT false, failure_reason TEXT, risk_score NUMERIC(5,2) DEFAULT 0, mfa_used BOOLEAN DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.admin_login_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, email text NOT NULL, event_type text NOT NULL, ip text, country text, device_id text, browser text, operating_system text, risk_score int NOT NULL DEFAULT 0, decision text NOT NULL DEFAULT 'allow', reason text, prev_hash text, event_hash text, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.admin_mfa_devices ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, factor_type TEXT NOT NULL CHECK (factor_type IN ('totp','sms','email')), label TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','revoked')), enrolled_at TIMESTAMPTZ, last_used_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.admin_sessions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, ip_address INET, user_agent TEXT, device_id TEXT, device_label TEXT, country TEXT, city TEXT, risk_score NUMERIC(5,2) DEFAULT 0, last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ, revoked_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_adapters ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_type text NOT NULL UNIQUE, domain text NOT NULL, adapter_code text NOT NULL, version integer NOT NULL DEFAULT 1, target_service text NOT NULL, target_function text, automation_allowed boolean NOT NULL DEFAULT false, refusal_reason text, revalidation_kind text NOT NULL DEFAULT 'NONE', required_payload_keys text[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ai_adapters_refusal CHECK (automation_allowed OR refusal_reason IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.ai_agents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, domain text NOT NULL, description text, enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_detectors ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, version integer NOT NULL DEFAULT 1, domain text NOT NULL, name text NOT NULL, event_source text NOT NULL, trigger_condition text NOT NULL, default_severity text NOT NULL CHECK (default_severity IN ('P0','P1','P2','P3')), confidence_floor numeric NOT NULL DEFAULT 0.50 CHECK (confidence_floor >= 0 AND confidence_floor <= 1), recommendation_type text, active boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.ai_model_registry ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, provider text NOT NULL, model text NOT NULL, model_version text NOT NULL DEFAULT 'unpinned', prompt_version text NOT NULL, tool_version text NOT NULL, max_output_tokens integer NOT NULL DEFAULT 2048, timeout_ms integer NOT NULL DEFAULT 60000, max_cost_usd numeric NOT NULL DEFAULT 0.50, fallback_model_code text, confidence_threshold numeric NOT NULL DEFAULT 0.70 CHECK (confidence_threshold >= 0 AND confidence_threshold <= 1), grounding_required boolean NOT NULL DEFAULT true, configured boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_type text NOT NULL, version integer NOT NULL DEFAULT 1, classification public.ai_action_class NOT NULL, target_service text, rules jsonb NOT NULL DEFAULT '{}'::jsonb, rationale text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (action_type, version) );
CREATE TABLE IF NOT EXISTS public.air_empty_legs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_id uuid NOT NULL REFERENCES public.air_fleet(id) ON DELETE CASCADE, owner_id uuid NOT NULL DEFAULT auth.uid(), origin text NOT NULL REFERENCES public.air_airfields(code), destination text NOT NULL REFERENCES public.air_airfields(code), depart_date date NOT NULL, flexible_days int NOT NULL DEFAULT 0 CHECK (flexible_days BETWEEN 0 AND 7), price_kes numeric NOT NULL CHECK (price_kes > 0), seats int NOT NULL CHECK (seats > 0), status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','held','sold','withdrawn')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (origin <> destination) );
CREATE TABLE IF NOT EXISTS public.alert_monitor_settings ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cadence_minutes INTEGER NOT NULL DEFAULT 15 CHECK (cadence_minutes BETWEEN 1 AND 1440), spike_absolute_threshold INTEGER NOT NULL DEFAULT 10 CHECK (spike_absolute_threshold >= 1), spike_multiplier NUMERIC NOT NULL DEFAULT 3 CHECK (spike_multiplier >= 1), enabled BOOLEAN NOT NULL DEFAULT TRUE, updated_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.alert_mute_windows ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), label TEXT NOT NULL, rule_id TEXT, metric_key TEXT, severity TEXT, starts_at TIMESTAMPTZ NOT NULL DEFAULT now(), ends_at TIMESTAMPTZ NOT NULL, reason TEXT, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (ends_at > starts_at) );
CREATE TABLE IF NOT EXISTS public.alert_notification_prefs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role text NOT NULL UNIQUE, email_enabled boolean NOT NULL DEFAULT true, slack_enabled boolean NOT NULL DEFAULT true, severity_info boolean NOT NULL DEFAULT false, severity_warning boolean NOT NULL DEFAULT true, severity_critical boolean NOT NULL DEFAULT true, slack_webhook_url text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.analytics_aggregates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_key text NOT NULL, bucket_period text NOT NULL, bucket_start timestamptz NOT NULL, value numeric(20,4) NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (aggregate_key, bucket_period, bucket_start));
CREATE TABLE IF NOT EXISTS public.analytics_dimensions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dimension_key text UNIQUE NOT NULL, dimension_type text NOT NULL, description text, values jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.analytics_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_name text NOT NULL, user_id uuid, subject_type text, subject_id uuid, properties jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.analytics_export_outbox ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_table text NOT NULL, source_pk text NOT NULL, event_date date NOT NULL DEFAULT CURRENT_DATE, payload jsonb NOT NULL, payload_hash text, status public.export_status NOT NULL DEFAULT 'PENDING', attempts int NOT NULL DEFAULT 0, last_error text, exported_at timestamptz, bq_insert_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (source_table, source_pk) );
CREATE TABLE IF NOT EXISTS public.analytics_facts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fact_table text NOT NULL, dim_key jsonb NOT NULL, metric_name text NOT NULL, metric_value numeric(20,4) NOT NULL, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.analytics_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), snapshot_key text NOT NULL, snapshot_date date NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (snapshot_key, snapshot_date));
CREATE TABLE IF NOT EXISTS public.ap360_cost_inputs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES public.ap360_versions(id) ON DELETE CASCADE, cost_key text NOT NULL, label text NOT NULL, unit text NOT NULL, amount numeric(14,2) NOT NULL DEFAULT 0, category text NOT NULL DEFAULT 'direct', note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_cost_unique UNIQUE (version_id, cost_key), CONSTRAINT ap360_cost_amount CHECK (amount >= 0), CONSTRAINT ap360_cost_category CHECK (category IN ('direct','overhead','risk_reserve')), CONSTRAINT ap360_cost_unit CHECK (unit IN ('per_trip','per_day','per_hour','per_km','per_night','per_passenger','per_movement','per_block_hour','fixed')) );
CREATE TABLE IF NOT EXISTS public.ap360_fuel_index ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country text NOT NULL DEFAULT 'KE', region text NOT NULL DEFAULT 'National', fuel_type text NOT NULL, price numeric(12,2) NOT NULL, currency text NOT NULL DEFAULT 'KES', unit text NOT NULL DEFAULT 'litre', effective_from date NOT NULL, effective_to date, source text NOT NULL DEFAULT 'EPRA', captured_at timestamptz NOT NULL DEFAULT now(), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_fuel_price CHECK (price > 0), CONSTRAINT ap360_fuel_type CHECK (fuel_type IN ('petrol','diesel','kerosene','jet_a1','avgas','marine_diesel')), CONSTRAINT ap360_fuel_window CHECK (effective_to IS NULL OR effective_to >= effective_from), CONSTRAINT ap360_fuel_unique UNIQUE (country, region, fuel_type, effective_from) );
CREATE TABLE IF NOT EXISTS public.ap360_market_references ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_code text NOT NULL REFERENCES public.ap360_categories(code) ON DELETE CASCADE, source text NOT NULL, source_url text, market text NOT NULL DEFAULT 'KE', geographic_area text NOT NULL DEFAULT 'National', observed_price numeric(14,2) NOT NULL, currency text NOT NULL DEFAULT 'KES', pricing_unit text NOT NULL, observed_date date NOT NULL, valid_until date, confidence text NOT NULL DEFAULT 'medium', notes text NOT NULL DEFAULT '', created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_market_price CHECK (observed_price > 0), CONSTRAINT ap360_market_confidence CHECK (confidence IN ('low','medium','high','verified')) );
CREATE TABLE IF NOT EXISTS public.ap360_quote_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_ref text, profile_id uuid REFERENCES public.ap360_profiles(id) ON DELETE SET NULL, version_id uuid REFERENCES public.ap360_versions(id) ON DELETE SET NULL, category_code text, engine_code text, version_number integer, inputs jsonb NOT NULL, result jsonb NOT NULL, currency text NOT NULL DEFAULT 'KES', customer_price numeric(14,2) NOT NULL, operator_net numeric(14,2) NOT NULL, yalla_revenue numeric(14,2) NOT NULL, operator_floor numeric(14,2) NOT NULL, contribution_pct numeric(8,3) NOT NULL, profitability_band text NOT NULL, exception_id uuid REFERENCES public.ap360_exceptions(id) ON DELETE SET NULL, calculated_by uuid, calculated_at timestamptz NOT NULL DEFAULT now(), valid_until timestamptz );
CREATE TABLE IF NOT EXISTS public.app_pages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route text NOT NULL UNIQUE, title text NOT NULL, page_group text, icon text, roles_required text[] NOT NULL DEFAULT ARRAY[]::text[], is_public boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true, sort_order int NOT NULL DEFAULT 100, description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.approval_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.approval_requests(id) ON DELETE CASCADE, step_no int NOT NULL, decided_by uuid NOT NULL, decision public.approval_decision_type NOT NULL, comment text, delegated_to uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.approval_delegations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delegator_user_id uuid NOT NULL, delegate_user_id uuid NOT NULL, corporate_id uuid REFERENCES public.corporate_accounts(id), starts_at timestamptz NOT NULL DEFAULT now(), ends_at timestamptz, active boolean NOT NULL DEFAULT true, reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.approval_escalations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.approval_requests(id) ON DELETE CASCADE, escalated_from_step int NOT NULL, escalated_to_user_id uuid, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.assurance_flakiness ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scenario text NOT NULL UNIQUE, domain text, flips integer NOT NULL DEFAULT 0, last_10 jsonb NOT NULL DEFAULT '[]'::jsonb, quarantined_at timestamptz, stabilized_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.assurance_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sha text, branch text, status text NOT NULL CHECK (status IN ('passed','failed','partial')), production_score numeric, indices jsonb NOT NULL DEFAULT '{}'::jsonb, kpi_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, failing_modules jsonb NOT NULL DEFAULT '[]'::jsonb, artifacts jsonb NOT NULL DEFAULT '{}'::jsonb, run_url text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.audit_hash_chain ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stream text NOT NULL UNIQUE, head_hash text, head_id uuid, head_at timestamptz, count bigint NOT NULL DEFAULT 0, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.audit_hashes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), as_of timestamptz NOT NULL DEFAULT now(), chain_root bytea NOT NULL, entry_count int NOT NULL, algorithm text NOT NULL DEFAULT 'sha256', notes text );
CREATE TABLE IF NOT EXISTS public.audit_logs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id UUID, actor_role TEXT, entity_type TEXT NOT NULL, entity_id UUID, action TEXT NOT NULL, before_data JSONB, after_data JSONB, ip_address INET, user_agent TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.audit_report_schedules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, cadence text NOT NULL CHECK (cadence IN ('daily','weekly','monthly')), range_days integer NOT NULL DEFAULT 7, recipients jsonb NOT NULL DEFAULT '[]'::jsonb, include_audit boolean NOT NULL DEFAULT true, include_login boolean NOT NULL DEFAULT true, enabled boolean NOT NULL DEFAULT true, last_run_at timestamptz, next_run_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.audit_verifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stream text NOT NULL, range_start timestamptz NOT NULL, range_end timestamptz NOT NULL, status text NOT NULL, rows_checked bigint NOT NULL DEFAULT 0, first_broken_id uuid, broken_at timestamptz, verified_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.availability_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_code text NOT NULL, metric_date date NOT NULL, uptime_seconds bigint NOT NULL DEFAULT 0, downtime_seconds bigint NOT NULL DEFAULT 0, incidents int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (service_code, metric_date));
CREATE TABLE IF NOT EXISTS public.backup_jobs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), job_name TEXT NOT NULL, target TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'running', size_bytes BIGINT, duration_seconds INT, destination TEXT, checksum TEXT, error_message TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.behavioral_scores ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, score numeric(6,3) NOT NULL, band text NOT NULL CHECK (band IN ('LOW','MEDIUM','HIGH','CRITICAL')), features jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.blocked_ips ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ip_address INET NOT NULL, reason TEXT NOT NULL, source TEXT, blocked_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, blocked_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.budget_forecasts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), budget_id uuid NOT NULL REFERENCES public.budgets(id) ON DELETE CASCADE, as_of date NOT NULL, projected_cents bigint NOT NULL, basis jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.capacity_commitments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), commitment_ref text NOT NULL UNIQUE, transaction_id uuid REFERENCES public.commercial_transactions(id) ON DELETE SET NULL, service_line text NOT NULL, provider_kind text NOT NULL DEFAULT 'driver', provider_ref text, driver_id uuid, vehicle_id uuid, resource_ref text, customer_user_id uuid, corporate_id uuid, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, price_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', commercial_terms jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'reserved', expires_at timestamptz NOT NULL, accepted_at timestamptz, released_at timestamptz, booking_id uuid, booking_table text, offer_ref text, dispatch_request_id uuid, lineage jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT capacity_commitments_status_check CHECK (status = ANY (ARRAY['reserved','accepted','booked','expired','released','cancelled'])), CONSTRAINT capacity_commitments_window_check CHECK (window_end >= window_start), CONSTRAINT capacity_commitments_price_check CHECK (price_cents >= 0) );
CREATE TABLE IF NOT EXISTS public.capacity_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_code text NOT NULL UNIQUE DEFAULT ('CAP-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8))), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, service_type public.mobility_service_type NOT NULL DEFAULT 'CHARTER', origin_label text NOT NULL, destination_label text, needed_at timestamptz, passengers integer, cargo_weight_kg numeric(12,2), vehicle_class text, service_level text, budget_amount numeric(14,2), currency text NOT NULL DEFAULT 'KES', requirements text, status text NOT NULL DEFAULT 'open', resolution_notes text, is_demo boolean NOT NULL DEFAULT false, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.carrier_applications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_reference text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED','UNDER_REVIEW','INFO_REQUESTED','APPROVED','REJECTED','WITHDRAWN')), legal_entity_name text NOT NULL, trading_name text, registration_number text, tax_identifier text, country text NOT NULL DEFAULT 'KE', county text, town text, contact_name text NOT NULL, contact_position text, contact_email text NOT NULL, contact_phone text NOT NULL, fleet_size integer, vehicle_types text[] NOT NULL DEFAULT '{}', service_categories text[] NOT NULL DEFAULT '{}', corridors text[] NOT NULL DEFAULT '{}', notes text, applicant_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, claim_token text NOT NULL, review_notes text, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at timestamptz, decided_at timestamptz, partner_id uuid, carrier_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.carrier_capabilities ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, vehicle_type text NOT NULL, vehicle_class text, max_payload_kg numeric(12,2) NOT NULL CHECK (max_payload_kg > 0), max_volume_cbm numeric(12,3), max_length_cm numeric(10,1), max_width_cm numeric(10,1), max_height_cm numeric(10,1), temperature_controlled boolean NOT NULL DEFAULT false, temperature_min_c numeric(5,1), temperature_max_c numeric(5,1), refrigerated boolean NOT NULL DEFAULT false, hazmat_capable boolean NOT NULL DEFAULT false, hazmat_authority_reference text, fragile_capable boolean NOT NULL DEFAULT false, high_value_capable boolean NOT NULL DEFAULT false, oversized_capable boolean NOT NULL DEFAULT false, container_capable boolean NOT NULL DEFAULT false, cross_border_capable boolean NOT NULL DEFAULT false, warehouse_capable boolean NOT NULL DEFAULT false, last_mile_capable boolean NOT NULL DEFAULT true, line_haul_capable boolean NOT NULL DEFAULT false, special_handling text[] NOT NULL DEFAULT '{}', equipment text[] NOT NULL DEFAULT '{}', units_declared integer NOT NULL DEFAULT 0 CHECK (units_declared >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (NOT hazmat_capable OR hazmat_authority_reference IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.carrier_compliance_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, requirement_code text NOT NULL, requirement_label text NOT NULL, category text NOT NULL CHECK (category IN ('LICENCE','PROTECTION','TAX','VEHICLE','DRIVER','CONTRACT','OTHER')), is_mandatory boolean NOT NULL DEFAULT true, state public.carrier_compliance_state NOT NULL DEFAULT 'MISSING', evidence_document_id uuid, evidence_storage_path text, evidence_hash text, issuing_authority text, reference_number text, issued_on date, expires_on date, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, driver_user_id uuid, legal_review_reason text, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at timestamptz, review_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (state <> 'VERIFIED' OR (reviewed_by IS NOT NULL AND (evidence_document_id IS NOT NULL OR evidence_storage_path IS NOT NULL))), CHECK (state <> 'LEGAL_REVIEW_REQUIRED' OR legal_review_reason IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.carrier_declarations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, declaration_code text NOT NULL, declaration_version text NOT NULL, declaration_title text NOT NULL, declaration_text_hash text NOT NULL, accepted_by uuid, accepted_by_name text, accepted_by_role text, accepted_at timestamptz, accepted_ip text, document_path text, state text NOT NULL DEFAULT 'PENDING' CHECK (state IN ('PENDING','ACCEPTED','SUPERSEDED','WITHDRAWN')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (carrier_id, declaration_code, declaration_version) );
CREATE TABLE IF NOT EXISTS public.carrier_requirement_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_code text NOT NULL UNIQUE, requirement_label text NOT NULL, category text NOT NULL, responsibility_level text NOT NULL CHECK (responsibility_level IN ('CARRIER','VEHICLE','DRIVER')), is_mandatory boolean NOT NULL DEFAULT true, service_categories text[] NOT NULL DEFAULT '{}', evidence_type text NOT NULL, issuing_authority_hint text, requires_expiry boolean NOT NULL DEFAULT true, guidance text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.carrier_score_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, bookings_total integer NOT NULL DEFAULT 0, on_time_pickup_pct numeric(6,2), on_time_delivery_pct numeric(6,2), acceptance_rate_pct numeric(6,2), tender_response_rate_pct numeric(6,2), cancellation_rate_pct numeric(6,2), failure_rate_pct numeric(6,2), damage_rate_pct numeric(6,2), pod_compliance_pct numeric(6,2), exception_rate_pct numeric(6,2), claim_rate_pct numeric(6,2), invoice_accuracy_pct numeric(6,2), reliability_score numeric(6,2), computed_from jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now(), UNIQUE (carrier_id, period_start, period_end) );
CREATE TABLE IF NOT EXISTS public.carrier_service_areas ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE CASCADE, area_kind text NOT NULL CHECK (area_kind IN ('CITY','COUNTY','COUNTRY','CORRIDOR','ZONE')), area_code text NOT NULL, area_label text NOT NULL, direction text NOT NULL DEFAULT 'BOTH' CHECK (direction IN ('ORIGIN','DESTINATION','BOTH')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (carrier_id, area_kind, area_code, direction) );
CREATE TABLE IF NOT EXISTS public.carrier_withdrawal_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_reference text NOT NULL UNIQUE, carrier_id uuid NOT NULL REFERENCES public.carrier_profiles(id) ON DELETE RESTRICT, destination_id uuid NOT NULL REFERENCES public.carrier_settlement_destinations(id) ON DELETE RESTRICT, amount_kes numeric(14,2) NOT NULL CHECK (amount_kes > 0), currency text NOT NULL DEFAULT 'KES', available_balance_at_request numeric(14,2), state text NOT NULL DEFAULT 'REQUESTED' CHECK (state IN ('REQUESTED','UNDER_REVIEW','APPROVED','REJECTED','EXECUTED','CONFIRMED','RECONCILED','CLOSED','FAILED','CANCELLED')), idempotency_key text NOT NULL UNIQUE, requested_by uuid, requested_at timestamptz NOT NULL DEFAULT now(), reviewed_by uuid, reviewed_at timestamptz, authorised_by uuid, authorised_at timestamptz, executed_at timestamptz, payment_evidence jsonb, settlement_id uuid, failure_reason text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.chart_of_accounts ( code text PRIMARY KEY, name text NOT NULL, account_type public.coa_type NOT NULL, normal_side public.coa_normal_side NOT NULL, parent_code text REFERENCES public.chart_of_accounts(code), is_postable boolean NOT NULL DEFAULT true, currency text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.command_access_logs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, command text NOT NULL, requested_center text, allowed boolean NOT NULL, denial_reason text, risk_score int NOT NULL DEFAULT 0, ip text, device_id text, country text, latency_ms int, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.command_denials ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, command text NOT NULL, requested_module text, reason text NOT NULL, risk_score int NOT NULL DEFAULT 0, country text, ip text, device_id text, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_a3_records ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL REFERENCES public.commercial_actions(id) ON DELETE CASCADE, situation text NOT NULL, analysis text NOT NULL, alternatives jsonb NOT NULL DEFAULT '[]'::jsonb, action text NOT NULL, approval text, accountability text, expected_outcome text NOT NULL, measurement text NOT NULL, review_at timestamptz, actual_outcome text, learning text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_account_service_volumes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.crm_accounts(id) ON DELETE CASCADE, staff_member_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, service_date date NOT NULL DEFAULT (now() AT TIME ZONE 'Africa/Nairobi')::date, airport_transfers integer NOT NULL DEFAULT 0 CHECK (airport_transfers >= 0), staff_transport_trips integer NOT NULL DEFAULT 0 CHECK (staff_transport_trips >= 0), parcel_deliveries integer NOT NULL DEFAULT 0 CHECK (parcel_deliveries >= 0), declared_value_kes numeric(14,2) CHECK (declared_value_kes IS NULL OR declared_value_kes >= 0), notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (account_id, service_date) );
CREATE TABLE IF NOT EXISTS public.commercial_action_outcomes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL REFERENCES public.commercial_actions(id) ON DELETE CASCADE, measured_at timestamptz NOT NULL DEFAULT now(), expected_revenue_cents bigint, actual_revenue_cents bigint, expected_contribution_cents bigint, actual_contribution_cents bigint, expected_fulfilment_pct numeric, actual_fulfilment_pct numeric, expected_conversion_pct numeric, actual_conversion_pct numeric, customer_outcome text, variance_pct numeric, verdict text NOT NULL DEFAULT 'pending', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, learning text, measured_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_action_outcomes_verdict_check CHECK (verdict IN ('pending','as_predicted','underperformed','outperformed','not_measurable')) );
CREATE TABLE IF NOT EXISTS public.commercial_activation_assignments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, account_id uuid REFERENCES public.crm_accounts(id) ON DELETE SET NULL, assignment_role text NOT NULL CHECK (assignment_role IN ('ACCOUNT_MANAGER','COORDINATOR','SUPERVISOR','DRIVER','VEHICLE')), staff_member_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, person_label text, vehicle_label text, start_date date, end_date date, status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','ACTIVE','COMPLETED','CANCELLED')), notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL CHECK (entity_type IN ('proposal','contract','service_order')), entity_id uuid NOT NULL, entity_ref text, account_id uuid, title text NOT NULL, amount_cents bigint, currency text NOT NULL DEFAULT 'KES', justification text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','declined','withdrawn')), requested_by uuid, requested_staff_id uuid, decided_by uuid, decided_at timestamptz, decision_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_deal_stakeholders ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_id uuid NOT NULL REFERENCES public.commercial_opportunities(id) ON DELETE CASCADE, account_id uuid, contact_id uuid, person_name text NOT NULL, job_title text, committee_role text NOT NULL CHECK (committee_role IN ( 'economic_buyer','decision_maker','procurement','finance','technical_evaluator', 'user','influencer','champion','detractor','executive_sponsor')), engagement text NOT NULL DEFAULT 'not_engaged' CHECK (engagement IN ('not_engaged','contacted','engaged','advocating','resistant')), confirmed_by uuid, confirmed_at timestamptz, source text NOT NULL DEFAULT 'manual', notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (opportunity_id, person_name, committee_role) );
CREATE TABLE IF NOT EXISTS public.commercial_document_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid REFERENCES public.commercial_documents(id), transaction_id uuid REFERENCES public.commercial_transactions(id), transaction_ref text, event_type text NOT NULL CHECK (event_type IN ( 'TRANSACTION_CREATED', 'QUOTE_CREATED','QUOTE_UPDATED','QUOTE_APPROVED','QUOTE_REJECTED','QUOTE_SENT','QUOTE_ACCEPTED','QUOTE_EXPIRED', 'PROFORMA_CREATED','PROFORMA_UPDATED','PROFORMA_APPROVED','PROFORMA_REJECTED','PROFORMA_SENT', 'PAYMENT_INITIATED','PAYMENT_RECEIVED','PAYMENT_MATCHED','PAYMENT_UNMATCHED','PAYMENT_RECONCILED','PAYMENT_FAILED', 'TAX_INVOICE_REQUESTED','TAX_VALIDATION_STARTED','ETIMS_SUBMISSION_STARTED','ETIMS_ACCEPTED','ETIMS_REJECTED','TAX_INVOICE_ISSUED', 'PAYMENT_CONFIRMATION_CREATED','PAYMENT_CONFIRMATION_SENT', 'EMAIL_QUEUED','EMAIL_SENT','EMAIL_DELIVERED','EMAIL_BOUNCED','EMAIL_FAILED', 'DOCUMENT_VOIDED','DOCUMENT_SUPERSEDED','DOCUMENT_CORRECTED', 'DOCUMENT_STATUS_CHANGED','ISSUANCE_BLOCKED','COMMERCIAL_VARIANCE_EXCEPTION', 'AUDIT_EXCEPTION_CREATED','AUDIT_EXCEPTION_RESOLVED' )), actor_id uuid, actor_type text NOT NULL DEFAULT 'staff' CHECK (actor_type IN ('staff','customer','system','integration')), prev_status text, new_status text, correlation_id uuid, causation_id uuid, source_system text NOT NULL DEFAULT 'commercial-document-engine', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_document_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_line text NOT NULL, customer_kind text NOT NULL DEFAULT 'any', requires_proforma boolean NOT NULL DEFAULT false, requires_etims boolean NOT NULL DEFAULT true, requires_payment_before_issue boolean NOT NULL DEFAULT false, approval_required_over_cents bigint, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (service_line, customer_kind) );
CREATE TABLE IF NOT EXISTS public.commercial_exception_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL REFERENCES public.commercial_exceptions(id) ON DELETE CASCADE, exception_ref text NOT NULL, action text NOT NULL, actor_id uuid, actor_email text, status_before text, status_after text, assignee_before uuid, assignee_after uuid, note text, sla_state text, escalation_level int, source text NOT NULL DEFAULT 'operator', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_financial_backfill_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_by uuid, dry_run boolean NOT NULL DEFAULT true, attempted integer NOT NULL DEFAULT 0, populated integer NOT NULL DEFAULT 0, still_incomplete integer NOT NULL DEFAULT 0, report jsonb NOT NULL DEFAULT '{}'::jsonb, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz );
CREATE TABLE IF NOT EXISTS public.commercial_lineage_stages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.commercial_transactions(id) ON DELETE CASCADE, transaction_ref text NOT NULL, stage_no smallint NOT NULL CHECK (stage_no BETWEEN 1 AND 14), stage_key text NOT NULL, authoritative_id text, authoritative_table text, status text NOT NULL DEFAULT 'recorded', occurred_at timestamptz, source text NOT NULL, actor_kind text NOT NULL DEFAULT 'system', actor_id uuid, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (transaction_id, stage_no) );
CREATE TABLE IF NOT EXISTS public.commercial_opportunity_changes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), opportunity_id uuid NOT NULL REFERENCES public.commercial_opportunities(id) ON DELETE CASCADE, field text NOT NULL, old_value text, new_value text, delta_cents bigint, changed_by uuid, changed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_rate_card_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rate_card_id uuid NOT NULL REFERENCES public.commercial_rate_cards(id) ON DELETE CASCADE, event text NOT NULL, status_before text, status_after text, note text, sole_approver boolean NOT NULL DEFAULT false, actor_user_id uuid, actor_staff_id uuid REFERENCES public.staff_members(id), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_rate_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rate_card_id uuid NOT NULL REFERENCES public.commercial_rate_cards(id) ON DELETE CASCADE, service_code text NOT NULL CHECK (service_code IN ( 'day_trip','executive','pwd','offroad','airport_transfer','monthly_long_term')), scope_label text NOT NULL DEFAULT '', category_code text NOT NULL REFERENCES public.commercial_vehicle_categories(code) ON DELETE RESTRICT, pricing_basis text NOT NULL CHECK (pricing_basis IN ('per_day','per_trip','per_month')), amount numeric(14,2) NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'KES', included_distance_km integer, included_distance_period text CHECK (included_distance_period IN ('day','trip','month')), drive_mode text CHECK (drive_mode IN ('chauffeured','self_drive','dry_with_driver')), min_days integer, inclusion_note text, conditions text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rate_card_id, service_code, scope_label, category_code, pricing_basis) );
CREATE TABLE IF NOT EXISTS public.commercial_reconciliation_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL DEFAULT gen_random_uuid(), break_kind text NOT NULL, stage_from text NOT NULL, stage_to text NOT NULL, entity_table text NOT NULL, entity_id text NOT NULL, value_cents bigint, severity text NOT NULL DEFAULT 'moderate', owner_label text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, root_cause text, status text NOT NULL DEFAULT 'open', resolution text, resolved_by uuid, resolved_at timestamptz, detected_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_recon_severity_check CHECK (severity IN ('critical','high','moderate','low')), CONSTRAINT commercial_recon_status_check CHECK (status IN ('open','investigating','resolved','accepted_risk')), CONSTRAINT commercial_recon_kind_check CHECK (break_kind IN ('missing_linkage','fulfilment_leakage','billing_leakage','settlement_discrepancy','revenue_discrepancy','dashboard_discrepancy')) );
CREATE TABLE IF NOT EXISTS public.commercial_reconciliation_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), run_source text NOT NULL DEFAULT 'job', transactions_scanned integer NOT NULL DEFAULT 0, breaks_found integer NOT NULL DEFAULT 0, exceptions_raised integer NOT NULL DEFAULT 0, result jsonb NOT NULL DEFAULT '{}'::jsonb, run_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_record_labels ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL DEFAULT auth.uid(), entity_type text NOT NULL CHECK (entity_type IN ('account','opportunity','quotation','contract','lead','contact')), entity_id uuid NOT NULL, label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (owner_user_id, entity_type, entity_id, label) );
CREATE TABLE IF NOT EXISTS public.commercial_schedules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_instance_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, rate_card_id uuid NOT NULL REFERENCES public.commercial_rate_cards(id) ON DELETE RESTRICT, title text NOT NULL, services text[] NOT NULL DEFAULT '{}', locations text[] NOT NULL DEFAULT '{}', vehicle_categories text[] NOT NULL DEFAULT '{}', commercial_terms text, validity text, special_conditions text, approval_status text NOT NULL DEFAULT 'pending' CHECK (approval_status IN ('pending','approved','rejected')), approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_service_execution_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), execution_id uuid NOT NULL REFERENCES public.commercial_service_executions(id) ON DELETE CASCADE, status text NOT NULL, note text, actor uuid, at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_state_registry ( state text PRIMARY KEY, seq int NOT NULL, label text NOT NULL, description text NOT NULL, entry_condition text NOT NULL, exit_condition text NOT NULL, revenue_treatment text NOT NULL DEFAULT 'none' CHECK (revenue_treatment IN ('none','pipeline','contracted','qualifying')), is_terminal boolean NOT NULL DEFAULT false, work_kind text, work_title text, sla_minutes int, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_whitespace_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL, service_code text NOT NULL, decision text NOT NULL CHECK (decision IN ('dismissed','pursued')), reason text, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, decided_by uuid NOT NULL DEFAULT auth.uid(), decided_at timestamptz NOT NULL DEFAULT now(), UNIQUE (account_id, service_code) );
CREATE TABLE IF NOT EXISTS public.commission_audit_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid, rule_id uuid, action text NOT NULL, actor uuid, old_value jsonb, new_value jsonb, reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commission_calculations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.revenue_events(id) ON DELETE CASCADE, driver_id uuid, driver_share_cents bigint NOT NULL CHECK (driver_share_cents >= 0), commission_cents bigint NOT NULL CHECK (commission_cents >= 0), commission_rate numeric(7,4), currency text NOT NULL DEFAULT 'KES', calculated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commission_schedules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, name text NOT NULL, version int NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_approval','approved','retired')), default_rate_percent numeric NOT NULL CHECK (default_rate_percent >= 0 AND default_rate_percent <= 100), min_rate_percent numeric CHECK (min_rate_percent IS NULL OR (min_rate_percent >= 0 AND min_rate_percent <= 100)), max_rate_percent numeric CHECK (max_rate_percent IS NULL OR (max_rate_percent >= 0 AND max_rate_percent <= 100)), default_basis text NOT NULL DEFAULT 'net_service_price' CHECK (default_basis IN ('base_fare','service_price','net_service_price', 'eligible_transaction_amount','completed_service_amount', 'collected_amount','gross_customer_total')), excluded_components jsonb NOT NULL DEFAULT '["tax","pass_through","surcharge"]'::jsonb, effective_from date, effective_to date, supersedes_id uuid REFERENCES public.commission_schedules(id), change_summary text, created_by uuid, approved_by uuid, approved_at timestamptz, published_by uuid, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.comms_access_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid, actor_email text, action text NOT NULL, account_id uuid, thread_id uuid, message_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.comms_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mailbox_address text NOT NULL UNIQUE, display_name text NOT NULL, provider public.comms_provider NOT NULL DEFAULT 'platform', department text, business_entity text, status text NOT NULL DEFAULT 'not_connected', credential_secret_ref text, sync_enabled boolean NOT NULL DEFAULT false, sync_cursor text, last_sync_at timestamptz, last_sync_status text, last_sync_error text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT comms_accounts_status_chk CHECK (status IN ('not_connected','connecting','connected','error','disabled')) );
CREATE TABLE IF NOT EXISTS public.comms_unified_readers ( staff_id uuid PRIMARY KEY REFERENCES public.staff_members(id) ON DELETE CASCADE, reason text NOT NULL, granted_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.company_collateral ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, slug text NOT NULL, title text NOT NULL, version text NOT NULL DEFAULT 'v1.0', description text, file_url text NOT NULL, file_size bigint, page_count integer, status text NOT NULL DEFAULT 'draft', published_at timestamptz, published_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT company_collateral_status_chk CHECK (status IN ('draft','published','superseded')), CONSTRAINT company_collateral_slug_version_key UNIQUE (slug, version) );
CREATE TABLE IF NOT EXISTS public.compliance_country_rules ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), country_code TEXT NOT NULL, rule_key TEXT NOT NULL, rule_value JSONB NOT NULL, applies_to TEXT NOT NULL, is_blocking BOOLEAN NOT NULL DEFAULT true, source_ref TEXT, effective_from DATE, is_active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(country_code, rule_key, applies_to) );
CREATE TABLE IF NOT EXISTS public.compliance_escalations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_id uuid, driver_id uuid, level int NOT NULL DEFAULT 1, escalated_to uuid, reason text, status text NOT NULL DEFAULT 'OPEN', due_at timestamptz, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.compliance_jobs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_code text NOT NULL, scope text NOT NULL, status text NOT NULL DEFAULT 'PENDING', scanned_count int DEFAULT 0, alert_count int DEFAULT 0, action_count int DEFAULT 0, started_at timestamptz, completed_at timestamptz, error_message text, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.concierge_approval_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid, reference text NOT NULL, event text NOT NULL, from_status text, to_status text, actor_id uuid, actor_email text, corporate_id uuid, amount_kes numeric, clauses jsonb NOT NULL DEFAULT '[]'::jsonb, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.consent_records ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, purpose TEXT NOT NULL, granted BOOLEAN NOT NULL, granted_at TIMESTAMPTZ NOT NULL DEFAULT now(), withdrawn_at TIMESTAMPTZ, source TEXT, policy_version TEXT, ip_address INET, user_agent TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contact_audit_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid, action text NOT NULL, old_status text, new_status text, old_is_spam boolean, new_is_spam boolean, actor_id uuid, actor_email text, detail jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contact_rate_limits ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, ip_address TEXT NOT NULL, window_start TIMESTAMPTZ NOT NULL DEFAULT now(), count INTEGER NOT NULL DEFAULT 1, last_submission_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contact_submissions ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, company TEXT, phone TEXT, type TEXT NOT NULL DEFAULT 'contact', subject TEXT, message TEXT NOT NULL, source_page TEXT, employee_count TEXT, status TEXT NOT NULL DEFAULT 'new', ip_address TEXT, user_agent TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.control_tower_alert_rules ( rule_key text PRIMARY KEY, condition_kind text NOT NULL, label text NOT NULL, description text, severity text NOT NULL DEFAULT 'warning' CHECK (severity IN ('info','warning','critical')), enabled boolean NOT NULL DEFAULT true, threshold_numeric numeric, window_minutes integer NOT NULL DEFAULT 60 CHECK (window_minutes > 0), owner_role text NOT NULL DEFAULT 'operations_admin', escalate_after_minutes integer, channels text[] NOT NULL DEFAULT ARRAY['control_tower']::text[], updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.control_tower_commands ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id text NOT NULL, correlation_id text NOT NULL, operation text NOT NULL, entity_type text, entity_id uuid, tenant_id uuid, actor_id uuid, permission_required text, outcome text NOT NULL CHECK (outcome IN ('APPLIED','REJECTED','FAILED')), error_code text, error_message text, latency_ms integer, payload jsonb NOT NULL DEFAULT '{}'::jsonb, result jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.control_tower_settings ( setting_key text PRIMARY KEY, label text NOT NULL, category text NOT NULL DEFAULT 'operations', value jsonb NOT NULL, state text NOT NULL DEFAULT 'SET' CHECK (state IN ('SET','OWNER_CONFIGURATION_REQUIRED')), guidance text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.control_tower_sla_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope_kind text NOT NULL CHECK (scope_kind IN ('global','service','customer','contract')), scope_value text, label text NOT NULL, target_minutes integer NOT NULL CHECK (target_minutes > 0), warning_threshold_pct numeric NOT NULL DEFAULT 70 CHECK (warning_threshold_pct BETWEEN 1 AND 100), critical_threshold_pct numeric NOT NULL DEFAULT 90 CHECK (critical_threshold_pct BETWEEN 1 AND 100), breach_grace_minutes integer NOT NULL DEFAULT 0 CHECK (breach_grace_minutes >= 0), stop_overdue_minutes integer NOT NULL DEFAULT 30 CHECK (stop_overdue_minutes > 0), active boolean NOT NULL DEFAULT true, notes text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ct_sla_scope_value_required CHECK (scope_kind = 'global' OR scope_value IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.country_governance_contacts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), country_code TEXT NOT NULL, regulator TEXT NOT NULL, contact_name TEXT, contact_role TEXT, email TEXT, phone TEXT, response_sla_hours INTEGER, escalation_path TEXT, is_primary BOOLEAN NOT NULL DEFAULT false, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.country_launch_status ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), country_code TEXT NOT NULL UNIQUE, country_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', launch_date DATE, primary_city TEXT, active_cities TEXT[], services_enabled TEXT[], notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.cta_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), button_name TEXT NOT NULL, action_type TEXT NOT NULL, target TEXT, page_source TEXT, campaign_source TEXT, utm_source TEXT, utm_medium TEXT, utm_campaign TEXT, user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, user_role TEXT, session_id TEXT, clicked_at TIMESTAMPTZ NOT NULL DEFAULT now(), converted BOOLEAN NOT NULL DEFAULT false, converted_at TIMESTAMPTZ, conversion_value NUMERIC, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.customer_document_confirmations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_kind text NOT NULL CHECK (document_kind IN ('invoice','proforma','receipt')), document_id uuid NOT NULL, document_no text, confirmed_by_user_id uuid NOT NULL, confirmed_email text, note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (document_kind, document_id, confirmed_by_user_id) );
CREATE TABLE IF NOT EXISTS public.dashboard_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dashboard_key text NOT NULL, metric_key text NOT NULL, display_label text NOT NULL, value numeric(20,4), unit text, trend numeric(8,4), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now(), UNIQUE (dashboard_key, metric_key));
CREATE TABLE IF NOT EXISTS public.dashboard_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dashboard_key text NOT NULL, snapshot jsonb NOT NULL, taken_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.data_classifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), schema_name TEXT NOT NULL, table_name TEXT NOT NULL, column_name TEXT, classification public.data_classification_level NOT NULL, pii BOOLEAN NOT NULL DEFAULT false, notes TEXT, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(schema_name, table_name, column_name) );
CREATE TABLE IF NOT EXISTS public.data_quality_findings ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id UUID, finding_kind TEXT NOT NULL, subject_table TEXT NOT NULL, subject_id TEXT NOT NULL, root_cause_category TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.digital_signatures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_kind text NOT NULL, subject_id uuid NOT NULL, algorithm text NOT NULL DEFAULT 'sha256', key_id text, signature bytea NOT NULL, signed_at timestamptz NOT NULL DEFAULT now(), signed_by uuid );
CREATE TABLE IF NOT EXISTS public.digital_twin_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), scale TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'seed', status TEXT NOT NULL DEFAULT 'running', triggered_by UUID REFERENCES auth.users(id), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ, duration_ms INTEGER, domains_completed TEXT[] NOT NULL DEFAULT '{}', rows_by_domain JSONB NOT NULL DEFAULT '{}'::jsonb, rows_by_table JSONB NOT NULL DEFAULT '{}'::jsonb, validation JSONB NOT NULL DEFAULT '{}'::jsonb, readiness_score INTEGER, error TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.disaster_recovery_tests ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), test_name TEXT NOT NULL, scenario TEXT NOT NULL, scheduled_for TIMESTAMPTZ, executed_at TIMESTAMPTZ, rto_target_minutes INT, rpo_target_minutes INT, rto_actual_minutes INT, rpo_actual_minutes INT, passed BOOLEAN, findings TEXT, conducted_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_number_sequences ( domain_code text NOT NULL, class_code text NOT NULL, year int NOT NULL, last_seq bigint NOT NULL DEFAULT 0, PRIMARY KEY (domain_code, class_code, year) );
CREATE TABLE IF NOT EXISTS public.doc_security_profiles ( code text PRIMARY KEY, label text NOT NULL, watermark_text text NOT NULL, watermark_placement text NOT NULL DEFAULT 'DIAGONAL', watermark_opacity numeric NOT NULL DEFAULT 0.12, seal_enabled boolean NOT NULL DEFAULT true, seal_opacity numeric NOT NULL DEFAULT 0.14, qr_enabled boolean NOT NULL DEFAULT false, recipient_binding boolean NOT NULL DEFAULT false, microtext_enabled boolean NOT NULL DEFAULT true, footer_opacity numeric NOT NULL DEFAULT 0.55, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_signing_keys ( key_id text PRIMARY KEY, algorithm text NOT NULL DEFAULT 'ed25519', public_key_pem text NOT NULL, provider text NOT NULL DEFAULT 'server_kms' CHECK (provider IN ('server_kms','development')), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired','compromised')), trusted boolean NOT NULL DEFAULT true, activated_at timestamptz NOT NULL DEFAULT now(), retired_at timestamptz, note text );
CREATE TABLE IF NOT EXISTS public.doc_source_systems ( code text PRIMARY KEY, label text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, kind text NOT NULL CHECK (kind IN ('CONTRACT','RATE_CARD','INVOICE','QUOTATION','SERVICE_ORDER','SCHEDULE','OTHER')), description text, owner_domain text NOT NULL DEFAULT 'commercial', legal_entity text NOT NULL DEFAULT 'Yalla Beena Limited (Trading as Yalla Mobility)', jurisdiction text NOT NULL DEFAULT 'Republic of Kenya', classification text NOT NULL DEFAULT 'PRIVATE & CONFIDENTIAL', source_reference text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.document_anomalies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL, document_table text NOT NULL, anomaly_type text NOT NULL, severity public.security_severity NOT NULL DEFAULT 'MEDIUM', details jsonb NOT NULL DEFAULT '{}'::jsonb, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.document_expiry_monitor ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_document_id UUID REFERENCES public.driver_documents(id) ON DELETE CASCADE, vehicle_document_id UUID, days_to_expiry INT NOT NULL, channel TEXT NOT NULL, notified_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'sent' );
CREATE TABLE IF NOT EXISTS public.document_review_assignments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), queue_id uuid NOT NULL, reviewer_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, assigned_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, assigned_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, status text NOT NULL DEFAULT 'active', notes text );
CREATE TABLE IF NOT EXISTS public.document_review_queue ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID REFERENCES public.drivers(id) ON DELETE CASCADE, driver_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, document_type TEXT NOT NULL, kyc_stage TEXT NOT NULL DEFAULT 'initial' CHECK (kyc_stage IN ('initial','enhanced','renewal','periodic_review','reverification')), status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('draft','submitted','pending_review','under_investigation','approved','rejected','expired','suspended','fraud_review','resubmission_required')), priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','critical')), file_url TEXT, file_meta JSONB DEFAULT '{}'::jsonb, ocr_payload JSONB DEFAULT '{}'::jsonb, ai_flags JSONB DEFAULT '[]'::jsonb, assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, assigned_at TIMESTAMPTZ, submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), decided_at TIMESTAMPTZ, decided_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, decision_reason TEXT, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.document_verification_queue ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_document_id UUID REFERENCES public.driver_documents(id) ON DELETE CASCADE, vehicle_document_id UUID, review_status TEXT NOT NULL DEFAULT 'pending', assigned_admin UUID, priority INT NOT NULL DEFAULT 3, review_notes TEXT, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.edge_function_invocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL, correlation_id uuid, function_name text NOT NULL, user_id uuid, method text, status_code int NOT NULL, latency_ms int NOT NULL, error_code text, error_message text, ip text, user_agent text, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.edge_function_registry ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), function_name TEXT NOT NULL UNIQUE, version TEXT, git_sha TEXT, deployment_id TEXT, deployed_at TIMESTAMPTZ, first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_invocation_at TIMESTAMPTZ, last_success_at TIMESTAMPTZ, last_failure_at TIMESTAMPTZ, invocation_count BIGINT NOT NULL DEFAULT 0, success_count BIGINT NOT NULL DEFAULT 0, failure_count BIGINT NOT NULL DEFAULT 0, avg_latency_ms NUMERIC, health_status TEXT NOT NULL DEFAULT 'unknown', owner_team TEXT, workflow_membership TEXT[] DEFAULT '{}', metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_category_prefs ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, email TEXT NOT NULL, category TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, updated_by UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE (email, category), CONSTRAINT email_category_prefs_optional_only CHECK (category IN ('operational','marketing','reports','internal')) );
CREATE TABLE IF NOT EXISTS public.email_dead_letters ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, queue TEXT NOT NULL, message_id TEXT, template_name TEXT, recipient_email TEXT, route TEXT, attempts INTEGER NOT NULL DEFAULT 0, payload JSONB NOT NULL DEFAULT '{}'::jsonb, reason TEXT, status TEXT NOT NULL DEFAULT 'pending', reprocessed_at TIMESTAMPTZ, reprocessed_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_domain_auth_checks ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, domain TEXT NOT NULL, spf_present BOOLEAN NOT NULL DEFAULT false, spf_record TEXT, dkim_present BOOLEAN NOT NULL DEFAULT false, dkim_selector TEXT, dmarc_present BOOLEAN NOT NULL DEFAULT false, dmarc_policy TEXT, mx_present BOOLEAN NOT NULL DEFAULT false, readiness_score INTEGER NOT NULL DEFAULT 0, findings JSONB NOT NULL DEFAULT '[]'::jsonb, checked_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_domain_migration_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), migrated_at timestamptz NOT NULL DEFAULT now(), target_table text NOT NULL, target_column text NOT NULL, old_value text NOT NULL, new_value text NOT NULL, classification text NOT NULL, reason text NOT NULL DEFAULT 'Retire yallabeena.info; authoritative domain is yalla.africa' );
CREATE TABLE IF NOT EXISTS public.email_send_log ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), message_id TEXT, template_name TEXT NOT NULL, recipient_email TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'sent', 'suppressed', 'failed', 'bounced', 'complained', 'dlq')), error_message TEXT, metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_send_state ( id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1), retry_after_until TIMESTAMPTZ, batch_size INTEGER NOT NULL DEFAULT 10, send_delay_ms INTEGER NOT NULL DEFAULT 200, auth_email_ttl_minutes INTEGER NOT NULL DEFAULT 15, transactional_email_ttl_minutes INTEGER NOT NULL DEFAULT 60, updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_templates ( name TEXT NOT NULL PRIMARY KEY, display_name TEXT NOT NULL, description TEXT, active_version INTEGER, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_unsubscribe_tokens ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), token TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), used_at TIMESTAMPTZ );
CREATE TABLE IF NOT EXISTS public.error_tracking (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_code text, error_type text NOT NULL, message text NOT NULL, stack text, user_id uuid, context jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.etims_retry_queue ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL UNIQUE REFERENCES public.etims_invoices(id) ON DELETE CASCADE, attempt int NOT NULL DEFAULT 0, max_attempts int NOT NULL DEFAULT 12, next_retry_at timestamptz NOT NULL DEFAULT now(), last_attempt_at timestamptz, last_error text, abandoned boolean NOT NULL DEFAULT false, abandoned_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.etims_sync_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.etims_invoices(id) ON DELETE CASCADE, event_type public.etims_sync_event_type NOT NULL, attempt_number int NOT NULL DEFAULT 1, request_payload jsonb, response_status int, response_payload jsonb, duration_ms int, error_code text, error_message text, actor_id uuid, actor_type text NOT NULL DEFAULT 'service', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.etims_webhooks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid REFERENCES public.etims_invoices(id) ON DELETE SET NULL, source text NOT NULL DEFAULT 'TAX_KE', event_type text NOT NULL, raw_headers jsonb NOT NULL DEFAULT '{}'::jsonb, raw_payload jsonb NOT NULL, signature text, signature_verified boolean NOT NULL DEFAULT false, processed boolean NOT NULL DEFAULT false, processed_at timestamptz, processing_error text, remote_address text, received_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.etl_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_name text NOT NULL, status text NOT NULL DEFAULT 'PENDING', started_at timestamptz, finished_at timestamptz, rows_processed bigint, error text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.event_outbox_dlq ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL, event_type text NOT NULL, aggregate text, aggregate_id uuid, correlation_id text, trace_id text, span_id text, parent_span_id text, idempotency_key text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, payload_hash text, retry_count integer NOT NULL DEFAULT 0, retry_history jsonb NOT NULL DEFAULT '[]'::jsonb, failure_reason text, stack_trace text, poisoned boolean NOT NULL DEFAULT false, expired boolean NOT NULL DEFAULT false, environment text NOT NULL DEFAULT 'production', deployment_version text, git_revision text, resolution_status text NOT NULL DEFAULT 'pending' CHECK (resolution_status IN ('pending','acknowledged','replayed','discarded')), resolved_by uuid, resolved_at timestamptz, resolution_notes text, created_at timestamptz NOT NULL DEFAULT now(), last_retry_at timestamptz );
CREATE TABLE IF NOT EXISTS public.event_outbox_dlq_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dlq_id uuid NOT NULL, action text NOT NULL CHECK (action IN ('replay','retry','discard','quarantine','bulk_replay')), reason text, actor_user_id uuid, actor_role text, correlation_id text, outcome text NOT NULL DEFAULT 'accepted', details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamp with time zone NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.event_processing_metrics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), consumer_id uuid REFERENCES public.event_consumers(id) ON DELETE CASCADE, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, events_processed bigint NOT NULL DEFAULT 0, events_dropped bigint NOT NULL DEFAULT 0, events_retried bigint NOT NULL DEFAULT 0, avg_lag_ms int NOT NULL DEFAULT 0, max_lag_ms int NOT NULL DEFAULT 0, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.event_registry ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_name text NOT NULL UNIQUE, event_category text NOT NULL, source_service text NOT NULL, schema_version int NOT NULL DEFAULT 1, retention_days int NOT NULL DEFAULT 3650, description text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, tenant_id uuid, region_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.event_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, version bigint NOT NULL, state jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(aggregate_type, aggregate_id, version) );
CREATE TABLE IF NOT EXISTS public.event_streams ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(aggregate_type, aggregate_id) );
CREATE TABLE IF NOT EXISTS public.event_subscription_health ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stream text NOT NULL, channel_name text NOT NULL, status text NOT NULL CHECK (status IN ('connected','disconnected','error','timeout','reconnecting')), last_event_at timestamptz, last_error text, latency_ms integer, user_id uuid REFERENCES auth.users(id), session_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.executive_alert_history ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_key text NOT NULL, kind text NOT NULL, severity text NOT NULL, title text NOT NULL, message text NOT NULL, metric_key text, value numeric, integration_key text, channels jsonb NOT NULL DEFAULT '[]'::jsonb, incident_ref text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.executive_alert_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, stream text NOT NULL CHECK (stream IN ('trip','driver','finance')), metric_key text NOT NULL, operator text NOT NULL CHECK (operator IN ('gt','gte','lt','lte','eq','anomaly')), threshold numeric, window_seconds integer NOT NULL DEFAULT 300, severity text NOT NULL DEFAULT 'warning' CHECK (severity IN ('info','warning','critical')), enabled boolean NOT NULL DEFAULT true, notify_toast boolean NOT NULL DEFAULT true, cooldown_seconds integer NOT NULL DEFAULT 60, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.executive_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), severity text NOT NULL DEFAULT 'info', category text NOT NULL, title text NOT NULL, body text, resource_url text, acknowledged_at timestamptz, acknowledged_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.executive_forecasts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), forecast_key text NOT NULL, horizon text NOT NULL, value_numeric numeric, confidence numeric, model_name text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, generated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.executive_metrics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metric_key text NOT NULL, label text NOT NULL, value_numeric numeric, value_text text, unit text, trend_pct numeric, category text NOT NULL DEFAULT 'revenue', region text, tenant_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, measured_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (metric_key, region, tenant_id) );
CREATE TABLE IF NOT EXISTS public.export_audit_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, actor_email text, dataset text NOT NULL, export_type text NOT NULL CHECK (export_type IN ('pdf','csv','json','xlsx','zip')), row_count integer, byte_size bigint, ip_address inet, user_agent text, filters jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'success' CHECK (status IN ('success','failed','partial')), error text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fact_compliance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), snapshot_date date NOT NULL UNIQUE, total_drivers int NOT NULL DEFAULT 0, compliant_drivers int NOT NULL DEFAULT 0, expired_documents int NOT NULL DEFAULT 0, open_alerts int NOT NULL DEFAULT 0, open_incidents int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.failover_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_name TEXT NOT NULL, from_region TEXT, to_region TEXT, triggered_by TEXT NOT NULL, initiator UUID REFERENCES auth.users(id) ON DELETE SET NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, duration_seconds INT, successful BOOLEAN, notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.file_access_logs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, bucket TEXT NOT NULL, object_path TEXT NOT NULL, action TEXT NOT NULL, ip_address INET, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fin_cert_callbacks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), checkout_request_id text NOT NULL, merchant_request_id text, result_code integer, result_desc text, amount numeric, mpesa_receipt text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, source text NOT NULL DEFAULT 'daraja_sandbox', received_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.financial_autoapproval_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_by uuid, dry_run boolean NOT NULL DEFAULT true, threshold numeric(5,2) NOT NULL DEFAULT 85, scanned integer NOT NULL DEFAULT 0, auto_approved integer NOT NULL DEFAULT 0, left_for_review integer NOT NULL DEFAULT 0, report jsonb NOT NULL DEFAULT '{}'::jsonb, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz );
CREATE TABLE IF NOT EXISTS public.financial_risk_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), entity_type public.risk_entity_type NOT NULL, entity_id UUID, event_type TEXT NOT NULL, severity public.risk_event_severity NOT NULL DEFAULT 'medium', amount NUMERIC(14,2), currency TEXT DEFAULT 'KES', source TEXT NOT NULL, source_ref UUID, signal_data JSONB NOT NULL DEFAULT '{}'::JSONB, score NUMERIC(5,2), detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.forbidden_update_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), occurred_at timestamptz NOT NULL DEFAULT now(), actor_user_id uuid, target_table text NOT NULL, target_row_id text, attempted_columns text[] NOT NULL DEFAULT '{}', reason text NOT NULL, ip_address inet, user_agent text, request_path text );
CREATE TABLE IF NOT EXISTS public.fraud_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, status public.fraud_case_status NOT NULL DEFAULT 'OPEN', severity public.security_severity NOT NULL DEFAULT 'MEDIUM', score numeric(6,2), summary text, assigned_to uuid, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, resolution text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fraud_engine_traces ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id uuid NOT NULL, payment_attempt_id uuid, user_id uuid, decision text NOT NULL, score int NOT NULL, rules_fired jsonb NOT NULL DEFAULT '[]'::jsonb, latency_ms int, error_message text, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fraud_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_code text UNIQUE NOT NULL, name text NOT NULL, description text, signal_type text NOT NULL, weight numeric(5,2) NOT NULL DEFAULT 1.0, severity public.security_severity NOT NULL DEFAULT 'MEDIUM', active boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fraud_signals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, transaction_id uuid REFERENCES public.mpesa_transactions(id), kind public.fraud_signal_kind NOT NULL, score numeric(6,3) NOT NULL DEFAULT 0, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fx_revaluations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_end date NOT NULL, base_currency text NOT NULL DEFAULT 'KES' REFERENCES public.currencies(code), status text NOT NULL DEFAULT 'RUNNING' CHECK (status IN ('RUNNING','COMPLETED','FAILED')), journal_id uuid REFERENCES public.journals(id), totals jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.geo_anomalies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, prev_country text, current_country text, prev_lat numeric, prev_lng numeric, cur_lat numeric, cur_lng numeric, distance_km numeric, velocity_kmh numeric, flagged boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.governance_access_grants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), surface text NOT NULL CHECK (surface IN ('alert_history','concierge_audit','report_schedules','incident_detail','webhook_admin')), corporate_id uuid REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, corporate_role text CHECK (corporate_role IN ('corporate_admin','corporate_manager','corporate_employee')), department_id uuid REFERENCES public.corporate_departments(id) ON DELETE CASCADE, user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, can_read boolean NOT NULL DEFAULT true, can_export boolean NOT NULL DEFAULT false, can_manage boolean NOT NULL DEFAULT false, note text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.governance_webhook_replay_guard ( nonce text PRIMARY KEY, endpoint_id uuid REFERENCES public.governance_webhook_endpoints(id) ON DELETE CASCADE, seen_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.idempotency_keys ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL, key text NOT NULL, user_id uuid, request_hash text, status text NOT NULL DEFAULT 'IN_FLIGHT' CHECK (status IN ('IN_FLIGHT','SUCCEEDED','FAILED')), response jsonb, http_status int, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'), UNIQUE (scope, key) );
CREATE TABLE IF NOT EXISTS public.identity_controls ( control_code text PRIMARY KEY, domain text NOT NULL, title text NOT NULL, requirement text NOT NULL, evidence_kind text NOT NULL, severity text NOT NULL CHECK (severity IN ('P0','P1','P2','P3')), mandatory boolean NOT NULL DEFAULT true, note text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.identity_recovery_rate ( bucket text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT date_trunc('hour', now()), hits integer NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS public.identity_recovery_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email_hash text NOT NULL, email_domain text, outcome text NOT NULL CHECK (outcome IN ('ACCEPTED','RATE_LIMITED','INVALID_EMAIL')), correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.incentive_programs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, category_slug text REFERENCES public.ride_categories(slug) ON DELETE SET NULL, city text, trigger_type text NOT NULL CHECK (trigger_type IN ('trips_count','hours_online','peak_window','streak','rating')), threshold numeric(10,2) NOT NULL, reward_kes numeric(10,2) NOT NULL, window_start timestamptz, window_end timestamptz, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_environment_credentials ( environment_key text PRIMARY KEY, secret_name text NOT NULL, dsn_ciphertext text NOT NULL, dsn_iv text NOT NULL, dsn_sha256 text NOT NULL, host_ref text, database_ref text, key_version integer NOT NULL DEFAULT 1, configured_by uuid, configured_at timestamptz NOT NULL DEFAULT now(), rotated_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT infra_cred_environment_key CHECK (environment_key IN ('logistics-staging','logistics-restore')), CONSTRAINT infra_cred_ciphertext_not_plaintext CHECK (dsn_ciphertext !~ '(?i)(postgres(ql)?://|password=)') );
CREATE TABLE IF NOT EXISTS public.infra_fixture_sets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment_id uuid NOT NULL REFERENCES public.infra_environments(id) ON DELETE CASCADE, fixture_set_key text NOT NULL, scenario text NOT NULL, synthetic boolean NOT NULL DEFAULT true, deterministic_seed text NOT NULL, entity_counts jsonb NOT NULL DEFAULT '{}'::jsonb, production_identifier_scan public.infra_check_result NOT NULL DEFAULT 'UNKNOWN', loaded_at timestamptz, state public.infra_job_state NOT NULL DEFAULT 'REQUESTED', error_message text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (environment_id, fixture_set_key), CONSTRAINT infra_fixtures_are_synthetic CHECK (synthetic) );
CREATE TABLE IF NOT EXISTS public.infra_health_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment_id uuid NOT NULL REFERENCES public.infra_environments(id) ON DELETE CASCADE, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, request_id text NOT NULL DEFAULT gen_random_uuid()::text, actor_id uuid, system_actor text, state public.infra_job_state NOT NULL DEFAULT 'REQUESTED', overall_result public.infra_check_result NOT NULL DEFAULT 'UNKNOWN', started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, duration_ms integer, error_code text, error_message text, summary jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_independence_assertions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), result text NOT NULL CHECK (result IN ('PASS','FAIL','BLOCKED','UNKNOWN','NOT_CONFIGURED')), staging_identity_sha256 text, restore_identity_sha256 text, invariants jsonb NOT NULL DEFAULT '[]'::jsonb, failed_invariants text[] NOT NULL DEFAULT ARRAY[]::text[], detail jsonb NOT NULL DEFAULT '{}'::jsonb, correlation_id uuid, request_id uuid, asserted_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_operations_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation text NOT NULL, environment_key text, actor_id uuid, system_actor text, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, request_id text NOT NULL DEFAULT gen_random_uuid()::text, status text NOT NULL, error_code text, duration_ms integer, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_orchestration_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_reference text NOT NULL UNIQUE, trigger_source text NOT NULL CHECK (trigger_source IN ('CREDENTIAL_SAVED','MANUAL','RESUME','AUTO_RETRY','SCHEDULED')), environment_scope text[] NOT NULL DEFAULT ARRAY[]::text[], idempotency_key text NOT NULL UNIQUE, state text NOT NULL DEFAULT 'RUNNING' CHECK (state IN ('RUNNING','SUCCEEDED','PARTIAL','FAILED','BLOCKED','CANCELLED')), resumed_from_step text, blocked_step text, blocked_reason text, summary jsonb NOT NULL DEFAULT '{}'::jsonb, requested_by uuid, correlation_id uuid, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, duration_ms integer );
CREATE TABLE IF NOT EXISTS public.intern_academic_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL UNIQUE REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid REFERENCES public.rec_candidates(id) ON DELETE CASCADE, qualification_level text NOT NULL, programme text NOT NULL, institution text NOT NULL, institution_type text, specialisation text, curriculum_version text, curriculum_source_id uuid REFERENCES public.intern_curriculum_sources(id) ON DELETE SET NULL, year_of_study integer, semester integer, academic_stage text, relevant_courses text[] NOT NULL DEFAULT '{}', attachment_done boolean NOT NULL DEFAULT false, attachment_detail text, projects text[] NOT NULL DEFAULT '{}', skills text[] NOT NULL DEFAULT '{}', portfolio_url text, work_experience text, learning_objectives text[] NOT NULL DEFAULT '{}', expected_outcomes text[] NOT NULL DEFAULT '{}', validated_by uuid, validated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_audit_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid REFERENCES public.intern_profiles(id) ON DELETE SET NULL, actor_id uuid, action text NOT NULL, entity text NOT NULL, entity_id uuid, before_state jsonb, after_state jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_candidate_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, competency text NOT NULL, evidence_kind text NOT NULL, where_learned text, where_applied text, produced text, evidence_url text, classification text NOT NULL DEFAULT 'CLAIMED', reviewed_by uuid, reviewed_at timestamptz, verified_by uuid, verified_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT evidence_classification_ck CHECK (classification IN ('CLAIMED','UPLOADED','REVIEWED','ASSESSED','VERIFIED')) );
CREATE TABLE IF NOT EXISTS public.intern_capstones ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, title text NOT NULL, problem text, baseline text, research text, solution text, execution_summary text, evidence_url text, measured_impact text, recommendation text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','under_review','scored','returned')), score_problem numeric(5,2), score_research numeric(5,2), score_solution numeric(5,2), score_execution numeric(5,2), score_impact numeric(5,2), score_presentation numeric(5,2), score_reflection numeric(5,2), total_score numeric(5,2), scored_by uuid, scored_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_commercial_attributions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, attribution_type text NOT NULL CHECK (attribution_type IN ( 'LEAD_CREATED','LEAD_QUALIFIED','OPPORTUNITY_CREATED','SALES_ASSIST', 'BOOKING_ASSIST','CONVERSION_ASSIST','REVENUE_ATTRIBUTED')), channel text, product_line text, subject_ref text, subject_id uuid, amount_kes numeric(14,2), source_system text NOT NULL DEFAULT 'manual', verified boolean NOT NULL DEFAULT false, verified_by uuid, verified_at timestamptz, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_conversion_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, recommended_outcome text NOT NULL, decision text CHECK (decision IS NULL OR decision IN ('APPROVED','DECLINED','DEFERRED')), outcome text, rationale text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, recommended_by uuid, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_integrity_flags ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, signal text NOT NULL, severity text NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high')), detail jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'REVIEW_REQUIRED' CHECK (status IN ('REVIEW_REQUIRED','CLEARED','SUBSTANTIATED')), reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_performance_scores ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, learning_score numeric(5,2) NOT NULL DEFAULT 0, productivity_score numeric(5,2) NOT NULL DEFAULT 0, quality_score numeric(5,2) NOT NULL DEFAULT 0, commercial_score numeric(5,2) NOT NULL DEFAULT 0, operational_score numeric(5,2) NOT NULL DEFAULT 0, conduct_score numeric(5,2) NOT NULL DEFAULT 0, performance_index numeric(5,2) NOT NULL DEFAULT 0, evidence_confidence numeric(5,2) NOT NULL DEFAULT 0, breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now(), computed_by uuid, UNIQUE (intern_id, period_start, period_end) );
CREATE TABLE IF NOT EXISTS public.intern_public_application_links ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL UNIQUE, pipeline_id uuid NOT NULL, vacancy_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, reviewer_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, reviewer_user_id uuid, review_type text NOT NULL DEFAULT 'weekly' CHECK (review_type IN ('weekly','monthly','midpoint','final','coaching')), period_label text, strengths text, concerns text, coaching text, subjective_rating int CHECK (subjective_rating IS NULL OR subjective_rating BETWEEN 1 AND 5), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_skills ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, category text NOT NULL, skill text NOT NULL, classification text NOT NULL DEFAULT 'developmental' CHECK (classification IN ('required','preferred','developmental')), level int NOT NULL DEFAULT 1 CHECK (level BETWEEN 0 AND 5), evidence text, source text, confidence numeric(5,2) NOT NULL DEFAULT 50 CHECK (confidence BETWEEN 0 AND 100), assessed_by uuid, last_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (intern_id, skill) );
CREATE TABLE IF NOT EXISTS public.intern_supply_destinations ( id uuid primary key default gen_random_uuid(), intern_id uuid not null references public.intern_profiles(id) on delete cascade, cohort_id uuid references public.intern_cohorts(id) on delete set null, destination_name text not null, destination_type text not null, location text, customer_segments text[] not null default '{}', demand_status text not null default 'UNVERIFIED' check (demand_status in ('UNVERIFIED','INDICATIVE','VERIFIED')), demand_hypothesis text, demand_evidence text, mobility_requirements text, vehicle_categories text[] not null default '{}', driver_requirements text, fleet_requirements text, yalla_products text[] not null default '{}', supplier_pipeline text, activation_strategy text, operational_risks text, completeness numeric not null default 0 check (completeness between 0 and 100), status text not null default 'DRAFT' check (status in ('DRAFT','SUBMITTED','ACCEPTED','RETURNED','COMPLETE')), reviewed_by uuid, reviewed_at timestamptz, evidence_url text, is_demo boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.intern_supply_field_assignments ( id uuid primary key default gen_random_uuid(), intern_id uuid not null references public.intern_profiles(id) on delete cascade, cohort_id uuid references public.intern_cohorts(id) on delete set null, assignment text not null, location text not null, scheduled_for date not null, objective text, contacts_made integer not null default 0 check (contacts_made >= 0), records_created integer not null default 0 check (records_created >= 0), outcomes text, follow_up text, evidence_url text, supervisor_verified boolean not null default false, verified_by uuid, verified_at timestamptz, is_demo boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.intern_work_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intern_id uuid NOT NULL REFERENCES public.intern_profiles(id) ON DELETE CASCADE, title text NOT NULL, description text, work_kind text NOT NULL DEFAULT 'task', priority text NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','critical')), status text NOT NULL DEFAULT 'ASSIGNED' CHECK (status IN ('BACKLOG','ASSIGNED','IN_PROGRESS','BLOCKED','SUBMITTED','UNDER_REVIEW','ACCEPTED','REWORK','COMPLETED')), deadline timestamptz, deliverable_url text, quality_criteria text, quality_score numeric(5,2) CHECK (quality_score IS NULL OR quality_score BETWEEN 0 AND 100), complexity int NOT NULL DEFAULT 2 CHECK (complexity BETWEEN 1 AND 5), impact int NOT NULL DEFAULT 2 CHECK (impact BETWEEN 1 AND 5), rework_count int NOT NULL DEFAULT 0, reviewer_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, submitted_at timestamptz, accepted_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.journey_health_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id uuid NOT NULL, payment_attempt_id uuid, score numeric(5,2) NOT NULL, grade text NOT NULL, breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.languages (code text PRIMARY KEY, name text NOT NULL, native_name text, rtl boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS public.legal_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, approval_type text NOT NULL, authority text NOT NULL, decision public.legal_review_outcome NOT NULL DEFAULT 'pending', conditions text[] NOT NULL DEFAULT '{}', rationale text, requested_by uuid, requested_at timestamptz NOT NULL DEFAULT now(), decided_by uuid, decided_at timestamptz, evidence_id uuid REFERENCES public.legal_evidence(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_compliance_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gate_stage text NOT NULL, requirement_code text NOT NULL, reason_code text NOT NULL, decision text NOT NULL, title text NOT NULL, detail text, service_family text, required_action text, owner_role text NOT NULL DEFAULT 'legal_counsel', severity text NOT NULL DEFAULT 'high', status text NOT NULL DEFAULT 'open', occurrences integer NOT NULL DEFAULT 1, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), last_transaction_ref text, last_correlation_id text, acknowledged_at timestamptz, acknowledged_by uuid, acknowledgement_note text, resolved_at timestamptz, resolved_by uuid, resolution_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT legal_compliance_alerts_status_chk CHECK (status IN ('open','acknowledged','resolved')), CONSTRAINT legal_compliance_alerts_severity_chk CHECK (severity IN ('low','medium','high','critical')) );
CREATE TABLE IF NOT EXISTS public.legal_compliance_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, subject_type text NOT NULL, subject_id uuid, subject_ref text, requirement_code text, gate_stage public.legal_gate_stage, decision text NOT NULL, reason_code text, shadow_mode boolean NOT NULL DEFAULT true, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_data_processing_records ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, activity text NOT NULL, data_controller text NOT NULL, data_processor text, processing_purpose text NOT NULL, lawful_basis text NOT NULL, data_categories text[] NOT NULL DEFAULT '{}', data_subjects text[] NOT NULL DEFAULT '{}', special_category boolean NOT NULL DEFAULT false, retention_period_days integer, deletion_rule text, access_roles text[] NOT NULL DEFAULT '{}', sharing_parties text[] NOT NULL DEFAULT '{}', cross_border_transfer boolean NOT NULL DEFAULT false, transfer_destinations text[] NOT NULL DEFAULT '{}', transfer_safeguard text, security_measures text[] NOT NULL DEFAULT '{}', dpia_required boolean NOT NULL DEFAULT false, dpia_completed_at timestamptz, owner_user_id uuid, status public.legal_status NOT NULL DEFAULT 'review_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_goods_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, goods_category text NOT NULL, goods_class public.legal_goods_class NOT NULL DEFAULT 'unknown', jurisdiction_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, service_families text[] NOT NULL DEFAULT '{}', conditions text[] NOT NULL DEFAULT '{}', required_evidence text[] NOT NULL DEFAULT '{}', max_declared_value numeric, keywords text[] NOT NULL DEFAULT '{}', legal_basis text, failure_action public.legal_failure_action NOT NULL DEFAULT 'manual_review', owner_user_id uuid, notes text, status public.legal_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_licences ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, jurisdiction_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, regulator_id uuid REFERENCES public.legal_regulators(id) ON DELETE SET NULL, holder_type text NOT NULL DEFAULT 'platform', holder_id uuid, holder_name text, licence_type text NOT NULL, licence_number text, issuer text, issue_date date, effective_from date, effective_until date, scope text, document_path text, verification_status public.legal_review_outcome NOT NULL DEFAULT 'pending', verified_by uuid, verified_at timestamptz, owner_user_id uuid, notes text, status public.legal_status NOT NULL DEFAULT 'evidence_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_obligations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, contract_id uuid REFERENCES public.legal_contracts(id) ON DELETE SET NULL, title text NOT NULL, description text, obligation_type text NOT NULL DEFAULT 'regulatory', frequency text, next_due_at timestamptz, last_completed_at timestamptz, owner_role text, owner_user_id uuid, escalation_role text, failure_action public.legal_failure_action NOT NULL DEFAULT 'manual_review', status public.legal_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_permits ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, jurisdiction_id uuid REFERENCES public.legal_jurisdictions(id) ON DELETE SET NULL, regulator_id uuid REFERENCES public.legal_regulators(id) ON DELETE SET NULL, holder_type text NOT NULL DEFAULT 'platform', holder_id uuid, holder_name text, permit_type text NOT NULL, permit_number text, issuer text, issue_date date, effective_from date, effective_until date, scope text, document_path text, verification_status public.legal_review_outcome NOT NULL DEFAULT 'pending', owner_user_id uuid, notes text, status public.legal_status NOT NULL DEFAULT 'evidence_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL, version text NOT NULL DEFAULT '1.0', title text NOT NULL, policy_type text NOT NULL, audience text NOT NULL DEFAULT 'customer', summary text, body text, document_path text, public_url text, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, effective_from date, effective_until date, approved_by uuid, approved_at timestamptz, owner_user_id uuid, status public.legal_status NOT NULL DEFAULT 'review_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.legal_protection_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_reference text NOT NULL, provider text NOT NULL, policy_number text, insured_entity text NOT NULL, insured_entity_id uuid, coverage_type text NOT NULL, territory text, limit_amount numeric, limit_currency text NOT NULL DEFAULT 'KES', per_consignment_limit numeric, deductible numeric, effective_from date, effective_until date, covered_goods text[] NOT NULL DEFAULT '{}', exclusions text[] NOT NULL DEFAULT '{}', document_path text, verification_status public.legal_review_outcome NOT NULL DEFAULT 'pending', verified_by uuid, verified_at timestamptz, owner_user_id uuid, status public.legal_status NOT NULL DEFAULT 'evidence_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid, requirement_id uuid REFERENCES public.legal_requirements(id) ON DELETE SET NULL, question text NOT NULL, context jsonb NOT NULL DEFAULT '{}'::jsonb, raised_by uuid, assigned_to uuid, assigned_role text, due_at timestamptz, outcome public.legal_review_outcome NOT NULL DEFAULT 'legal_review_required', determination text, determined_by uuid, determined_at timestamptz, evidence_id uuid REFERENCES public.legal_evidence(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_slas ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid REFERENCES public.legal_contracts(id) ON DELETE CASCADE, code text NOT NULL, service_family text, metric text NOT NULL, target_value numeric, target_unit text, measurement_method text, remedy text, is_guarantee boolean NOT NULL DEFAULT false, effective_from date, effective_until date, owner_user_id uuid, status public.legal_status NOT NULL DEFAULT 'review_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.lg_approver_role_map ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), approver_kind text NOT NULL CHECK (approver_kind IN ('legal_reviewer','insurer','owner')), role text NOT NULL, control_id text, allowed boolean NOT NULL DEFAULT true, notify boolean NOT NULL DEFAULT true, notes text, created_by uuid REFERENCES auth.users, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.lg_dossier_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_id text NOT NULL, document_id text NOT NULL, version integer NOT NULL, title text NOT NULL, folder_path text NOT NULL, file_name text NOT NULL, evidence_type text NOT NULL, provenance text NOT NULL, issuing_authority text NOT NULL, draft_state text NOT NULL, declaration text NOT NULL, sections jsonb NOT NULL DEFAULT '[]'::jsonb, authoritative_fields jsonb NOT NULL DEFAULT '[]'::jsonb, regulatory_references jsonb NOT NULL DEFAULT '[]'::jsonb, operational_linkage text NOT NULL, blocking_stages text[] NOT NULL DEFAULT ARRAY['booking','dispatch']::text[], requires_insurer_approval boolean NOT NULL DEFAULT false, body_markdown text NOT NULL, content_hash text NOT NULL, is_current boolean NOT NULL DEFAULT true, superseded_by uuid REFERENCES public.lg_dossier_documents(id), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT lg_dossier_version_positive CHECK (version >= 1), CONSTRAINT lg_dossier_draft_state_valid CHECK (draft_state IN ( 'LEGAL_REVIEW_REQUIRED','EVIDENCE_REQUIRED','INSURANCE_EVIDENCE_REQUIRED', 'REGULATOR_ACTION_REQUIRED','OWNER_APPROVAL_REQUIRED')), CONSTRAINT lg_dossier_control_version_unique UNIQUE (control_id, version) );
CREATE TABLE IF NOT EXISTS public.location_history (id uuid NOT NULL DEFAULT gen_random_uuid(), subject_id uuid NOT NULL, subject_type text NOT NULL, lat double precision NOT NULL, lng double precision NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), trip_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY (id, recorded_at));
CREATE TABLE IF NOT EXISTS public.location_integrity_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, driver_id UUID, trip_id UUID, fingerprint_hash TEXT, signal public.gps_integrity_signal NOT NULL, severity public.security_severity NOT NULL DEFAULT 'HIGH', detected_speed_kph NUMERIC(7,2), reported_lat NUMERIC(10,7), reported_lng NUMERIC(10,7), prior_lat NUMERIC(10,7), prior_lng NUMERIC(10,7), delta_meters NUMERIC(10,2), delta_seconds NUMERIC(10,2), evidence JSONB NOT NULL DEFAULT '{}'::JSONB, countermeasure TEXT, countermeasure_applied_at TIMESTAMPTZ, detected_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.login_risk_scores ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), auth_event_id UUID REFERENCES public.authentication_events(id) ON DELETE SET NULL, user_id UUID, fingerprint_hash TEXT, score NUMERIC(5,2) NOT NULL, band TEXT NOT NULL, factors JSONB NOT NULL DEFAULT '{}'::JSONB, decision TEXT NOT NULL, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.manifests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), manifest_number text NOT NULL UNIQUE DEFAULT 'MAN-' || upper(substring(replace(gen_random_uuid()::text,'-',''),1,10)), driver_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, module text NOT NULL, status text NOT NULL DEFAULT 'draft', total_packages integer NOT NULL DEFAULT 0, total_weight_kg numeric(10,3) NOT NULL DEFAULT 0, departed_at timestamptz, closed_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.marketplace_demand_snapshots ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, bucket_at TIMESTAMPTZ NOT NULL, ride_type TEXT, search_count INTEGER NOT NULL DEFAULT 0, request_count INTEGER NOT NULL DEFAULT 0, unfulfilled_count INTEGER NOT NULL DEFAULT 0, cancel_count INTEGER NOT NULL DEFAULT 0, avg_wait_seconds INTEGER, conversion_rate NUMERIC(5,4), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.marketplace_heatmap_tiles ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), layer TEXT NOT NULL, intensity NUMERIC(6,3) NOT NULL DEFAULT 0, color_hint TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb );
CREATE TABLE IF NOT EXISTS public.marketplace_supply_snapshots ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, bucket_at TIMESTAMPTZ NOT NULL, ride_type TEXT, available_drivers INTEGER NOT NULL DEFAULT 0, busy_drivers INTEGER NOT NULL DEFAULT 0, offline_drivers INTEGER NOT NULL DEFAULT 0, avg_eta_seconds INTEGER, utilization NUMERIC(5,4), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.meeting_host_availability ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), staff_id uuid NOT NULL REFERENCES public.staff_members(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('weekly','leave')), weekday int CHECK (weekday BETWEEN 0 AND 6), start_minute int CHECK (start_minute BETWEEN 0 AND 1440), end_minute int CHECK (end_minute BETWEEN 0 AND 1440), leave_from timestamptz, leave_to timestamptz, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((kind='weekly' AND weekday IS NOT NULL AND start_minute < end_minute) OR (kind='leave' AND leave_from < leave_to)) );
CREATE TABLE IF NOT EXISTS public.meeting_invitations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interview_id uuid NOT NULL REFERENCES public.rec_interviews(id) ON DELETE CASCADE, calendar_uid text NOT NULL, sequence integer NOT NULL DEFAULT 0, method text NOT NULL DEFAULT 'REQUEST', scheduled_at timestamptz NOT NULL, duration_minutes integer NOT NULL, mode text NOT NULL, meeting_link text, location text, organiser_email text NOT NULL, recipient_email text NOT NULL, cc_emails text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'sent', provider_message_id text, failure_reason text, sent_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT meeting_invitations_method_chk CHECK (method IN ('REQUEST','CANCEL')), CONSTRAINT meeting_invitations_status_chk CHECK (status IN ('sent','failed')) );
CREATE TABLE IF NOT EXISTS public.meeting_types ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, description text, department text, duration_minutes int NOT NULL DEFAULT 30 CHECK (duration_minutes BETWEEN 15 AND 180), buffer_minutes int NOT NULL DEFAULT 10 CHECK (buffer_minutes BETWEEN 0 AND 60), min_notice_hours int NOT NULL DEFAULT 2 CHECK (min_notice_hours BETWEEN 0 AND 168), max_advance_days int NOT NULL DEFAULT 30 CHECK (max_advance_days BETWEEN 1 AND 180), requires_meet boolean NOT NULL DEFAULT true, is_public boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true, sort_order int NOT NULL DEFAULT 100, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_drift_metrics ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), model_id UUID REFERENCES public.ml_model_registry(id) ON DELETE CASCADE, feature_name TEXT, metric_type TEXT NOT NULL, metric_value NUMERIC NOT NULL, threshold NUMERIC, is_drift_detected BOOLEAN NOT NULL DEFAULT false, window_start TIMESTAMPTZ NOT NULL, window_end TIMESTAMPTZ NOT NULL, sample_size INTEGER, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_experiments ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, hypothesis TEXT, use_case TEXT, variants JSONB NOT NULL, traffic_split JSONB NOT NULL, primary_metric TEXT NOT NULL, secondary_metrics TEXT[], status TEXT NOT NULL DEFAULT 'draft', started_at TIMESTAMPTZ, ended_at TIMESTAMPTZ, results JSONB, winner TEXT, owner UUID, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_feature_definitions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), feature_name TEXT NOT NULL UNIQUE, entity_type TEXT NOT NULL, dtype TEXT NOT NULL, description TEXT, owner TEXT, source_sql TEXT, freshness_minutes INTEGER NOT NULL DEFAULT 60, is_pii BOOLEAN NOT NULL DEFAULT false, tags TEXT[], is_active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ml_feature_values ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), feature_name TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, value_num NUMERIC, value_text TEXT, value_json JSONB, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, UNIQUE(feature_name, entity_id) );
CREATE TABLE IF NOT EXISTS public.ml_model_deployments ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), model_id UUID NOT NULL REFERENCES public.ml_model_registry(id) ON DELETE CASCADE, use_case TEXT NOT NULL, environment TEXT NOT NULL DEFAULT 'production', traffic_pct NUMERIC(5,2) NOT NULL DEFAULT 100.00, is_canary BOOLEAN NOT NULL DEFAULT false, is_active BOOLEAN NOT NULL DEFAULT true, rollout_started_at TIMESTAMPTZ NOT NULL DEFAULT now(), rolled_back_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.nav_integrity_threshold_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment text NOT NULL, threshold_id uuid, action text NOT NULL CHECK (action IN ('insert','update','delete')), changed_by uuid REFERENCES auth.users(id), changed_by_email text, old_values jsonb, new_values jsonb, diff jsonb, changed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.nav_integrity_thresholds ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), environment text NOT NULL UNIQUE, max_dead_routes integer NOT NULL DEFAULT 0, max_registry_mismatch integer NOT NULL DEFAULT 0, max_unbound_critical integer NOT NULL DEFAULT 0, max_orphan_routes integer NOT NULL DEFAULT 50, max_missing_analytics integer NOT NULL DEFAULT 25, block_deploy boolean NOT NULL DEFAULT true, notify_emails text[] NOT NULL DEFAULT '{}', updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.nav_registry_versions ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, version bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','validated','in_review','approved','published','superseded','rejected')), title text NOT NULL, notes text, snapshot jsonb NOT NULL, snapshot_hash text NOT NULL, validation jsonb, validation_passed boolean, is_active boolean NOT NULL DEFAULT false, rolled_back_from uuid REFERENCES public.nav_registry_versions(id), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), validated_at timestamptz, submitted_by uuid, submitted_at timestamptz, approved_by uuid, approved_at timestamptz, published_by uuid, published_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.navigation_integrity_runs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), ran_at TIMESTAMPTZ NOT NULL DEFAULT now(), trigger TEXT NOT NULL DEFAULT 'manual', dead_routes INTEGER NOT NULL DEFAULT 0, orphan_routes INTEGER NOT NULL DEFAULT 0, unbound_buttons INTEGER NOT NULL DEFAULT 0, missing_analytics INTEGER NOT NULL DEFAULT 0, permission_violations INTEGER NOT NULL DEFAULT 0, registry_mismatch INTEGER NOT NULL DEFAULT 0, passed BOOLEAN NOT NULL DEFAULT true, report JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.noc_dashboards ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, description TEXT, layout JSONB NOT NULL DEFAULT '{}'::JSONB, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.noc_runbooks ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, service_name TEXT, alert_pattern TEXT, content_md TEXT NOT NULL, tags TEXT[] DEFAULT ARRAY[]::TEXT[], created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.notification_settings ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, contact_inbox TEXT, demo_inbox TEXT, support_inbox TEXT, send_user_confirmation BOOLEAN NOT NULL DEFAULT true, updated_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.notification_templates ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), template_code TEXT NOT NULL UNIQUE, subject TEXT NOT NULL, body_html TEXT NOT NULL, body_text TEXT NOT NULL, variables JSONB NOT NULL DEFAULT '[]'::jsonb, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ocr_extractions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid, driver_id uuid, vehicle_id uuid, document_type text, storage_bucket text, storage_path text, status public.ocr_status NOT NULL DEFAULT 'PENDING', provider text NOT NULL DEFAULT 'lovable-ai', model text, raw_text text, extracted jsonb DEFAULT '{}'::jsonb, confidence numeric(5,2), error_message text, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.operating_context_switches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), acting_user_id uuid NOT NULL, acting_identity text, organisation_id uuid, role text, previous_context text, new_context text NOT NULL, authorization_basis text NOT NULL, event_type text NOT NULL DEFAULT 'operating_context_switch', outcome text NOT NULL DEFAULT 'allowed', correlation_id text, session_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.operations_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, severity text NOT NULL DEFAULT 'info', region text, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, subject_type text, subject_id text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ops_event_outbox ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_uid text NOT NULL, event_type text NOT NULL, source_portal text NOT NULL, service_line text, entity_type text NOT NULL, entity_id uuid NOT NULL, entity_ref text, occurred_at timestamptz NOT NULL DEFAULT now(), signals jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL DEFAULT '{}'::jsonb, dedupe_key text NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_error text, ops_event_id uuid, work_item_id uuid, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ops_event_outbox_dedupe_key_uniq UNIQUE (dedupe_key), CONSTRAINT ops_event_outbox_status_chk CHECK (status IN ('pending','processed','failed','skipped')) );
CREATE TABLE IF NOT EXISTS public.ops_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, source_portal text NOT NULL, service_line text, chain_stage text NOT NULL, entity_type text NOT NULL, entity_id uuid, entity_ref text, occurred_at timestamptz NOT NULL DEFAULT now(), signals jsonb NOT NULL DEFAULT '{}'::jsonb, payload jsonb NOT NULL DEFAULT '{}'::jsonb, disposition text NOT NULL, ops_queue text, priority text NOT NULL DEFAULT 'medium', sla_minutes integer NOT NULL DEFAULT 60, decision_reasons text[] NOT NULL DEFAULT ARRAY[]::text[], dedupe_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ops_events_disposition_chk CHECK (disposition IN ('auto','staff_work','approval','escalate','notify_only','no_action')), CONSTRAINT ops_events_priority_chk CHECK (priority IN ('critical','high','medium','low')) );
CREATE TABLE IF NOT EXISTS public.ops_work_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_item_id uuid NOT NULL REFERENCES public.staff_work_items(id) ON DELETE CASCADE, actor_user_id uuid, actor_role text, actor_name text, action text NOT NULL, state_before text, state_after text, reason text, entity_type text, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.opt_automation_registry ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_type text NOT NULL UNIQUE, domain text NOT NULL, trigger_description text NOT NULL, policy_reference text NOT NULL, authority text NOT NULL, risk_level public.opt_risk_class NOT NULL, reversible boolean NOT NULL, rollback_capability text NOT NULL, adapter_code text, automation_allowed boolean NOT NULL DEFAULT false, refusal_reason text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT opt_automation_refusal_law CHECK ( automation_allowed OR refusal_reason IS NOT NULL ), CONSTRAINT opt_automation_risk_law CHECK ( NOT automation_allowed OR (risk_level = 'LOW_REVERSIBLE' AND reversible) ) );
CREATE TABLE IF NOT EXISTS public.opt_metrics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, domain text NOT NULL, name text NOT NULL, unit text NOT NULL, direction text NOT NULL DEFAULT 'HIGHER_IS_BETTER' CHECK (direction IN ('HIGHER_IS_BETTER','LOWER_IS_BETTER','NEUTRAL')), min_sample_size integer NOT NULL CHECK (min_sample_size >= 1), source_description text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.outbound_external_sends ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, channel text NOT NULL CHECK (channel IN ('email','invoice_note','invite')), recipients text[] NOT NULL DEFAULT '{}', subject text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.outbox_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), source text NOT NULL DEFAULT 'cron', processed integer NOT NULL DEFAULT 0, failed integer NOT NULL DEFAULT 0, total integer NOT NULL DEFAULT 0, duration_ms integer, webhook_url text, notes text );
CREATE TABLE IF NOT EXISTS public.paf_alert_settings ( severity text PRIMARY KEY CHECK (severity IN ('critical','high','medium','low')), slack_webhook_url text, email_recipients text[] NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT true, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.paf_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource text NOT NULL, category text NOT NULL, severity text NOT NULL CHECK (severity IN ('critical','high','medium','low','info')), justification text NOT NULL, compensating_controls text, requested_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, approved_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, approved_at timestamptz, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','expired','revoked')), expires_at timestamptz NOT NULL, linked_run_id uuid, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.paf_remediation_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL, resource text NOT NULL, severity text NOT NULL, sql_text text NOT NULL, sql_hash text NOT NULL, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, decision text NOT NULL CHECK (decision IN ('approved','rejected','deferred')), decision_notes text, exported_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.paf_resource_classifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resource_kind text NOT NULL, resource_name text NOT NULL, domain text NOT NULL, sensitivity text NOT NULL, scope text, notes text, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (resource_kind, resource_name) );
CREATE TABLE IF NOT EXISTS public.paf_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), ran_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, trigger text NOT NULL DEFAULT 'manual', scores jsonb NOT NULL DEFAULT '{}'::jsonb, inventory jsonb NOT NULL DEFAULT '{}'::jsonb, classification jsonb NOT NULL DEFAULT '{}'::jsonb, validation jsonb NOT NULL DEFAULT '{}'::jsonb, drift jsonb NOT NULL DEFAULT '{}'::jsonb, risk_register jsonb NOT NULL DEFAULT '[]'::jsonb, remediation jsonb NOT NULL DEFAULT '[]'::jsonb, critical_count int NOT NULL DEFAULT 0, high_count int NOT NULL DEFAULT 0, medium_count int NOT NULL DEFAULT 0, low_count int NOT NULL DEFAULT 0, passed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_api_credential_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), credential_id uuid REFERENCES public.partner_api_credentials(id) ON DELETE SET NULL, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, action text NOT NULL, environment public.partner_api_environment NOT NULL, actor_id uuid, actor_label text, reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_api_usage_daily ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, credential_id uuid REFERENCES public.partner_api_credentials(id) ON DELETE CASCADE, environment public.partner_api_environment NOT NULL, usage_date date NOT NULL, domain_key text NOT NULL DEFAULT 'all', requests integer NOT NULL DEFAULT 0, errors integer NOT NULL DEFAULT 0, throttled integer NOT NULL DEFAULT 0, p95_latency_ms integer, UNIQUE (credential_id, environment, usage_date, domain_key) );
CREATE TABLE IF NOT EXISTS public.partner_application_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.partner_applications(id) ON DELETE CASCADE, action text NOT NULL, status_from text, status_to text, note text, actor_user_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_application_public_notices ( application_id uuid PRIMARY KEY, notified_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid REFERENCES public.partners(id) ON DELETE CASCADE, application_id uuid REFERENCES public.partner_applications(id) ON DELETE CASCADE, requirement_code text NOT NULL, file_path text NOT NULL, file_name text NOT NULL, mime_type text, size_bytes bigint, status public.partner_doc_status NOT NULL DEFAULT 'pending', issued_on date, expires_at date, review_notes text, reviewed_by uuid, reviewed_at timestamptz, uploaded_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT partner_documents_owner_chk CHECK (partner_id IS NOT NULL OR application_id IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.partner_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, event_type text NOT NULL, title text NOT NULL, detail text, severity text NOT NULL DEFAULT 'info', payload jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_golive_reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, programme text NOT NULL CHECK (programme IN ('api','white_label','technology')), status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','approved','rejected')), checklist jsonb NOT NULL DEFAULT '{"contract_signed":false,"sandbox_calls_passed":false,"webhook_verified":false,"security_contact":false,"support_contact":false,"data_flows_agreed":false}'::jsonb, security_contact text, support_contact text, notes text, submitted_by uuid, submitted_at timestamptz, decided_by uuid, decided_at timestamptz, decision_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (partner_id, programme) );
CREATE TABLE IF NOT EXISTS public.partner_intent_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contact_email text NOT NULL, organisation_name text, contact_name text, contact_phone text, country text, city text, partner_type text, commercial_model text, intent_bring text, network_category text, maturity_level text, lifecycle_stage text, ab_variant text, session_id text, last_application_id uuid REFERENCES public.partner_applications(id) ON DELETE SET NULL, partner_id uuid REFERENCES public.partners(id) ON DELETE SET NULL, application_count integer NOT NULL DEFAULT 0, first_seen_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_performance_components ( id uuid primary key default gen_random_uuid(), partner_id uuid not null references public.partners(id) on delete cascade, computed_at timestamptz not null default now(), component text not null, weight numeric(6,2) not null, score numeric(6,2) not null, evidence jsonb not null default '{}'::jsonb, window_days integer not null default 90 );
CREATE TABLE IF NOT EXISTS public.partner_portal_grants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.partner_applications(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, recipient_email text, recipient_name text, expires_at timestamptz NOT NULL, revoked_at timestamptz, revoked_by uuid, first_opened_at timestamptz, last_opened_at timestamptz, opens integer NOT NULL DEFAULT 0, created_by uuid, created_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_risk_flags ( id uuid primary key default gen_random_uuid(), partner_id uuid not null references public.partners(id) on delete cascade, kind text not null, severity text not null default 'medium' check (severity in ('low','medium','high','critical')), state text not null default 'OPEN' check (state in ('OPEN','INVESTIGATING','RESOLVED','DISMISSED')), detail text not null, evidence jsonb not null default '{}'::jsonb, dedupe_key text not null unique, detected_at timestamptz not null default now(), resolved_by uuid, resolved_at timestamptz, resolution_notes text, updated_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.partner_supply_assets ( id uuid primary key default gen_random_uuid(), partner_id uuid not null references public.partners(id) on delete cascade, asset_kind text not null check (asset_kind in ('DRIVER','VEHICLE','FLEET_CAPACITY','EQUIPMENT')), driver_id uuid references public.drivers(id) on delete set null, vehicle_id uuid references public.vehicles(id) on delete set null, label text not null, service_types text[] not null default '{}', vehicle_class text, city text, county text, country text not null default 'KE', capacity integer not null default 1 check (capacity > 0), status text not null default 'REGISTERED' check (status in ('REGISTERED','VERIFICATION','APPROVED','AVAILABLE','ASSIGNED','ON_TRIP','UNAVAILABLE','SUSPENDED','RETIRED')), compliance_expires_at date, quality_score numeric(5,2) not null default 70 check (quality_score between 0 and 100), is_demo boolean not null default false, notes text, created_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint partner_supply_kind_identity check ( (asset_kind = 'DRIVER' and driver_id is not null) or (asset_kind = 'VEHICLE' and vehicle_id is not null) or (asset_kind in ('FLEET_CAPACITY','EQUIPMENT')) ) );
CREATE TABLE IF NOT EXISTS public.partner_users ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, partner_role public.partner_user_role NOT NULL DEFAULT 'agent', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (partner_id, user_id) );
CREATE TABLE IF NOT EXISTS public.partner_wl_brand_config ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL UNIQUE REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, logo_url text, primary_color text, accent_color text, font_family text, email_sender_name text, support_email text, legal_entity text, policy_url text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_changes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, change_class text NOT NULL, title text NOT NULL, detail text, rollback_plan text, status public.partner_wl_change_status NOT NULL DEFAULT 'proposed', requested_by uuid, approved_by uuid, approved_at timestamptz, applied_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_domains ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, domain text NOT NULL UNIQUE CHECK (domain ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$'), txt_token text NOT NULL DEFAULT 'yalla-verify=' || encode(extensions.gen_random_bytes(12),'hex'), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','failed')), checked_at timestamptz, check_note text, requested_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_environments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, environment public.partner_api_environment NOT NULL, base_url text NOT NULL, webhook_url text, webhook_secret_fingerprint text, is_enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, environment) );
CREATE TABLE IF NOT EXISTS public.partner_wl_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, kind text NOT NULL, subject_ref text, statement text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, prev_hash text, entry_hash text NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_provisioning_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_id uuid NOT NULL, tenant_id uuid, tenant_code text NOT NULL, step text NOT NULL, outcome text NOT NULL CHECK (outcome IN ('started','succeeded','failed','rolled_back')), detail text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_wl_readiness ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL REFERENCES public.partners(id) ON DELETE CASCADE, item_key text NOT NULL, status text NOT NULL DEFAULT 'pending', evidence_ref text, note text, verified_by uuid, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, item_key) );
CREATE TABLE IF NOT EXISTS public.partner_work_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_code text NOT NULL UNIQUE, partner_id uuid REFERENCES public.partners(id) ON DELETE CASCADE, application_id uuid REFERENCES public.partner_applications(id) ON DELETE CASCADE, order_id uuid REFERENCES public.mobility_orders(id) ON DELETE CASCADE, journey_id uuid REFERENCES public.journeys(id) ON DELETE CASCADE, settlement_id uuid REFERENCES public.partner_settlements(id) ON DELETE CASCADE, queue text NOT NULL, title text NOT NULL, detail text, priority text NOT NULL DEFAULT 'medium', state public.partner_case_state NOT NULL DEFAULT 'open', sla_minutes integer NOT NULL DEFAULT 240, sla_started_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz, compliance_flags text[] NOT NULL DEFAULT '{}', risk_score numeric(5,2) NOT NULL DEFAULT 0, assigned_to uuid, escalated_at timestamptz, escalation_reason text, resolved_at timestamptz, resolution_notes text, dedupe_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT partner_work_priority_chk CHECK (priority IN ('critical','high','medium','low')), CONSTRAINT partner_work_queue_chk CHECK (queue IN ('onboarding','compliance','fulfilment','finance','risk','capacity','support')) );
CREATE TABLE IF NOT EXISTS public.performance_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metric_name text NOT NULL, metric_value numeric(20,4) NOT NULL, unit text, tags jsonb NOT NULL DEFAULT '{}'::jsonb, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.phishing_reports ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), report_number TEXT NOT NULL UNIQUE DEFAULT ('PR-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), reported_by UUID, reporter_email TEXT, channel TEXT NOT NULL, artifact_type TEXT NOT NULL, artifact_value TEXT NOT NULL, artifact_screenshot_ref TEXT, description TEXT, status public.phishing_report_status NOT NULL DEFAULT 'new', severity public.security_severity NOT NULL DEFAULT 'MEDIUM', assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, triaged_at TIMESTAMPTZ, resolution_notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pipeline_stage_weights ( stage_key text PRIMARY KEY, label text NOT NULL, win_probability_pct integer NOT NULL CHECK (win_probability_pct BETWEEN 0 AND 100), is_open boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 100, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.platform_readiness_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), computed_at timestamptz NOT NULL DEFAULT now(), ready boolean NOT NULL, readiness_score numeric(5,2) NOT NULL, signal_scores jsonb NOT NULL DEFAULT '{}'::jsonb, reasons jsonb NOT NULL DEFAULT '[]'::jsonb, failed_signals text[] NOT NULL DEFAULT '{}', run_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.policy_capabilities ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_key text NOT NULL, policy_type text NOT NULL, capability_id uuid NOT NULL REFERENCES public.capabilities(id) ON DELETE CASCADE, required boolean NOT NULL DEFAULT true, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (policy_key, capability_id) );
CREATE TABLE IF NOT EXISTS public.policy_change_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, policy_key text NOT NULL, policy_type text NOT NULL, action text NOT NULL, old_state jsonb, new_state jsonb, approval_ref text, reason text, risk_score int NOT NULL DEFAULT 0, prev_hash text, event_hash text, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.posting_batches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, description text, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','POSTING','POSTED','FAILED','CANCELLED')), journal_count int NOT NULL DEFAULT 0, total_debit_cents bigint NOT NULL DEFAULT 0, total_credit_cents bigint NOT NULL DEFAULT 0, created_by uuid REFERENCES auth.users(id), posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.posting_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_code text NOT NULL, version int NOT NULL DEFAULT 1, event_type text NOT NULL, description text, template jsonb NOT NULL, active boolean NOT NULL DEFAULT true, effective_from date NOT NULL DEFAULT CURRENT_DATE, effective_to date, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rule_code, version) );
CREATE TABLE IF NOT EXISTS public.practical_assessments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.training_courses(id) ON DELETE CASCADE, evaluator_id uuid, status text NOT NULL DEFAULT 'pending', score numeric(5,2), notes text, evaluated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.privacy_requests ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), request_number TEXT NOT NULL UNIQUE DEFAULT ('DSAR-' || to_char(now(),'YYYYMMDD') || '-' || substr(gen_random_uuid()::text,1,8)), user_id UUID, requester_email TEXT NOT NULL, request_type public.privacy_request_type NOT NULL, status public.privacy_request_status NOT NULL DEFAULT 'received', sla_due_at TIMESTAMPTZ, description TEXT, resolution_notes TEXT, assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, completed_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.privileged_update_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), occurred_at timestamptz NOT NULL DEFAULT now(), actor_user_id uuid, actor_role text, target_table text NOT NULL, target_row_id text NOT NULL, changed_columns text[] NOT NULL DEFAULT '{}', old_values jsonb NOT NULL DEFAULT '{}'::jsonb, new_values jsonb NOT NULL DEFAULT '{}'::jsonb, request_source text, ip_address inet, user_agent text );
CREATE TABLE IF NOT EXISTS public.projection_drift_scans ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), window_interval interval NOT NULL DEFAULT '24 hours', scanned int NOT NULL DEFAULT 0, healthy int NOT NULL DEFAULT 0, minor int NOT NULL DEFAULT 0, major int NOT NULL DEFAULT 0, critical int NOT NULL DEFAULT 0, drift_score numeric(5,2) NOT NULL DEFAULT 100, blocked_promotion boolean NOT NULL DEFAULT false, duration_ms int, triggered_by text NOT NULL DEFAULT 'system', details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.public_intake_counters ( scope text NOT NULL, window_start timestamptz NOT NULL, hits integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (scope, window_start) );
CREATE TABLE IF NOT EXISTS public.public_upload_scope_ceilings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), counter_table text NOT NULL CHECK (counter_table IN ('rec_public_upload_counters','public_intake_counters')), scope_pattern text NOT NULL, ceiling integer NOT NULL CHECK (ceiling > 0), guard_function text NOT NULL, purpose text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (counter_table, scope_pattern) );
CREATE TABLE IF NOT EXISTS public.public_upload_volume_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), counter_table text NOT NULL, scope text NOT NULL, window_start timestamptz NOT NULL, ceiling integer NOT NULL, hits integer NOT NULL, utilisation numeric NOT NULL, severity text NOT NULL CHECK (severity IN ('WARNING','CRITICAL')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz, acknowledged_by uuid, UNIQUE (counter_table, scope, window_start) );
CREATE TABLE IF NOT EXISTS public.realtime_subscription_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, role_claim text, stream text NOT NULL, channel text, outcome text NOT NULL CHECK (outcome IN ('allowed','denied')), reason text, request_ip inet, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_ai_recommendations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL CHECK (subject_type IN ('vacancy','application','candidate','interview','offer','pipeline')), subject_id uuid, kind text NOT NULL, recommendation text NOT NULL, rationale text, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, confidence numeric, model text, human_decision text CHECK (human_decision IN ('accepted','overridden','rejected','review_requested')), human_decision_by uuid, human_decision_at timestamptz, override_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_application_drafts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, email text NOT NULL, token_hash text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, current_step integer NOT NULL DEFAULT 1, save_count integer NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL DEFAULT now() + interval '60 days', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vacancy_id, email) );
CREATE TABLE IF NOT EXISTS public.rec_application_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, academic_qualifications jsonb NOT NULL DEFAULT '[]'::jsonb, professional_qualifications jsonb NOT NULL DEFAULT '[]'::jsonb, employment_history jsonb NOT NULL DEFAULT '[]'::jsonb, skills text[] NOT NULL DEFAULT '{}', consent_privacy boolean NOT NULL DEFAULT false, consent_at timestamptz, submitted_ip text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (application_id) );
CREATE TABLE IF NOT EXISTS public.rec_application_remediation_cases ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, vacancy_slug text NOT NULL, email text NOT NULL, application_id uuid REFERENCES public.rec_applications(id) ON DELETE SET NULL, cause text NOT NULL DEFAULT 'CANDIDATE_ACTION_REQUIRED' CHECK (cause IN ('CANDIDATE_ACTION_REQUIRED','SYSTEM_REMEDIATION_REQUIRED','SECURITY_REVIEW_REQUIRED')), error_code text, missing jsonb NOT NULL DEFAULT '[]'::jsonb, documents_preserved jsonb NOT NULL DEFAULT '[]'::jsonb, attempt_count integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CANDIDATE_NOTIFIED','RESUMED','COMPLETED','CLOSED_NO_ACTION')), first_failed_at timestamptz NOT NULL DEFAULT now(), last_failed_at timestamptz NOT NULL DEFAULT now(), candidate_notified_at timestamptz, candidate_resumed_at timestamptz, completed_at timestamptz, resolution text, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vacancy_slug, email) );
CREATE TABLE IF NOT EXISTS public.rec_assessment_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_key text NOT NULL, version integer NOT NULL DEFAULT 1, title text NOT NULL, role_family text NOT NULL DEFAULT 'general', vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'draft', total_marks numeric NOT NULL DEFAULT 0, band_rules jsonb NOT NULL DEFAULT '[]'::jsonb, notes text, created_by uuid DEFAULT auth.uid(), activated_at timestamptz, retired_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_assessment_templates_version_uk UNIQUE (template_key, version), CONSTRAINT rec_assessment_templates_status_ck CHECK (status IN ('draft','pilot','active','retired')) );
CREATE TABLE IF NOT EXISTS public.rec_audit_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid DEFAULT auth.uid(), actor_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, action text NOT NULL, object_type text NOT NULL, object_id uuid, previous_state jsonb, new_state jsonb, context jsonb NOT NULL DEFAULT '{}'::jsonb, source text NOT NULL DEFAULT 'staff_portal', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_blueprints ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','retired')), cover_letter_mode text NOT NULL DEFAULT 'optional' CHECK (cover_letter_mode IN ('none','optional','required')), sections jsonb NOT NULL DEFAULT '{"education":true,"qualifications":true,"employment":true,"skills":true}'::jsonb, document_requirements jsonb NOT NULL DEFAULT '[{"doc_type":"cv","label":"CV / Résumé","required":true}]'::jsonb, assessment jsonb NOT NULL DEFAULT '{}'::jsonb, interview jsonb NOT NULL DEFAULT '{}'::jsonb, workflow jsonb NOT NULL DEFAULT '{}'::jsonb, fairness_reviewed_by uuid, fairness_reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vacancy_id, version) );
CREATE TABLE IF NOT EXISTS public.rec_candidate_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, application_id uuid, doc_type text NOT NULL DEFAULT 'cv' CHECK (doc_type IN ('cv','cover_letter','certificate','identification','offer_letter','contract','onboarding','other')), file_name text NOT NULL, storage_path text NOT NULL, mime_type text, size_bytes bigint, crm_document_id uuid REFERENCES public.crm_documents(id) ON DELETE SET NULL, uploaded_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_candidate_experience ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, employer text NOT NULL, title text NOT NULL, start_date date, end_date date, is_current boolean NOT NULL DEFAULT false, description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_candidate_qualifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, qualification text NOT NULL, institution text, award_year integer, kind text NOT NULL DEFAULT 'education' CHECK (kind IN ('education','certification','licence','language')), verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_candidate_skills ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, skill text NOT NULL, proficiency text CHECK (proficiency IN ('basic','intermediate','advanced','expert')), years numeric, evidence text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_comm_candidate_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.rec_comm_requests(id) ON DELETE CASCADE, interview_id uuid REFERENCES public.rec_interviews(id) ON DELETE SET NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, action text, note text, proposed_at timestamptz, responded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_comm_candidate_action_chk CHECK (action IS NULL OR action IN ('confirmed','reschedule_requested','declined')) );
CREATE TABLE IF NOT EXISTS public.rec_comm_reconciliation_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, scanned integer NOT NULL DEFAULT 0, findings integer NOT NULL DEFAULT 0, repaired integer NOT NULL DEFAULT 0, detail jsonb NOT NULL DEFAULT '{}'::jsonb );
CREATE TABLE IF NOT EXISTS public.rec_comm_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE REFERENCES public.rec_comm_requests(id) ON DELETE CASCADE, template_key text NOT NULL, template_version integer NOT NULL, rendered_subject text NOT NULL, rendered_body text NOT NULL, data_snapshot jsonb NOT NULL, branding jsonb NOT NULL DEFAULT '{}'::jsonb, content_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_communications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, application_id uuid REFERENCES public.rec_applications(id) ON DELETE CASCADE, channel text NOT NULL DEFAULT 'email' CHECK (channel IN ('email','sms','in_app','call','note','system')), direction text NOT NULL DEFAULT 'outbound' CHECK (direction IN ('outbound','inbound','internal')), subject text, body text, template_key text, status text NOT NULL DEFAULT 'logged' CHECK (status IN ('draft','queued','sent','delivered','failed','logged')), sent_at timestamptz, actor_id uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_competencies ( code text PRIMARY KEY, label text NOT NULL, description text, role_family text NOT NULL DEFAULT 'general', is_active boolean NOT NULL DEFAULT true, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_conflict_adjudications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid REFERENCES public.rec_candidates(id) ON DELETE SET NULL, subject text NOT NULL DEFAULT 'evaluation_conflict', conflict_summary text NOT NULL, evaluation_ids uuid[] NOT NULL DEFAULT '{}', ai_recommendation text, ai_rationale text, ai_model text, ai_confidence numeric, ai_generated_at timestamptz, hr_decision text CHECK (hr_decision IN ('uphold_advance','uphold_reject','blend_scores','re_interview','request_evidence')), hr_rationale text, decided_by uuid, decided_by_label text, decided_at timestamptz, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','ai_recommended','decided')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_contact_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, application_id uuid REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, requested_fields text[] NOT NULL DEFAULT ARRAY['email','phone']::text[], channel text NOT NULL DEFAULT 'email', status text NOT NULL DEFAULT 'pending', attempt_no integer NOT NULL DEFAULT 1, notification_job_id uuid, recipient text, message_note text, response_email text, response_phone text, response_notes text, responder_kind text, requested_at timestamptz NOT NULL DEFAULT now(), responded_at timestamptz, requested_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_contact_req_channel_chk CHECK (channel = ANY (ARRAY['email','sms','phone_call','whatsapp','manual'])), CONSTRAINT rec_contact_req_status_chk CHECK (status = ANY (ARRAY['pending','awaiting_manual','sent','responded','no_response','cancelled'])), CONSTRAINT rec_contact_req_responder_chk CHECK (responder_kind IS NULL OR responder_kind = ANY (ARRAY['candidate','recruiter','referrer','system'])) );
CREATE TABLE IF NOT EXISTS public.rec_cv_claims ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, application_id uuid REFERENCES public.rec_applications(id) ON DELETE CASCADE, claim_type text NOT NULL, claim_text text NOT NULL, source_document text, source_reference text, extracted_by text NOT NULL DEFAULT 'staff', verification_status text NOT NULL DEFAULT 'claimed', confidence text NOT NULL DEFAULT 'unverified', created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_cv_claims_verif_ck CHECK (verification_status IN ('claimed','verified','demonstrated','partially_verified','unverified','contradicted')), CONSTRAINT rec_cv_claims_conf_ck CHECK (confidence IN ('high','medium','low','unverified')) );
CREATE TABLE IF NOT EXISTS public.rec_document_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid, application_id uuid, candidate_id uuid, vacancy_id uuid, doc_key text, academic_year integer, action text NOT NULL, actor_id uuid, actor_role text, previous_status text, new_status text, reason text, file_hash text, document_version integer, context jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_document_requirement_sets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, scope text NOT NULL DEFAULT 'vacancy' CHECK (scope IN ('universal','vacancy')), vacancy_content_version integer, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','superseded')), effective_from timestamptz NOT NULL DEFAULT now(), notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_docreq_set_scope CHECK ((scope = 'universal' AND vacancy_id IS NULL) OR (scope = 'vacancy' AND vacancy_id IS NOT NULL)) );
CREATE TABLE IF NOT EXISTS public.rec_education_gate_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, public_slug text, draft_ref text, stage text NOT NULL, allowed boolean NOT NULL, code text, outstanding jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_enrichment_audit ( id uuid primary key default gen_random_uuid(), table_name text not null, record_id uuid, candidate_id uuid references public.rec_candidates(id) on delete cascade, action text not null check (action in ('insert','update')), changes jsonb not null default '{}'::jsonb, actor_user_id uuid, actor_label text, source text not null default 'app', run_id uuid references public.rec_import_runs(id) on delete set null, step_key text, created_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.rec_evaluations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interview_id uuid NOT NULL REFERENCES public.rec_interviews(id) ON DELETE CASCADE, application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, evaluator_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, criteria_scores jsonb NOT NULL DEFAULT '[]'::jsonb, overall_score numeric, recommendation text CHECK (recommendation IN ('strong_advance','advance','hold','reject','strong_reject')), strengths text, concerns text, evidence text, comments text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','submitted','reviewed')), submitted_at timestamptz, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (interview_id, evaluator_staff_id) );
CREATE TABLE IF NOT EXISTS public.rec_evidence_adjudications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, attribute text NOT NULL, decision text NOT NULL CHECK (decision IN ('verify','override','reject','waive_gate','set_rejection_reason')), before_fact_id uuid, before_value text, before_confidence numeric, after_fact_id uuid, after_value text, after_confidence numeric, reason_code text NOT NULL, reason_notes text, evaluation_before jsonb NOT NULL DEFAULT '{}'::jsonb, evaluation_after jsonb NOT NULL DEFAULT '{}'::jsonb, adjudicated_by uuid, adjudicator_email text, adjudicated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_evidence_facts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, application_id uuid REFERENCES public.rec_applications(id) ON DELETE CASCADE, attribute text NOT NULL, value_text text, value_numeric numeric, source_kind text NOT NULL, source_ref text NOT NULL, source_locator text, confidence numeric NOT NULL, extracted_by text NOT NULL DEFAULT 'system', verified_by uuid, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_evidence_source_ck CHECK (source_kind IN ('cv','document','form','assessment','interview','reference','manual')), CONSTRAINT rec_evidence_conf_ck CHECK (confidence >= 0 AND confidence <= 1), CONSTRAINT rec_evidence_value_ck CHECK (value_text IS NOT NULL OR value_numeric IS NOT NULL) );
CREATE TABLE IF NOT EXISTS public.rec_import_run_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.rec_import_runs(id) ON DELETE CASCADE, item_no text NOT NULL, item_kind text NOT NULL CHECK (item_kind IN ('invitation_letter','evaluation_form','cv','cover_letter','candidate','application','interview','profile_enrichment')), extracted_name text, extracted_id_number text, extracted_payload jsonb NOT NULL DEFAULT '{}'::jsonb, match_outcome text NOT NULL CHECK (match_outcome IN ('created','updated','matched','skipped','conflict','ambiguous')), match_confidence numeric, matched_candidate_id uuid REFERENCES public.rec_candidates(id) ON DELETE SET NULL, matched_application_id uuid REFERENCES public.rec_applications(id) ON DELETE SET NULL, target_table text, target_id uuid, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (run_id, item_no, item_kind) );
CREATE TABLE IF NOT EXISTS public.rec_import_worker_config ( key text primary key, value text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.rec_internship_spec_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, spec_id uuid NOT NULL, version integer NOT NULL, revision_state text NOT NULL DEFAULT 'DRAFT' CHECK (revision_state IN ('DRAFT','PUBLISHED','SUPERSEDED')), snapshot jsonb NOT NULL, public_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, content_hash text NOT NULL, sealed_at timestamptz, sealed_by uuid, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE (vacancy_id, version) );
CREATE TABLE IF NOT EXISTS public.rec_internship_specs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL UNIQUE REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, programme_id uuid REFERENCES public.intern_programmes(id), cohort_id uuid REFERENCES public.intern_cohorts(id), primary_track_id uuid REFERENCES public.intern_tracks(id), secondary_track_id uuid REFERENCES public.intern_tracks(id), development_track_id uuid REFERENCES public.intern_tracks(id), internship_type text NOT NULL DEFAULT 'ACADEMIC' CHECK (internship_type IN ('ACADEMIC','INDUSTRIAL_ATTACHMENT','PROFESSIONAL','GRADUATE','STRUCTURED_TALENT')), duration_weeks integer NOT NULL DEFAULT 12 CHECK (duration_weeks BETWEEN 1 AND 104), start_date date, end_date date, application_deadline date, host_function text, department text, business_unit text, supervisor_staff_id uuid, mentor_staff_id uuid, approving_manager_staff_id uuid, programme_purpose text, learning_objectives jsonb NOT NULL DEFAULT '[]'::jsonb, learning_outcomes jsonb NOT NULL DEFAULT '[]'::jsonb, productivity_mandate jsonb NOT NULL DEFAULT '[]'::jsonb, kpis jsonb NOT NULL DEFAULT '[]'::jsonb, academic_eligibility jsonb NOT NULL DEFAULT '{}'::jsonb, required_documents text[] NOT NULL DEFAULT '{}', curriculum_map jsonb NOT NULL DEFAULT '[]'::jsonb, competencies jsonb NOT NULL DEFAULT '[]'::jsonb, practical_capabilities text[] NOT NULL DEFAULT '{}', experience_equivalency text[] NOT NULL DEFAULT '{}', assessment_design jsonb NOT NULL DEFAULT '[]'::jsonb, interview_framework jsonb NOT NULL DEFAULT '[]'::jsonb, selection_weights jsonb NOT NULL DEFAULT '{"academic_relevance":15,"curriculum_relevance":15,"competencies":10,"evidence":15,"assessment":20,"learning_agility":10,"communication":5,"problem_solving":5,"interview":5}'::jsonb, weights_version integer NOT NULL DEFAULT 1, talent_attributes text[] NOT NULL DEFAULT '{}', commercial_objective jsonb NOT NULL DEFAULT '{}'::jsonb, success_profile text[] NOT NULL DEFAULT '{}', development_plan jsonb NOT NULL DEFAULT '[]'::jsonb, public_preview jsonb NOT NULL DEFAULT '{}'::jsonb, application_questions jsonb NOT NULL DEFAULT '[]'::jsonb, position_exception_reason text, spec_status text NOT NULL DEFAULT 'DRAFT' CHECK (spec_status IN ('DRAFT','REVIEW','APPROVED','PUBLISHED','CLOSED')), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_interview_panel ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interview_id uuid NOT NULL REFERENCES public.rec_interviews(id) ON DELETE CASCADE, staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, panel_role text NOT NULL DEFAULT 'interviewer' CHECK (panel_role IN ('lead','interviewer','observer')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (interview_id, staff_id) );
CREATE TABLE IF NOT EXISTS public.rec_migration_batches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_no text NOT NULL UNIQUE, name text NOT NULL, source_kind text NOT NULL DEFAULT 'unknown' CHECK (source_kind IN ('external_ats','job_board','previous_system','email_applications','historical_archive','agency','manual_collection','other','unknown')), source_platform text, source_organization text, original_campaign text, import_date date, owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, notes text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','ingesting','processing','review','importing','imported','partially_imported','rolled_back','failed','cancelled')), mapping jsonb NOT NULL DEFAULT '{}'::jsonb, totals jsonb NOT NULL DEFAULT '{}'::jsonb, quality jsonb NOT NULL DEFAULT '{}'::jsonb, rollback_available boolean NOT NULL DEFAULT true, rolled_back_at timestamptz, rolled_back_by uuid, started_at timestamptz, completed_at timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_migration_mappings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, source_kind text NOT NULL DEFAULT 'unknown', source_platform text, mapping jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_offer_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES public.rec_offers(id) ON DELETE CASCADE, step_order integer NOT NULL DEFAULT 1, approver_role text NOT NULL, approver_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, decision text NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending','approved','rejected','skipped')), decided_by uuid, decided_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (offer_id, step_order) );
CREATE TABLE IF NOT EXISTS public.rec_preemployment_checks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, offer_id uuid REFERENCES public.rec_offers(id) ON DELETE SET NULL, onboarding_case_id uuid REFERENCES public.rec_onboarding_cases(id) ON DELETE SET NULL, check_type text NOT NULL, status text NOT NULL DEFAULT 'pending', is_blocking boolean NOT NULL DEFAULT true, provider text, reference text, notes text, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_preemp_status_chk CHECK (status IN ('pending','in_progress','passed','failed','waived')), CONSTRAINT rec_preemp_unique UNIQUE (application_id, check_type) );
CREATE TABLE IF NOT EXISTS public.rec_privacy_notices ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version text NOT NULL UNIQUE, title text NOT NULL, body_markdown text NOT NULL, effective_from date NOT NULL DEFAULT current_date, is_current boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_public_announcement_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, public_slug text NOT NULL, event_kind text NOT NULL CHECK (event_kind IN ('VIEW','APPLICATION_START','APPLICATION_SUBMIT')), visitor_hash text, referrer_host text, device_class text CHECK (device_class IS NULL OR device_class IN ('mobile','tablet','desktop','unknown')), occurred_at timestamptz NOT NULL DEFAULT now(), occurred_on date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date );
CREATE TABLE IF NOT EXISTS public.rec_public_api_metrics ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, operation text NOT NULL CHECK (operation IN ('list_vacancies','get_vacancy','submit_application','upload_document')), slug text, duration_ms integer NOT NULL CHECK (duration_ms >= 0), outcome text NOT NULL CHECK (outcome IN ('success','empty','error')), row_count integer, error_message text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_public_apply_attempts ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, email text, vacancy_slug text, outcome text NOT NULL CHECK (outcome IN ('accepted','duplicate','rejected')), reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_public_upload_counters ( scope text NOT NULL, window_start timestamptz NOT NULL, hits integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (scope, window_start) );
CREATE TABLE IF NOT EXISTS public.rec_public_upload_sessions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_slug text NOT NULL, file_count integer NOT NULL DEFAULT 0, claimed_application_id uuid, claimed_at timestamptz, expires_at timestamptz NOT NULL DEFAULT now() + interval '2 hours', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_publication_gate_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, vacancy_slug text, gate text NOT NULL CHECK (gate IN ('VALIDATION','CONTRACT','E2E')), outcome text NOT NULL CHECK (outcome IN ('PASS','FAIL')), content_version integer, requirement_version integer, build_id text, suite text, cases_total integer, cases_passed integer, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, executed_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_question_bank ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_key text NOT NULL, version integer NOT NULL DEFAULT 1, competency_code text NOT NULL, competency_label text NOT NULL, prompt text NOT NULL, scenario text, question_type text NOT NULL DEFAULT 'behavioural', max_marks numeric NOT NULL CHECK (max_marks > 0), probes text[] NOT NULL DEFAULT '{}', good_indicators text[] NOT NULL DEFAULT '{}', weak_indicators text[] NOT NULL DEFAULT '{}', scoring_anchors jsonb NOT NULL DEFAULT '[]'::jsonb, expected_evidence text, role_family text NOT NULL DEFAULT 'general', status text NOT NULL DEFAULT 'active', effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_question_bank_version_uk UNIQUE (question_key, version), CONSTRAINT rec_question_bank_status_ck CHECK (status IN ('draft','active','retired')), CONSTRAINT rec_question_bank_type_ck CHECK (question_type IN ( 'cv_validation','behavioural','situational','role_specific','commercial', 'operational','productivity','role_play','work_simulation')) );
CREATE TABLE IF NOT EXISTS public.rec_rejection_reasons ( code text PRIMARY KEY, label text NOT NULL, category text NOT NULL, template_key text, requires_approval boolean NOT NULL DEFAULT false, exposes_comparative boolean NOT NULL DEFAULT false, candidate_message text, is_active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_requirement_evaluations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, trigger_reason text NOT NULL, document_id uuid, requirement_version integer, requirement_set_ids uuid[], education_evidence_complete boolean NOT NULL, education_verified_complete boolean NOT NULL, submission_allowed boolean NOT NULL, progression_allowed boolean NOT NULL, outstanding text[] NOT NULL DEFAULT '{}', evaluation jsonb NOT NULL, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_requirement_response_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), response_id uuid, application_id uuid NOT NULL, requirement_key text NOT NULL, action text NOT NULL, previous_status text, new_status text, declared boolean, note text, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_scorecards ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'draft', notes text, created_by uuid, activated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_scorecards_status_ck CHECK (status IN ('draft','active','archived')), CONSTRAINT rec_scorecards_version_uk UNIQUE (vacancy_id, version) );
CREATE TABLE IF NOT EXISTS public.rec_screenings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, criteria jsonb NOT NULL DEFAULT '[]'::jsonb, knockout_failed boolean NOT NULL DEFAULT false, ai_score numeric, ai_recommendation text CHECK (ai_recommendation IN ('advance','review','reject')), ai_rationale text, ai_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, human_score numeric, human_decision text CHECK (human_decision IN ('advance','reject','hold')), human_decision_by uuid, human_decision_at timestamptz, decision_notes text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','in_progress','completed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_settings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), setting_key text NOT NULL UNIQUE, value jsonb NOT NULL DEFAULT '{}'::jsonb, description text, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_shortlist_entries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, rank integer, reviewer_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, reason text, decision text NOT NULL DEFAULT 'shortlisted' CHECK (decision IN ('shortlisted','removed','advanced','second_opinion')), added_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vacancy_id, application_id) );
CREATE TABLE IF NOT EXISTS public.rec_skills ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, category text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_sla_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sla_key text NOT NULL UNIQUE, label text NOT NULL, target_hours integer NOT NULL, applies_to text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_staff_provisioning ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL UNIQUE REFERENCES public.rec_applications(id) ON DELETE CASCADE, onboarding_case_id uuid NOT NULL REFERENCES public.rec_onboarding_cases(id) ON DELETE CASCADE, staff_member_id uuid NOT NULL REFERENCES public.staff_members(id) ON DELETE RESTRICT, staff_no text NOT NULL, provisioned_by uuid DEFAULT auth.uid(), provisioned_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_suitability_determinations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, verdict text NOT NULL, evidence_status text NOT NULL, average_form_score numeric, score_scale text, evidence_basis jsonb NOT NULL DEFAULT '[]'::jsonb, missing_evidence text[] NOT NULL DEFAULT '{}'::text[], conflicts text[] NOT NULL DEFAULT '{}'::text[], rationale text NOT NULL, requires_hr_action text, determined_by uuid, determined_at timestamptz NOT NULL DEFAULT now(), is_current boolean NOT NULL DEFAULT true, CONSTRAINT rec_suit_verdict_ck CHECK (verdict = ANY (ARRAY['SUITABLE','NOT_SUITABLE','EVIDENCE_INSUFFICIENT','CONFLICTING_EVIDENCE'])), CONSTRAINT rec_suit_evidence_ck CHECK (evidence_status = ANY (ARRAY['COMPLETE','INCOMPLETE','ASSESSMENT_DATA_MISSING'])) );
CREATE TABLE IF NOT EXISTS public.rec_talent_pool ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, tags text[] NOT NULL DEFAULT '{}', potential_roles text[] NOT NULL DEFAULT '{}', availability text, desired_location text, desired_salary_cents bigint, rating numeric, entry_reason text NOT NULL DEFAULT 'not_selected', added_by uuid DEFAULT auth.uid(), last_engaged_at timestamptz, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','nurturing','placed','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (candidate_id) );
CREATE TABLE IF NOT EXISTS public.rec_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_key text NOT NULL UNIQUE, name text NOT NULL, kind text NOT NULL CHECK (kind IN ('job_description','email','interview_invite','rejection','offer','onboarding','notification')), subject text, body text NOT NULL DEFAULT '', variables text[] NOT NULL DEFAULT '{}', is_active boolean NOT NULL DEFAULT true, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_vacancy_assessment_decisions ( vacancy_id uuid PRIMARY KEY REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, decision text NOT NULL CHECK (decision IN ('REQUIRED','NOT_APPLICABLE')), reason text NOT NULL, decided_by uuid, decided_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_vacancy_slug_aliases ( slug text PRIMARY KEY, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_vacancy_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, version integer NOT NULL, content_hash text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE (vacancy_id, version) );
CREATE TABLE IF NOT EXISTS public.rec_workflows ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_key text NOT NULL UNIQUE, name text NOT NULL, trigger_event text NOT NULL, conditions jsonb NOT NULL DEFAULT '[]'::jsonb, actions jsonb NOT NULL DEFAULT '[]'::jsonb, is_active boolean NOT NULL DEFAULT true, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.recon_action_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), actor_id uuid, actor_email text, action text NOT NULL CHECK (action = ANY (ARRAY[ 'export','rerun','rerun_dry_run','reversal_confirm','acknowledge','resolve','alert_retry','alert_acknowledge' ]::text[])), permission text, target_type text, target_id text, dataset text, row_count integer, export_format text, filters jsonb NOT NULL DEFAULT '{}'::jsonb, resolution_notes text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, outcome text NOT NULL DEFAULT 'success' CHECK (outcome = ANY (ARRAY['success','failed','denied']::text[])) );
CREATE TABLE IF NOT EXISTS public.reconciliation_case_activities ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID NOT NULL REFERENCES public.reconciliation_cases(id) ON DELETE CASCADE, actor UUID REFERENCES auth.users(id) ON DELETE SET NULL, actor_email TEXT, action_type TEXT NOT NULL, previous_status TEXT, new_status TEXT, note TEXT, ip_address TEXT, device TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.reconciliation_evidence ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID REFERENCES public.reconciliation_cases(id) ON DELETE SET NULL, reconciliation_id UUID REFERENCES public.corporate_financial_reconciliation(id) ON DELETE SET NULL, corporate_id UUID REFERENCES public.corporate_accounts(id) ON DELETE SET NULL, file_name TEXT NOT NULL, storage_path TEXT NOT NULL, file_type TEXT, mime_type TEXT, file_size BIGINT, uploaded_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, uploaded_by_email TEXT, description TEXT, version INTEGER NOT NULL DEFAULT 1, checksum TEXT, deleted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.regulatory_caps ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), country_code TEXT NOT NULL, regulator TEXT NOT NULL, framework_ref TEXT, commission_pct_max NUMERIC(5,2), driver_share_pct_min NUMERIC(5,2), minimum_fare_local NUMERIC(10,2), currency TEXT, surge_multiplier_max NUMERIC(4,2), max_vehicle_age_years INTEGER, vat_pct NUMERIC(5,2), digital_service_tax_pct NUMERIC(5,2), effective_from DATE, effective_until DATE, is_active BOOLEAN NOT NULL DEFAULT true, source_url TEXT, notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(country_code, framework_ref) );
CREATE TABLE IF NOT EXISTS public.regulatory_frameworks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES public.countries(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, authority text, version text, effective_from date, effective_to date, config jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_id, code, version) );
CREATE TABLE IF NOT EXISTS public.regulatory_reports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind public.reg_report_kind NOT NULL, name text NOT NULL, regulator public.regulator NOT NULL, jurisdiction text NOT NULL DEFAULT 'KE', cadence text NOT NULL DEFAULT 'monthly', definition jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rename_alert_thresholds ( source TEXT PRIMARY KEY CHECK (source IN ('rename-audit','phase3-backfill','scheduled-verify')), critical_threshold INTEGER NOT NULL DEFAULT 0, warning_threshold INTEGER NOT NULL DEFAULT 0, cooldown_minutes INTEGER NOT NULL DEFAULT 30, notes TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by UUID );
CREATE TABLE IF NOT EXISTS public.rename_backfill_verifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ran_at timestamptz NOT NULL DEFAULT now(), trigger text NOT NULL CHECK (trigger IN ('scheduled','manual')), triggered_by uuid REFERENCES auth.users(id), tables jsonb NOT NULL DEFAULT '[]'::jsonb, divergent_rows integer NOT NULL DEFAULT 0, passed boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_amendments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.rental_bookings(id) ON DELETE RESTRICT, amendment_type text NOT NULL CHECK (amendment_type IN ('RESCHEDULE','CANCELLATION')), original_start date NOT NULL, original_end date NOT NULL, original_total_kes numeric(14,2) NOT NULL, requested_start date, requested_end date, reason text, requested_by uuid, requested_channel text NOT NULL DEFAULT 'CUSTOMER', state text NOT NULL DEFAULT 'REQUESTED' CHECK (state IN ('REQUESTED','APPROVED','DECLINED','POLICY_REQUIRED')), decided_by uuid, decided_at timestamptz, decision_note text, price_difference_kes numeric(14,2), refund_id uuid REFERENCES public.rental_refunds(id) ON DELETE SET NULL, correlation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_controls ( control_code text PRIMARY KEY, domain text NOT NULL, title text NOT NULL, requirement text NOT NULL, evidence_kind text NOT NULL CHECK (evidence_kind IN ('EXECUTED_DB_PROBE','ISOLATED_CONCURRENCY_PROBE','ROLE_SESSION_PROBE', 'EXTERNAL_DOCUMENT','OWNER_DECISION','MEASUREMENT','STAGING_END_TO_END')), severity text NOT NULL CHECK (severity IN ('P0','P1','P2')), mandatory boolean NOT NULL DEFAULT true, note text );
CREATE TABLE IF NOT EXISTS public.rental_domain_authority ( domain text PRIMARY KEY, authoritative_store text NOT NULL, owns text NOT NULL, may_not_write text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_domain_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_uid text NOT NULL UNIQUE, event_type text NOT NULL, event_version integer NOT NULL DEFAULT 1, entity_type text NOT NULL, entity_id uuid, entity_ref text, correlation_id uuid NOT NULL, causation_id uuid, actor_id uuid, payload jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_event_escalations ( rental_event_type text PRIMARY KEY, ops_event_type text NOT NULL, source_portal text NOT NULL DEFAULT 'rental_leasing', service_line text NOT NULL DEFAULT 'rental', ops_entity_type text NOT NULL DEFAULT 'rental_agreement' );
CREATE TABLE IF NOT EXISTS public.rental_exception_policies ( exception_code text PRIMARY KEY, label text NOT NULL, severity text NOT NULL CHECK (severity IN ('P0','P1','P2','P3')), autonomous boolean NOT NULL DEFAULT false, action text NOT NULL, max_attempts integer NOT NULL DEFAULT 0, never_auto_retry boolean NOT NULL DEFAULT false, human_authority text, note text );
CREATE TABLE IF NOT EXISTS public.rental_handovers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.rental_bookings(id) ON DELETE RESTRICT, unit_id uuid REFERENCES public.rental_fleet_units(id) ON DELETE SET NULL, direction text NOT NULL CHECK (direction IN ('PICKUP','RETURN')), occurred_at timestamptz NOT NULL DEFAULT now(), location text NOT NULL, odometer_km integer NOT NULL CHECK (odometer_km >= 0), fuel_level text NOT NULL CHECK (fuel_level IN ('EMPTY','QUARTER','HALF','THREE_QUARTER','FULL')), condition_note text NOT NULL, damage_found boolean NOT NULL DEFAULT false, documents jsonb NOT NULL DEFAULT '[]'::jsonb, photos jsonb NOT NULL DEFAULT '[]'::jsonb, customer_name text NOT NULL, staff_id uuid, correlation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (booking_id, direction) );
CREATE TABLE IF NOT EXISTS public.rental_operations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operation text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), state text NOT NULL DEFAULT 'IN_PROGRESS' CHECK (state IN ('IN_PROGRESS','COMPLETED','FAILED')), result jsonb, failure_reason text, attempts integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE (operation, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.rental_policies ( policy_code text PRIMARY KEY, label text NOT NULL, evaluation_point text NOT NULL CHECK (evaluation_point IN ('QUOTE_REQUEST','QUOTE_ACCEPTANCE','BOOKING_CONFIRMATION', 'PICKUP','RETURN','CANCELLATION','REFUND','VEHICLE_ACTIVATION')), rule_type text NOT NULL CHECK (rule_type IN ('HARD_GATE','APPROVAL','CHARGE','ADVISORY')), config jsonb NOT NULL DEFAULT '{}'::jsonb, state text NOT NULL DEFAULT 'ACTIVE' CHECK (state IN ('ACTIVE','POLICY_REQUIRED','DISABLED')), owner_decision text, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_policy_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evaluation_point text NOT NULL, policy_code text NOT NULL, policy_version integer, version_state text, rule_type text, subject_type text, subject_ref text, correlation_id uuid, input jsonb NOT NULL DEFAULT '{}'::jsonb, decision text NOT NULL, reason text, binding boolean NOT NULL DEFAULT true, actor_kind text NOT NULL DEFAULT 'SYSTEM', actor_id uuid, decided_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_quote_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_id uuid NOT NULL REFERENCES public.rental_quote_requests(id) ON DELETE CASCADE, event_type text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_release_gates ( gate_code text PRIMARY KEY, label text NOT NULL, sort_order integer NOT NULL DEFAULT 100, description text );
CREATE TABLE IF NOT EXISTS public.rental_saga_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), saga text NOT NULL, correlation_id uuid NOT NULL, subject_type text NOT NULL, subject_id uuid, subject_ref text, state text NOT NULL DEFAULT 'RUNNING' CHECK (state IN ('RUNNING','COMPENSATING','COMPENSATED','COMPLETED','ESCALATED')), last_error text, started_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz );
CREATE TABLE IF NOT EXISTS public.rental_state_transitions ( entity text NOT NULL, from_state text NOT NULL, to_state text NOT NULL, note text, PRIMARY KEY (entity, from_state, to_state) );
CREATE TABLE IF NOT EXISTS public.rental_unit_commitments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.rental_fleet_units(id) ON DELETE CASCADE, booking_id uuid REFERENCES public.rental_bookings(id) ON DELETE CASCADE, start_date date NOT NULL, end_date date NOT NULL, source text NOT NULL DEFAULT 'BOOKING' CHECK (source IN ('BOOKING','BLOCK','SERVICE')), note text, created_at timestamptz NOT NULL DEFAULT now(), CHECK (end_date >= start_date) );
CREATE TABLE IF NOT EXISTS public.rental_unit_readiness_checks ( check_code text PRIMARY KEY, label text NOT NULL, mandatory boolean NOT NULL DEFAULT true, note text );
CREATE TABLE IF NOT EXISTS public.report_export_schedules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, report_key text NOT NULL, cadence text NOT NULL, format text NOT NULL DEFAULT 'csv', recipients jsonb NOT NULL DEFAULT '[]'::jsonb, corporate_id uuid, range_days integer NOT NULL DEFAULT 30, enabled boolean NOT NULL DEFAULT true, last_run_at timestamptz, next_run_at timestamptz NOT NULL DEFAULT now(), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT res_cadence_check CHECK (cadence IN ('daily','weekly','monthly')), CONSTRAINT res_format_check CHECK (format IN ('csv','pdf','both')), CONSTRAINT res_range_check CHECK (range_days BETWEEN 1 AND 365) );
CREATE TABLE IF NOT EXISTS public.report_schema_alerts ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, request_id text NOT NULL, report text NOT NULL, error_kind text NOT NULL, error_code text, message text NOT NULL, missing jsonb NOT NULL DEFAULT '{}'::jsonb, route text, actor_id uuid, actor_email text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.resource_scopes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, scope_type text NOT NULL, scope_value text NOT NULL, tenant_id uuid, region_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, scope_type, scope_value) );
CREATE TABLE IF NOT EXISTS public.retention_policies ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dataset TEXT NOT NULL UNIQUE, retention_days INT NOT NULL, delete_strategy TEXT NOT NULL DEFAULT 'hard_delete', legal_hold BOOLEAN NOT NULL DEFAULT false, description TEXT, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.revenue_eligibility_checks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL REFERENCES public.commercial_transactions(id) ON DELETE CASCADE, transaction_ref text NOT NULL, service_line text NOT NULL, rule_key text, eligible boolean NOT NULL, missing_fields jsonb NOT NULL DEFAULT '[]'::jsonb, blockers jsonb NOT NULL DEFAULT '[]'::jsonb, economics_complete boolean NOT NULL DEFAULT false, review_status text, source text NOT NULL DEFAULT 'manual', checked_by uuid, checked_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.revenue_event_reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), revenue_event_id uuid NOT NULL REFERENCES public.contract_revenue_events(id) ON DELETE RESTRICT, contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE RESTRICT, decision text NOT NULL CHECK (decision IN ('APPROVED','ADJUSTED','REJECTED')), original_amount numeric(14,2) NOT NULL, adjusted_amount numeric(14,2), delta_amount numeric(14,2), correction_event_id uuid REFERENCES public.contract_revenue_events(id), reason text NOT NULL, reviewer_id uuid, reviewer_staff_id uuid REFERENCES public.staff_members(id), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.revenue_idempotency_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), replays_per_case int NOT NULL, cases_tested int NOT NULL DEFAULT 0, cases_passed int NOT NULL DEFAULT 0, cases_failed int NOT NULL DEFAULT 0, duplicates_created int NOT NULL DEFAULT 0, verdict text NOT NULL DEFAULT 'PASS', guard_present boolean NOT NULL DEFAULT false, run_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.revenue_recognition_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_key text NOT NULL UNIQUE, service_line text NOT NULL, description text NOT NULL, requires_fulfilment boolean NOT NULL DEFAULT true, requires_payment boolean NOT NULL DEFAULT false, requires_invoice boolean NOT NULL DEFAULT false, requires_settlement boolean NOT NULL DEFAULT false, requires_economics_complete boolean NOT NULL DEFAULT true, recognise_gross boolean NOT NULL DEFAULT false, min_amount_cents bigint NOT NULL DEFAULT 0, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, is_active boolean NOT NULL DEFAULT true, approved_by uuid, approved_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.risk_models ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, version TEXT NOT NULL, description TEXT, weights JSONB NOT NULL DEFAULT '{}'::JSONB, thresholds JSONB NOT NULL DEFAULT '{}'::JSONB, active BOOLEAN NOT NULL DEFAULT false, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(name, version) );
CREATE TABLE IF NOT EXISTS public.risk_scores ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), entity_type public.risk_entity_type NOT NULL, entity_id UUID NOT NULL, score NUMERIC(5,2) NOT NULL, band TEXT NOT NULL, model_name TEXT, model_version TEXT, factors JSONB NOT NULL DEFAULT '{}'::JSONB, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_assignment_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES public.sales_leads(id) ON DELETE CASCADE, account_id uuid, from_staff_id uuid, to_staff_id uuid, rule_kind text NOT NULL, rule_id uuid, reason text, actor_user_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_commission_plans ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, base_rate_bp integer NOT NULL CHECK (base_rate_bp BETWEEN 0 AND 10000), performance_rate_bp integer NOT NULL DEFAULT 0 CHECK (performance_rate_bp BETWEEN 0 AND 10000), performance_trigger text NOT NULL DEFAULT 'monthly_target_attainment', effective_from date NOT NULL, effective_to date, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','superseded')), approved_by uuid, approved_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_commission_targets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_code text NOT NULL, period_month date NOT NULL, target_revenue_cents bigint NOT NULL CHECK (target_revenue_cents > 0), status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','superseded')), set_by uuid, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (position_code, period_month) );
CREATE TABLE IF NOT EXISTS public.sales_engine_settings ( id boolean PRIMARY KEY DEFAULT true CHECK (id), business_days_only boolean NOT NULL DEFAULT true, warn_ratio numeric(4,3) NOT NULL DEFAULT 0.800, closing_soon_days int NOT NULL DEFAULT 14, stale_followup_days int NOT NULL DEFAULT 7, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_kpi_closes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grain text NOT NULL CHECK (grain IN ('DAY','WEEK','MONTH','QUARTER','YEAR')), period_start date NOT NULL, period_end date NOT NULL, staff_member_id uuid NOT NULL REFERENCES public.staff_members(id) ON DELETE CASCADE, target_kes numeric NOT NULL DEFAULT 0, revenue_kes numeric NOT NULL DEFAULT 0, attainment_pct numeric, figures jsonb NOT NULL DEFAULT '{}'::jsonb, source text NOT NULL DEFAULT 'AUTOMATED_FREEZE', closed_at timestamptz NOT NULL DEFAULT now(), closed_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (grain, period_start, staff_member_id) );
CREATE TABLE IF NOT EXISTS public.sales_lead_changes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, field text NOT NULL, old_value text, new_value text, changed_by uuid, changed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_lead_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, action text NOT NULL, stage_from text, stage_to text, note text, actor_user_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_lead_followups ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, sales_staff_id uuid, logged_note text NOT NULL, contact_date date NOT NULL DEFAULT (now() AT TIME ZONE 'Africa/Nairobi')::date, next_action text NOT NULL, due_date date NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','DONE','CANCELLED')), outcome text, closed_at timestamptz, closed_by uuid, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_lead_import_batches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), imported_by uuid NOT NULL DEFAULT auth.uid(), source text NOT NULL DEFAULT 'PASTE', label text, rows_submitted integer NOT NULL DEFAULT 0, rows_created integer NOT NULL DEFAULT 0, rows_skipped integer NOT NULL DEFAULT 0, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_lead_messages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, direction text NOT NULL CHECK (direction IN ('OUTBOUND','INBOUND')), channel text NOT NULL CHECK (channel IN ('EMAIL','PHONE','WHATSAPP','MEETING','CONTACT_LINK','OTHER')), subject text, body text NOT NULL, recipient_email text, contact_link text, sender_name text, actor_user_id uuid, actor_staff_member_id uuid, intent text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_lead_reminder_state ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, reminder_kind text NOT NULL, snoozed_until date, dismissed_at timestamptz, note text, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (lead_id, reminder_kind) );
CREATE TABLE IF NOT EXISTS public.sales_lead_routing_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_key text NOT NULL UNIQUE, lead_context text NOT NULL, product_scope text NOT NULL, primary_position_code text NOT NULL, supporting_position_code text, account_owner_preserved boolean NOT NULL DEFAULT false, notes text, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_lead_service_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id) ON DELETE CASCADE, request_ref text NOT NULL UNIQUE, service_type text NOT NULL CHECK (service_type IN ('DELIVERY','STAFF_TRANSPORT','AIRPORT_TRANSFER','CHARTER','OTHER')), pickup_location text NOT NULL, dropoff_location text NOT NULL, requested_date date, requested_time text, goods_description text, weight_kg numeric(12,2), vehicle_preference text, passengers integer, notes text, submitted_by_name text, contact_phone text, status text NOT NULL DEFAULT 'SUBMITTED' CHECK (status IN ('SUBMITTED','RECEIVED','IN_REVIEW','QUOTED','SCHEDULED','COMPLETED','DECLINED','CANCELLED')), status_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_period_closures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_start date NOT NULL, period_end date NOT NULL, staff_member_id uuid NOT NULL REFERENCES public.staff_members(id) ON DELETE CASCADE, target_kes numeric(14,2) NOT NULL DEFAULT 0, revenue_kes numeric(14,2) NOT NULL DEFAULT 0, attainment_pct numeric(8,2), won_count int NOT NULL DEFAULT 0, decided_count int NOT NULL DEFAULT 0, open_pipeline_kes numeric(14,2) NOT NULL DEFAULT 0, snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'CLOSED' CHECK (status = ANY (ARRAY['CLOSED','REOPENED'])), closed_by uuid, closed_at timestamptz NOT NULL DEFAULT now(), UNIQUE (period_start, staff_member_id) );
CREATE TABLE IF NOT EXISTS public.sales_routing_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind = ANY (ARRAY['TERRITORY','CAPABILITY','TEAM'])), label text NOT NULL, match_country text, match_city text, match_territory text, match_service text, match_tier text, staff_member_id uuid REFERENCES public.staff_members(id) ON DELETE CASCADE, unit_id uuid REFERENCES public.org_units(id) ON DELETE CASCADE, priority int NOT NULL DEFAULT 100, is_active boolean NOT NULL DEFAULT true, effective_from date NOT NULL DEFAULT current_date, effective_to date, notes text, set_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_sla_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), process text NOT NULL CHECK (process = ANY (ARRAY[ 'LEAD_RESPONSE','QUALIFICATION','INFORMATION_REQUEST', 'PROPOSAL_FOLLOWUP','CONTRACT_FOLLOWUP','ACCOUNT_ACTIVATION'])), label text NOT NULL, minutes int NOT NULL CHECK (minutes > 0), warn_ratio numeric(4,3) NOT NULL DEFAULT 0.800, pause_on_customer boolean NOT NULL DEFAULT false, match_service text, match_priority text, match_source text, match_tier text, match_territory text, match_position_code text, effective_from date NOT NULL DEFAULT current_date, effective_to date, is_active boolean NOT NULL DEFAULT true, notes text, set_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_targets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL CHECK (scope IN ('GLOBAL','UNIT','POSITION','STAFF')), staff_member_id uuid REFERENCES public.staff_members(id) ON DELETE CASCADE, position_code text, unit_id uuid REFERENCES public.org_units(id) ON DELETE CASCADE, period text NOT NULL DEFAULT 'MONTH' CHECK (period IN ('MONTH','QUARTER','YEAR')), amount_kes numeric(14,2) NOT NULL CHECK (amount_kes >= 0), currency text NOT NULL DEFAULT 'KES', effective_from date NOT NULL DEFAULT date_trunc('month', now())::date, effective_to date, is_active boolean NOT NULL DEFAULT true, is_override boolean NOT NULL DEFAULT false, notes text, set_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT sales_targets_scope_key CHECK ( (scope = 'GLOBAL' AND staff_member_id IS NULL AND position_code IS NULL AND unit_id IS NULL) OR (scope = 'UNIT' AND unit_id IS NOT NULL AND staff_member_id IS NULL) OR (scope = 'POSITION' AND position_code IS NOT NULL AND staff_member_id IS NULL) OR (scope = 'STAFF' AND staff_member_id IS NOT NULL) ) );
CREATE TABLE IF NOT EXISTS public.security_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), incident_id uuid REFERENCES public.security_incidents(id) ON DELETE SET NULL, alert_type text NOT NULL, severity public.security_severity NOT NULL DEFAULT 'MEDIUM', message text NOT NULL, acknowledged boolean NOT NULL DEFAULT false, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.security_audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_type text NOT NULL, performed_by uuid, scope text, findings jsonb NOT NULL DEFAULT '[]'::jsonb, passed boolean, performed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.security_control_evidence ( id uuid primary key default gen_random_uuid(), control_id text not null, status text not null check (status in ('VERIFIED','FAILED','BLOCKED','UNVERIFIED','NOT_APPLICABLE')), reason text, evidence text, asset_ids text[] not null default '{}', observed_at timestamptz not null default now(), recorded_by uuid default auth.uid(), created_at timestamptz not null default now() );
CREATE TABLE IF NOT EXISTS public.security_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, event_type TEXT NOT NULL, severity incident_severity NOT NULL DEFAULT 'low', details JSONB, ip_address INET, user_agent TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.security_findings_registry ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), internal_id text NOT NULL UNIQUE, scanner_name text NOT NULL DEFAULT 'supabase_lov', finding_code text, name text NOT NULL, description text, severity text NOT NULL DEFAULT 'warn', status text NOT NULL DEFAULT 'open', first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), fixed_at timestamptz, regressed_at timestamptz, last_scan_at timestamptz NOT NULL DEFAULT now(), occurrences integer NOT NULL DEFAULT 1, resolution_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT security_findings_registry_status_chk CHECK (status IN ('open','fixed','regressed','ignored')) );
CREATE TABLE IF NOT EXISTS public.security_scan_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scanner_name text NOT NULL DEFAULT 'supabase_lov', trigger_source text NOT NULL DEFAULT 'scheduled', started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, total_findings integer NOT NULL DEFAULT 0, new_findings integer NOT NULL DEFAULT 0, regressed_findings integer NOT NULL DEFAULT 0, resolved_findings integer NOT NULL DEFAULT 0, alerted boolean NOT NULL DEFAULT false, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.security_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, score numeric(5,2) NOT NULL, factors jsonb NOT NULL DEFAULT '{}'::jsonb, computed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sensitive_read_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, user_roles text[] NOT NULL DEFAULT '{}'::text[], resource text NOT NULL, action text NOT NULL DEFAULT 'select', row_count integer NOT NULL DEFAULT 0, allowed boolean NOT NULL DEFAULT true, context jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.service_alerts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_name TEXT NOT NULL, metric TEXT NOT NULL, threshold NUMERIC, observed NUMERIC, severity public.noc_severity NOT NULL DEFAULT 'SEV4', state TEXT NOT NULL DEFAULT 'firing', fired_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, incident_id UUID REFERENCES public.service_incidents(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.service_health_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_code text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, uptime_pct numeric(5,2), p50_ms int, p95_ms int, p99_ms int, error_count int, request_count int, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.service_line_financial_terms ( service_line text PRIMARY KEY, currency text NOT NULL DEFAULT 'KES', tax_rate_bps integer NOT NULL DEFAULT 0, tax_inclusive boolean NOT NULL DEFAULT true, commission_bps integer NOT NULL DEFAULT 0, payment_cost_bps integer NOT NULL DEFAULT 0, principal_contract boolean NOT NULL DEFAULT false, notes text, approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT slft_service_line_check CHECK (service_line = ANY (ARRAY['ride_hailing','airport','corporate','charter','delivery','rental'])), CONSTRAINT slft_tax_bps_check CHECK (tax_rate_bps BETWEEN 0 AND 5000), CONSTRAINT slft_commission_bps_check CHECK (commission_bps BETWEEN 0 AND 10000), CONSTRAINT slft_payment_bps_check CHECK (payment_cost_bps BETWEEN 0 AND 2000) );
CREATE TABLE IF NOT EXISTS public.social_account_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES public.social_accounts(id) ON DELETE SET NULL, platform_slug text, actor_user_id uuid, action text NOT NULL, old_value jsonb, new_value jsonb, reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_campaigns ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, objective text, platform_slug text REFERENCES public.social_platforms(slug) ON DELETE SET NULL, market text NOT NULL DEFAULT 'GLOBAL', landing_path text NOT NULL DEFAULT '/', utm_source text NOT NULL, utm_medium text NOT NULL DEFAULT 'social', utm_campaign text NOT NULL, start_date date, end_date date, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','PAUSED','ENDED')), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_connections ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL UNIQUE REFERENCES public.social_accounts(id) ON DELETE CASCADE, platform_slug text NOT NULL REFERENCES public.social_platforms(slug) ON DELETE RESTRICT, state text NOT NULL DEFAULT 'NOT_CONNECTED' CHECK (state IN ('NOT_CONNECTED','NOT_CONFIGURED','CONNECTING','CONNECTED', 'TOKEN_EXPIRING','TOKEN_EXPIRED','REAUTH_REQUIRED','SUSPENDED','DISCONNECTED')), external_account_id text, external_account_name text, granted_scopes text[] NOT NULL DEFAULT '{}', token_expires_at timestamptz, last_sync_at timestamptz, last_publication_at timestamptz, last_error_code text, last_error_message text, connected_by uuid, connected_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_content_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid, variant_id uuid, job_id uuid, account_id uuid, actor_user_id uuid, action text NOT NULL, result text NOT NULL DEFAULT 'OK', detail jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_link_health ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.social_accounts(id) ON DELETE CASCADE, checked_at timestamptz NOT NULL DEFAULT now(), state text NOT NULL CHECK (state IN ('HEALTHY','REDIRECTED','UNREACHABLE','INVALID','SUSPENDED','PENDING_REVIEW')), http_status integer, redirect_target text, attempt integer NOT NULL DEFAULT 1, error_detail text );
CREATE TABLE IF NOT EXISTS public.social_webhook_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, signature_valid boolean NOT NULL DEFAULT false, payload jsonb NOT NULL DEFAULT '{}'::jsonb, processed_at timestamptz, error text, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider, event_id) );
CREATE TABLE IF NOT EXISTS public.st_control_executions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES public.st_certification_runs(id) ON DELETE SET NULL, control_id text NOT NULL, environment_key text, environment_id uuid REFERENCES public.infra_environments(id) ON DELETE SET NULL, environment_fingerprint text, schema_version text, state public.st_exec_state NOT NULL DEFAULT 'REQUESTED', result public.st_result NOT NULL DEFAULT 'NOT_TESTED', assertions jsonb NOT NULL DEFAULT '[]'::jsonb, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, first_failure jsonb, error_code text, error_message text, retryable boolean NOT NULL DEFAULT false, attempt integer NOT NULL DEFAULT 1, idempotency_key text NOT NULL UNIQUE, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, request_id text NOT NULL DEFAULT gen_random_uuid()::text, actor text NOT NULL DEFAULT 'di00-orchestrator', evidence_sha256 text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, duration_ms integer, expires_at timestamptz, invalidated_at timestamptz, invalidated_reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.suppressed_emails ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL, reason TEXT NOT NULL CHECK (reason IN ('unsubscribe', 'bounce', 'complaint')), metadata JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(email) );
CREATE TABLE IF NOT EXISTS public.system_health_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_code text NOT NULL, status public.health_status NOT NULL, latency_ms int, error_rate numeric(6,4), message text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.system_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, category text, description text, owner_team text, status text NOT NULL DEFAULT 'ACTIVE', version text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.threat_advisories ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source TEXT NOT NULL, external_id TEXT NOT NULL, title TEXT NOT NULL, severity TEXT NOT NULL, cvss NUMERIC, summary TEXT, affected_component TEXT, affected_versions TEXT, fixed_version TEXT, reference_url TEXT, published_at TIMESTAMPTZ, ingested_at TIMESTAMPTZ NOT NULL DEFAULT now(), test_scenario_key TEXT NOT NULL, mitigation_status TEXT NOT NULL DEFAULT 'open', mitigation_notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source, external_id) );
CREATE TABLE IF NOT EXISTS public.threat_intelligence ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), indicator_type TEXT NOT NULL, indicator_value TEXT NOT NULL, source TEXT NOT NULL, confidence INT NOT NULL DEFAULT 50, tlp public.tlp_marking NOT NULL DEFAULT 'AMBER', first_seen TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(indicator_type, indicator_value, source) );
CREATE TABLE IF NOT EXISTS public.tracking_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL CHECK (subject_type IN ('DRIVER','RIDER','TRIP','VEHICLE')), subject_id uuid NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, point_count int NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.treasury_forecasts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.treasury_accounts(id), forecast_date date NOT NULL, horizon_days int NOT NULL DEFAULT 30, projected_cents bigint NOT NULL, confidence numeric(5,2), assumptions jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.treasury_movements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.treasury_accounts(id), direction text NOT NULL CHECK (direction IN ('INFLOW','OUTFLOW')), amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL, journal_id uuid REFERENCES public.journals(id), reference text, memo text, occurred_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.treasury_positions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.treasury_accounts(id), as_of date NOT NULL, currency text NOT NULL, opening_cents bigint NOT NULL, inflows_cents bigint NOT NULL DEFAULT 0, outflows_cents bigint NOT NULL DEFAULT 0, closing_cents bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (account_id, as_of, currency) );
CREATE TABLE IF NOT EXISTS public.trust_escalations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID NOT NULL REFERENCES public.trust_cases(id) ON DELETE CASCADE, from_user UUID REFERENCES auth.users(id) ON DELETE SET NULL, to_team TEXT NOT NULL, to_user UUID REFERENCES auth.users(id) ON DELETE SET NULL, reason TEXT NOT NULL, level INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.trust_investigations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID NOT NULL REFERENCES public.trust_cases(id) ON DELETE CASCADE, investigator UUID REFERENCES auth.users(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'open', findings TEXT, evidence_refs JSONB NOT NULL DEFAULT '[]'::JSONB, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.trust_resolutions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID NOT NULL UNIQUE REFERENCES public.trust_cases(id) ON DELETE CASCADE, outcome public.trust_resolution_outcome NOT NULL, notes TEXT, refund_amount NUMERIC(14,2), refund_currency TEXT DEFAULT 'KES', decided_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, decided_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.trust_watchlists ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_type public.trust_subject_type NOT NULL, subject_id UUID, subject_value TEXT, risk_level public.trust_case_severity NOT NULL DEFAULT 'medium', reason TEXT NOT NULL, added_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, expires_at TIMESTAMPTZ, active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.trusted_devices ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, fingerprint_id UUID NOT NULL REFERENCES public.device_fingerprints(id) ON DELETE CASCADE, label TEXT, trusted_at TIMESTAMPTZ NOT NULL DEFAULT now(), expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, revoked_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, fingerprint_id) );
CREATE TABLE IF NOT EXISTS public.velocity_checks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid NOT NULL, subject_kind text NOT NULL, window_sec int NOT NULL, count int NOT NULL, threshold int NOT NULL, breached boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.verification_logs ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_document_id UUID, vehicle_document_id UUID, actor_user_id UUID, from_status doc_verification_status, to_status doc_verification_status, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.video_completion_logs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), driver_id uuid NOT NULL, video_id uuid NOT NULL REFERENCES public.training_videos(id) ON DELETE CASCADE, watched_seconds int NOT NULL DEFAULT 0, watched_percent int NOT NULL DEFAULT 0, checkpoints_passed jsonb NOT NULL DEFAULT '[]'::jsonb, completed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(driver_id, video_id) );
CREATE TABLE IF NOT EXISTS public.work_disposition_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_item_id uuid NOT NULL REFERENCES public.staff_work_items(id) ON DELETE CASCADE, staff_id uuid, decided_by uuid NOT NULL DEFAULT auth.uid(), disposition text NOT NULL CHECK (disposition IN ( 'continue','reschedule','waiting','blocked','reassign','automate','nurture','close','disqualify','escalate')), reason text NOT NULL, business_date date NOT NULL DEFAULT (now() AT TIME ZONE 'Africa/Nairobi')::date, new_due_date date, reassign_to_staff_id uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.work_triage_bands ( band text PRIMARY KEY, rank_order integer NOT NULL, label text NOT NULL, priority text NOT NULL, sla_multiplier numeric NOT NULL DEFAULT 1, effort_multiplier numeric NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.workflow_invocations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workflow_name TEXT NOT NULL, workflow_version TEXT, correlation_id UUID NOT NULL, parent_correlation_id UUID, request_id UUID NOT NULL, function_name TEXT NOT NULL, deployment_id TEXT, git_sha TEXT, user_id UUID, caller TEXT, caller_role TEXT, tenant_id UUID, region TEXT, environment TEXT, current_step TEXT, current_state TEXT, execution_status TEXT NOT NULL DEFAULT 'STARTED' CHECK (execution_status IN ('STARTED','SUCCEEDED','FAILED','ABORTED','TIMED_OUT')), started_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, duration_ms INTEGER, retry_count INTEGER NOT NULL DEFAULT 0, error_code TEXT, error_message TEXT, ip TEXT, user_agent TEXT, http_method TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.workflow_registry ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workflow_name TEXT NOT NULL UNIQUE, version TEXT NOT NULL DEFAULT '1.0.0', description TEXT, expected_steps JSONB NOT NULL DEFAULT '[]', sla_seconds INTEGER, timeout_seconds INTEGER, retry_policy JSONB NOT NULL DEFAULT '{}', owner_team TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_agent_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.ai_agents(id) ON DELETE CASCADE, version integer NOT NULL, model_id text, config jsonb NOT NULL DEFAULT '{}'::jsonb, prompt_hash text, active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (agent_id, version) );
CREATE TABLE IF NOT EXISTS public.air_quote_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL DEFAULT ('AQ-' || upper(substr(md5(gen_random_uuid()::text),1,8))) UNIQUE, user_id uuid DEFAULT auth.uid(), contact_name text NOT NULL CHECK (length(contact_name) BETWEEN 2 AND 120), contact_email text NOT NULL CHECK (contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'), contact_phone text NOT NULL CHECK (length(contact_phone) BETWEEN 7 AND 20), origin text NOT NULL REFERENCES public.air_airfields(code), destination text NOT NULL REFERENCES public.air_airfields(code), depart_date date NOT NULL, return_date date, passengers int NOT NULL CHECK (passengers BETWEEN 1 AND 30), class_code text REFERENCES public.air_aircraft_classes(code), fleet_id uuid REFERENCES public.air_fleet(id), empty_leg_id uuid REFERENCES public.air_empty_legs(id), indicative_total_kes numeric, price_breakdown jsonb NOT NULL DEFAULT '{}', notes text CHECK (notes IS NULL OR length(notes) <= 1000), status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','contacted','quoted','booked','lost','cancelled')), staff_note text, handled_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.alerts_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid REFERENCES public.executive_alert_rules(id) ON DELETE SET NULL, rule_name text NOT NULL, stream text NOT NULL, metric_key text NOT NULL, observed_value numeric, threshold numeric, operator text, severity text NOT NULL, message text NOT NULL, triggered_by uuid REFERENCES auth.users(id), context jsonb NOT NULL DEFAULT '{}'::jsonb, acknowledged_at timestamptz, acknowledged_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.assurance_deployment_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES public.assurance_runs(id) ON DELETE CASCADE, decision text NOT NULL CHECK (decision IN ('APPROVED','BLOCKED','WARNING')), reason text, scores jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.assurance_rerun_requests ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id UUID REFERENCES public.assurance_runs(id) ON DELETE CASCADE, requested_by UUID REFERENCES auth.users(id), modules TEXT[] NOT NULL, status TEXT NOT NULL DEFAULT 'queued', dispatch_response JSONB NOT NULL DEFAULT '{}'::jsonb, workflow_run_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.audit_report_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid REFERENCES public.audit_report_schedules(id) ON DELETE CASCADE, range_from timestamptz NOT NULL, range_to timestamptz NOT NULL, audit_count integer NOT NULL DEFAULT 0, login_count integer NOT NULL DEFAULT 0, first_hash text, last_hash text, hash_summary text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','generated','failed')), storage_path text, error text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.carrier_application_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.carrier_applications(id) ON DELETE CASCADE, action text NOT NULL, status_from text, status_to text, note text, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.carrier_withdrawal_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.carrier_withdrawal_requests(id) ON DELETE CASCADE, event_type text NOT NULL, from_state text, to_state text, actor uuid, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_lifecycle ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL UNIQUE REFERENCES public.sales_leads(id) ON DELETE CASCADE, lead_ref text, account_id uuid, opportunity_id uuid, staff_member_id uuid, current_state text NOT NULL DEFAULT 'LEAD' REFERENCES public.commercial_state_registry(state), opportunity_value_kes numeric, contracted_value_kes numeric, ordered_value_kes numeric, delivered_value_kes numeric, billable_value_kes numeric, invoiced_value_kes numeric, recognised_value_kes numeric, collected_value_kes numeric, won_at timestamptz, contracted_at timestamptz, ordered_at timestamptz, delivered_at timestamptz, billable_at timestamptz, invoiced_at timestamptz, recognised_at timestamptz, collected_at timestamptz, lost_at timestamptz, cancelled_at timestamptz, blocked_reason text, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_quotation_lines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quotation_id uuid NOT NULL REFERENCES public.commercial_quotations(id) ON DELETE CASCADE, rate_line_id uuid REFERENCES public.commercial_rate_lines(id) ON DELETE SET NULL, service_code text NOT NULL, scope_label text NOT NULL DEFAULT '', category_code text NOT NULL, pricing_basis text NOT NULL, unit_amount numeric(14,2) NOT NULL, quantity numeric(10,2) NOT NULL DEFAULT 1 CHECK (quantity > 0), line_total numeric(14,2) NOT NULL, included_distance_km integer, conditions text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_state_requirements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), state text NOT NULL REFERENCES public.commercial_state_registry(state) ON DELETE CASCADE, document_type text NOT NULL, label text NOT NULL, is_required boolean NOT NULL DEFAULT true, applies_when jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (state, document_type) );
CREATE TABLE IF NOT EXISTS public.commission_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid NOT NULL REFERENCES public.commission_schedules(id) ON DELETE CASCADE, label text NOT NULL, priority int NOT NULL DEFAULT 100, service_code text, scope_label text, category_code text, country text, region text, city text, account_id uuid, customer_segment text, partner_id uuid, operator_id uuid, fleet_id uuid, contract_id uuid, transaction_type text, partner_tier text, promotion_code text, min_volume numeric, max_volume numeric, rate_percent numeric NOT NULL CHECK (rate_percent >= 0 AND rate_percent <= 100), basis text CHECK (basis IS NULL OR basis IN ('base_fare','service_price','net_service_price', 'eligible_transaction_amount','completed_service_amount','collected_amount','gross_customer_total')), min_commission numeric, max_commission numeric, effective_from date, effective_to date, reason text, active boolean NOT NULL DEFAULT true, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.comms_account_grants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.comms_accounts(id) ON DELETE CASCADE, role_key text, staff_id uuid REFERENCES public.staff_members(id) ON DELETE CASCADE, permission public.comms_grant_permission NOT NULL DEFAULT 'read', granted_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT comms_grant_subject_chk CHECK ((role_key IS NOT NULL) <> (staff_id IS NOT NULL)) );
CREATE TABLE IF NOT EXISTS public.comms_sync_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.comms_accounts(id) ON DELETE CASCADE, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, status text NOT NULL DEFAULT 'running', direction text, messages_ingested integer NOT NULL DEFAULT 0, error_message text, triggered_by uuid );
CREATE TABLE IF NOT EXISTS public.comms_threads ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.comms_accounts(id) ON DELETE CASCADE, external_thread_key text, subject text NOT NULL DEFAULT '(no subject)', counterparty_name text, counterparty_email text, category public.comms_category NOT NULL DEFAULT 'external', status public.comms_thread_status NOT NULL DEFAULT 'unread', priority text NOT NULL DEFAULT 'normal', owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, message_count integer NOT NULL DEFAULT 0, inbound_count integer NOT NULL DEFAULT 0, outbound_count integer NOT NULL DEFAULT 0, first_activity_at timestamptz NOT NULL DEFAULT now(), last_activity_at timestamptz NOT NULL DEFAULT now(), last_direction public.comms_direction, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.company_collateral_downloads ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, collateral_id uuid NOT NULL REFERENCES public.company_collateral(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), surface text NOT NULL DEFAULT 'staff_documents', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.compliance_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid REFERENCES public.compliance_jobs(id) ON DELETE SET NULL, driver_id uuid, vehicle_id uuid, alert_code text NOT NULL, severity public.risk_severity NOT NULL, status public.compliance_alert_status NOT NULL DEFAULT 'OPEN', title text NOT NULL, details jsonb DEFAULT '{}'::jsonb, resolved_at timestamptz, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.control_tower_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_number text NOT NULL UNIQUE DEFAULT 'CT-' || to_char(now(),'YYYYMM') || '-' || lpad(nextval('public.ct_alert_seq')::text, 6, '0'), rule_key text NOT NULL REFERENCES public.control_tower_alert_rules(rule_key), condition_kind text NOT NULL, severity text NOT NULL CHECK (severity IN ('info','warning','critical')), status public.ct_alert_status NOT NULL DEFAULT 'CREATED', entity_type text NOT NULL, entity_id uuid, entity_ref text, tenant_id uuid, reason text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, observed_value numeric, threshold numeric, source_event_id uuid, correlation_id text NOT NULL DEFAULT gen_random_uuid()::text, dedupe_key text NOT NULL UNIQUE, owner_user_id uuid, occurrence_count integer NOT NULL DEFAULT 1, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz, acknowledged_by uuid, resolved_at timestamptz, resolved_by uuid, resolution text, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.country_document_requirements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES public.countries(id) ON DELETE CASCADE, document_type_id uuid REFERENCES public.kyc_document_types(id) ON DELETE CASCADE, required boolean NOT NULL DEFAULT true, applies_to text NOT NULL DEFAULT 'DRIVER', framework_id uuid REFERENCES public.regulatory_frameworks(id) ON DELETE SET NULL, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_id, document_type_id, applies_to) );
CREATE TABLE IF NOT EXISTS public.dependency_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.system_modules(id) ON DELETE CASCADE, depends_on_module_id uuid NOT NULL REFERENCES public.system_modules(id) ON DELETE CASCADE, dependency_type text NOT NULL DEFAULT 'HARD', notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (module_id, depends_on_module_id));
CREATE TABLE IF NOT EXISTS public.doc_security_marks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), doc_number text NOT NULL UNIQUE, security_number text NOT NULL UNIQUE, verification_token text NOT NULL UNIQUE, document_id uuid, domain_code text NOT NULL, class_code text NOT NULL, source_system text NOT NULL REFERENCES public.doc_source_systems(code), origin_ref text NOT NULL, doc_version int NOT NULL DEFAULT 1, template_code text, template_version text, template_hash text, data_snapshot_hash text, document_hash text, classification text NOT NULL DEFAULT 'INTERNAL', profile_code text NOT NULL REFERENCES public.doc_security_profiles(code), footer_line text NOT NULL, micro_code text NOT NULL, page_count int, status text NOT NULL DEFAULT 'issued' CHECK (status IN ('issued','valid','superseded','void','expired')), supersedes_mark_id uuid REFERENCES public.doc_security_marks(id), superseded_by_mark_id uuid REFERENCES public.doc_security_marks(id), expires_at timestamptz, issued_at timestamptz NOT NULL DEFAULT now(), created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_template_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES public.doc_templates(id) ON DELETE CASCADE, version text NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','IN_REVIEW','APPROVED','PUBLISHED','REJECTED','RETIRED')), body jsonb NOT NULL DEFAULT '[]'::jsonb, variables jsonb NOT NULL DEFAULT '[]'::jsonb, execution_block jsonb NOT NULL DEFAULT '{}'::jsonb, content_fingerprint text, source_status text NOT NULL DEFAULT 'SOURCE_VERIFIED' CHECK (source_status IN ('SOURCE_VERIFIED','SOURCE_DOCUMENT_REQUIRED')), notes text, author_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, author_user_id uuid, submitted_at timestamptz, approved_at timestamptz, published_at timestamptz, retired_at timestamptz, supersedes_version_id uuid REFERENCES public.doc_template_versions(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (template_id, version) );
CREATE TABLE IF NOT EXISTS public.document_escalations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), queue_id UUID NOT NULL REFERENCES public.document_review_queue(id) ON DELETE CASCADE, opened_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, assigned_to UUID REFERENCES auth.users(id) ON DELETE SET NULL, severity TEXT NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high','critical')), status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','investigating','resolved','closed')), reason TEXT NOT NULL, resolution TEXT, resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.document_review_actions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), queue_id UUID NOT NULL REFERENCES public.document_review_queue(id) ON DELETE CASCADE, action_type TEXT NOT NULL CHECK (action_type IN ('approve','reject','request_resubmission','escalate','assign','reassign','note','flag_fraud','expire')), actor_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, payload JSONB DEFAULT '{}'::jsonb, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.document_review_notes ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), queue_id UUID NOT NULL REFERENCES public.document_review_queue(id) ON DELETE CASCADE, author_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, body TEXT NOT NULL, internal BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.email_template_versions ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, template_name TEXT NOT NULL REFERENCES public.email_templates(name) ON DELETE CASCADE, version INTEGER NOT NULL, subject TEXT NOT NULL, html_body TEXT NOT NULL, text_body TEXT, notes TEXT, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (template_name, version) );
CREATE TABLE IF NOT EXISTS public.event_store ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), stream_id uuid REFERENCES public.event_streams(id) ON DELETE CASCADE, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, version bigint NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, metadata jsonb DEFAULT '{}'::jsonb, actor_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(aggregate_type, aggregate_id, version) );
CREATE TABLE IF NOT EXISTS public.feature_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), feature_key text UNIQUE NOT NULL, module_id uuid REFERENCES public.system_modules(id) ON DELETE SET NULL, enabled boolean NOT NULL DEFAULT false, rollout_percentage int NOT NULL DEFAULT 0 CHECK (rollout_percentage BETWEEN 0 AND 100), targeting jsonb NOT NULL DEFAULT '{}'::jsonb, description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fraud_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid REFERENCES public.fraud_cases(id) ON DELETE CASCADE, rule_id uuid REFERENCES public.fraud_rules(id) ON DELETE SET NULL, subject_type text NOT NULL, subject_id uuid NOT NULL, severity public.security_severity NOT NULL DEFAULT 'MEDIUM', message text NOT NULL, signal jsonb NOT NULL DEFAULT '{}'::jsonb, acknowledged boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fraud_investigations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_id uuid NOT NULL REFERENCES public.fraud_cases(id) ON DELETE CASCADE, investigator_id uuid, notes text, findings jsonb NOT NULL DEFAULT '{}'::jsonb, evidence_urls text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fx_gain_loss ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), revaluation_id uuid REFERENCES public.fx_revaluations(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES public.ledger_accounts(id), currency text NOT NULL, base_currency text NOT NULL, realized_cents bigint NOT NULL DEFAULT 0, unrealized_cents bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.idempotency_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key_id uuid NOT NULL REFERENCES public.idempotency_keys(id) ON DELETE CASCADE, event text NOT NULL, detail jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.identity_control_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_code text NOT NULL REFERENCES public.identity_controls(control_code) ON DELETE CASCADE, verdict text NOT NULL CHECK (verdict IN ('PASS','PARTIAL','FAIL','BLOCKED','NOT_TESTED','REQUIRES_EXTERNAL_ACTION')), environment text NOT NULL, observation text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}', blocked_reason text, executed_by uuid, executed_at timestamptz NOT NULL DEFAULT now(), digest text GENERATED ALWAYS AS (md5(control_code || verdict || observation)) STORED );
CREATE TABLE IF NOT EXISTS public.infra_health_checks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.infra_health_runs(id) ON DELETE CASCADE, environment_id uuid NOT NULL REFERENCES public.infra_environments(id) ON DELETE CASCADE, check_key text NOT NULL, result public.infra_check_result NOT NULL, observed text, expected text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.infra_orchestration_notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid REFERENCES public.infra_orchestration_runs(id) ON DELETE CASCADE, severity text NOT NULL CHECK (severity IN ('INFO','WARNING','CRITICAL')), title text NOT NULL, body text NOT NULL, environment_key text, step_key text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz, acknowledged_by uuid );
CREATE TABLE IF NOT EXISTS public.infra_orchestration_steps ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.infra_orchestration_runs(id) ON DELETE CASCADE, step_key text NOT NULL, environment_key text, sequence_no integer NOT NULL DEFAULT 0, attempt integer NOT NULL DEFAULT 1, state text NOT NULL CHECK (state IN ('STARTED','SUCCEEDED','FAILED','SKIPPED','ROLLED_BACK','BLOCKED','RETRYING')), idempotency_key text, reused_evidence boolean NOT NULL DEFAULT false, detail jsonb NOT NULL DEFAULT '{}'::jsonb, error_code text, error_message text, rollback_action text, rollback_result text, duration_ms integer, recorded_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.intern_supply_opportunities ( id uuid primary key default gen_random_uuid(), intern_id uuid not null references public.intern_profiles(id) on delete cascade, cohort_id uuid references public.intern_cohorts(id) on delete set null, destination_id uuid references public.intern_supply_destinations(id) on delete set null, supplier_id uuid references public.intern_supply_fleet_suppliers(id) on delete set null, title text not null, product_line text not null, customer_segment text, requirement text, stage text not null default 'LEAD' check (stage in ('LEAD','QUALIFIED','OPPORTUNITY','CUSTOMER','BOOKING','COMPLETED_SERVICE','VERIFIED_REVENUE','LOST')), estimated_value_kes numeric, verified_revenue_kes numeric not null default 0 check (verified_revenue_kes >= 0), verified_source_table text, verified_source_id uuid, verified_by uuid, verified_at timestamptz, review_status text not null default 'SUBMITTED' check (review_status in ('SUBMITTED','ACCEPTED','RETURNED','REJECTED')), evidence_url text, notes text, is_demo boolean not null default true, created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint intern_supply_opp_revenue_evidence check (verified_revenue_kes = 0 or (verified_source_table is not null and verified_source_id is not null and verified_by is not null)) );
CREATE TABLE IF NOT EXISTS public.legal_obligation_assignments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), obligation_id uuid NOT NULL REFERENCES public.legal_obligations(id) ON DELETE CASCADE, assignee_user_id uuid, assignee_role text, assigned_by uuid, assigned_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz, completed_at timestamptz, completion_note text, evidence_id uuid REFERENCES public.legal_evidence(id) ON DELETE SET NULL, status public.legal_status NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.lg_dossier_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_version_id uuid NOT NULL REFERENCES public.lg_dossier_documents(id) ON DELETE RESTRICT, control_id text NOT NULL, document_version integer NOT NULL, content_hash text NOT NULL, approver_kind text NOT NULL, decision text NOT NULL, conditions text, evidence_ref text, issuing_authority text, effective_from timestamptz, effective_until timestamptz, comments text NOT NULL, decided_by uuid NOT NULL, decided_by_email text, decided_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT lg_approval_kind_valid CHECK (approver_kind IN ('legal_reviewer','insurer','owner')), CONSTRAINT lg_approval_decision_valid CHECK (decision IN ('approved','approved_with_conditions','rejected')), CONSTRAINT lg_approval_window CHECK (effective_until IS NULL OR effective_from IS NULL OR effective_until > effective_from), CONSTRAINT lg_approval_once_per_kind UNIQUE (document_version_id, approver_kind) );
CREATE TABLE IF NOT EXISTS public.lg_dossier_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_id text NOT NULL, document_version_id uuid REFERENCES public.lg_dossier_documents(id) ON DELETE RESTRICT, document_version integer, content_hash text, action text NOT NULL, approver_kind text, decision text, actor_user_id uuid, actor_email text, prior_version integer, prior_content_hash text, changes jsonb NOT NULL DEFAULT '{}'::jsonb, detail text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT lg_audit_action_valid CHECK (action IN ('SEEDED','VERSION_PUBLISHED','SUPERSEDED','APPROVAL_RECORDED')) );
CREATE TABLE IF NOT EXISTS public.location_streams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid REFERENCES public.tracking_sessions(id) ON DELETE CASCADE, subject_id uuid NOT NULL, lat double precision NOT NULL, lng double precision NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), speed_kph numeric(5,2), heading numeric(5,2));
CREATE TABLE IF NOT EXISTS public.meeting_type_hosts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_type_id uuid NOT NULL REFERENCES public.meeting_types(id) ON DELETE CASCADE, staff_id uuid NOT NULL REFERENCES public.staff_members(id) ON DELETE CASCADE, public_name text NOT NULL, public_role text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (meeting_type_id, staff_id) );
CREATE TABLE IF NOT EXISTS public.nav_drift_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fingerprint text NOT NULL, kind text NOT NULL, severity text NOT NULL DEFAULT 'warning', title text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, version_id uuid REFERENCES public.nav_registry_versions(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'open', occurrences integer NOT NULL DEFAULT 1, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), notified_at timestamptz, acknowledged_by uuid, acknowledged_at timestamptz, resolved_at timestamptz, CONSTRAINT nav_drift_kind_chk CHECK (kind IN ('crawler_integrity','capability_drift','rbac_drift','snapshot_hash_drift','orphan_route')), CONSTRAINT nav_drift_sev_chk CHECK (severity IN ('info','warning','critical')), CONSTRAINT nav_drift_status_chk CHECK (status IN ('open','acknowledged','resolved')), CONSTRAINT nav_drift_fingerprint_open UNIQUE (fingerprint) );
CREATE TABLE IF NOT EXISTS public.nav_registry_audit ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, version_id uuid NOT NULL REFERENCES public.nav_registry_versions(id) ON DELETE CASCADE, action text NOT NULL, from_status text, to_status text, actor uuid DEFAULT auth.uid(), detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ocr_validation_results ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), extraction_id uuid NOT NULL REFERENCES public.ocr_extractions(id) ON DELETE CASCADE, field text NOT NULL, expected text, actual text, passed boolean NOT NULL, severity public.risk_severity NOT NULL DEFAULT 'LOW', message text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ops_propagation_outbox ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_item_id uuid REFERENCES public.staff_work_items(id) ON DELETE CASCADE, ops_event_id uuid REFERENCES public.ops_events(id) ON DELETE SET NULL, audience text NOT NULL, channel text NOT NULL DEFAULT 'portal', recipient_user_id uuid, recipient_ref text, entity_type text, entity_id uuid, subject text NOT NULL, message text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, last_error text, read_at timestamptz, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ops_prop_audience_chk CHECK (audience IN ('customer','provider','corporate','staff','finance')), CONSTRAINT ops_prop_channel_chk CHECK (channel IN ('portal','email','webhook')), CONSTRAINT ops_prop_status_chk CHECK (status IN ('pending','delivered','skipped','failed')) );
CREATE TABLE IF NOT EXISTS public.opt_experiments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, hypothesis text NOT NULL, cohort_kind text NOT NULL, cohort_definition jsonb NOT NULL DEFAULT '{}'::jsonb, control jsonb NOT NULL, treatment jsonb NOT NULL, primary_metric_code text NOT NULL REFERENCES public.opt_metrics(code), guardrail_metric_codes text[] NOT NULL DEFAULT '{}', starts_at timestamptz, ends_at timestamptz, state public.opt_experiment_state NOT NULL DEFAULT 'DECLARED', decision text, decision_reason text, decided_by uuid, decided_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.opt_measurements ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metric_code text NOT NULL REFERENCES public.opt_metrics(code), scope_kind text NOT NULL, scope_ref text, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, value numeric, sample_size integer NOT NULL DEFAULT 0, sufficiency public.opt_sufficiency NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, computed_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT opt_measurement_value_law CHECK ( (sufficiency = 'SUFFICIENT' AND value IS NOT NULL) OR (sufficiency <> 'SUFFICIENT' AND value IS NULL) ) );
CREATE TABLE IF NOT EXISTS public.paf_exception_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_id uuid NOT NULL REFERENCES public.paf_exceptions(id) ON DELETE CASCADE, action text NOT NULL CHECK (action IN ('submitted','approved','rejected','revoked','expired','edited')), actor_id uuid REFERENCES auth.users(id), reason text, previous_status text, new_status text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.paf_remediation_applications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), approval_id uuid NOT NULL REFERENCES public.paf_remediation_approvals(id) ON DELETE CASCADE, run_id uuid, resource text NOT NULL, severity text NOT NULL, sql_text text NOT NULL, sql_hash text NOT NULL, applied_by uuid REFERENCES auth.users(id), applied_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL CHECK (status IN ('success','failed','rolled_back')), error_message text, rows_affected integer, confirmation_text text, rollback_sql text, notes text );
CREATE TABLE IF NOT EXISTS public.partner_golive_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES public.partner_golive_reviews(id) ON DELETE CASCADE, action text NOT NULL, actor_id uuid, note text, snapshot jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_lifecycle_signals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id text NOT NULL, lifecycle_stage text NOT NULL, maturity_level text, network_category text, intent_bring text, ab_variant text, page_source text, work_item_id uuid REFERENCES public.partner_work_items(id) ON DELETE SET NULL, profile_id uuid REFERENCES public.partner_intent_profiles(id) ON DELETE SET NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_profile_history ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.partner_intent_profiles(id) ON DELETE CASCADE, contact_email text NOT NULL, change_kind text NOT NULL CHECK (change_kind IN ('created','updated','reverted')), intent_bring text, network_category text, maturity_level text, lifecycle_stage text, commercial_model text, partner_type text, ab_variant text, session_id text, changed_fields text[] NOT NULL DEFAULT '{}', changed_by uuid, reverted_from_history_id uuid REFERENCES public.partner_profile_history(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_quotes ( id uuid primary key default gen_random_uuid(), quote_code text not null unique default ('PQ-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), request_id uuid not null references public.capacity_requests(id) on delete cascade, partner_id uuid not null references public.partners(id) on delete cascade, state text not null default 'REQUESTED' check (state in ('REQUESTED','VIEWED','DRAFT','SUBMITTED','UNDER_REVIEW','ACCEPTED','REJECTED','EXPIRED','WITHDRAWN')), currency text not null default 'KES', quoted_amount numeric(14,2), tax_amount numeric(14,2) not null default 0, fees_amount numeric(14,2) not null default 0, commission_pct numeric(6,3), commission_amount numeric(14,2), partner_net numeric(14,2), yalla_margin numeric(14,2), validity_until timestamptz, inclusions text, exclusions text, terms text, decision_notes text, response_minutes integer, order_id uuid references public.mobility_orders(id) on delete set null, requested_by uuid, submitted_by uuid, decided_by uuid, requested_at timestamptz not null default now(), submitted_at timestamptz, decided_at timestamptz, is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (request_id, partner_id) );
CREATE TABLE IF NOT EXISTS public.partner_wl_evidence_artifacts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL, evidence_id uuid REFERENCES public.partner_wl_evidence(id) ON DELETE SET NULL, document_key text NOT NULL, version integer NOT NULL, title text NOT NULL, file_name text NOT NULL, storage_path text NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL CHECK (byte_size >= 0), sha256 text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'), note text, uploaded_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, document_key, version) );
CREATE TABLE IF NOT EXISTS public.partner_wl_evidence_signatures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), evidence_id uuid NOT NULL REFERENCES public.partner_wl_evidence(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES public.partner_wl_tenants(id) ON DELETE CASCADE, partner_id uuid NOT NULL, key_id text NOT NULL, algorithm text NOT NULL DEFAULT 'Ed25519', signature_b64 text NOT NULL, signed_statement text NOT NULL, statement_hash text NOT NULL, signed_by uuid, signed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_work_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_item_id uuid NOT NULL REFERENCES public.partner_work_items(id) ON DELETE CASCADE, action text NOT NULL, from_state public.partner_case_state, to_state public.partner_case_state, note text, actor_id uuid, actor_email text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.phishing_takedowns ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), report_id UUID REFERENCES public.phishing_reports(id) ON DELETE CASCADE, target_artifact TEXT NOT NULL, target_type TEXT NOT NULL, registrar_or_provider TEXT, submitted_at TIMESTAMPTZ, acknowledged_at TIMESTAMPTZ, taken_down_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'pending', notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.posting_errors ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid REFERENCES public.posting_batches(id), journal_id uuid REFERENCES public.journals(id), error_code text NOT NULL, error_message text NOT NULL, context jsonb NOT NULL DEFAULT '{}'::jsonb, attempts int NOT NULL DEFAULT 1, resolved boolean NOT NULL DEFAULT false, resolved_at timestamptz, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.posting_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid REFERENCES public.posting_batches(id), journal_id uuid REFERENCES public.journals(id), event_type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.projection_drift_findings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scan_id uuid NOT NULL REFERENCES public.projection_drift_scans(id) ON DELETE CASCADE, payment_attempt_id uuid NOT NULL, correlation_id text, projection_name text NOT NULL, canonical_state text NOT NULL, projection_state text, severity text NOT NULL CHECK (severity IN ('healthy','minor','major','critical')), detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_application_answers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, blueprint_id uuid REFERENCES public.rec_blueprints(id) ON DELETE SET NULL, blueprint_version integer, question_key text NOT NULL, question_prompt text NOT NULL, question_kind text NOT NULL, classification text NOT NULL, answer jsonb NOT NULL DEFAULT 'null'::jsonb, score numeric, knockout_failed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (application_id, question_key) );
CREATE TABLE IF NOT EXISTS public.rec_application_evaluations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, scorecard_id uuid NOT NULL REFERENCES public.rec_scorecards(id), scorecard_version integer NOT NULL, eligibility text NOT NULL, weighted_score numeric NOT NULL DEFAULT 0, max_score numeric NOT NULL DEFAULT 0, criterion_results jsonb NOT NULL DEFAULT '[]'::jsonb, gate_failures text[] NOT NULL DEFAULT '{}', missing_evidence text[] NOT NULL DEFAULT '{}', recommendation text NOT NULL, confidence numeric, engine text NOT NULL DEFAULT 'rec_evaluate_application/v1', computed_by uuid, computed_at timestamptz NOT NULL DEFAULT now(), is_current boolean NOT NULL DEFAULT true, CONSTRAINT rec_eval_eligibility_ck CHECK (eligibility IN ('eligible','not_eligible','requires_review')), CONSTRAINT rec_eval_reco_ck CHECK (recommendation IN ('advance','review','do_not_advance')) );
CREATE TABLE IF NOT EXISTS public.rec_assessment_template_items ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES public.rec_assessment_templates(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.rec_question_bank(id), sort_order integer NOT NULL DEFAULT 0, max_marks numeric NOT NULL CHECK (max_marks > 0), critical_min numeric, mandatory boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_template_items_uk UNIQUE (template_id, question_id) );
CREATE TABLE IF NOT EXISTS public.rec_assessments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), interview_id uuid NOT NULL REFERENCES public.rec_interviews(id) ON DELETE CASCADE, application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, template_id uuid NOT NULL REFERENCES public.rec_assessment_templates(id), template_key text NOT NULL, template_version integer NOT NULL, assessor_user_id uuid NOT NULL DEFAULT auth.uid(), assessor_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, assessor_name text, status text NOT NULL DEFAULT 'draft', total_score numeric, max_score numeric NOT NULL DEFAULT 0, percentage numeric, band text, gate_status jsonb NOT NULL DEFAULT '[]'::jsonb, gates_passed boolean, recommendation text, strengths text, concerns text, risks text, submitted_at timestamptz, amended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_assessments_assessor_uk UNIQUE (interview_id, assessor_user_id), CONSTRAINT rec_assessments_status_ck CHECK (status IN ('draft','submitted','amended')), CONSTRAINT rec_assessments_reco_ck CHECK (recommendation IS NULL OR recommendation IN ('strong_advance','advance','hold','reject','strong_reject')) );
CREATE TABLE IF NOT EXISTS public.rec_blueprint_questions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), blueprint_id uuid NOT NULL REFERENCES public.rec_blueprints(id) ON DELETE CASCADE, ord integer NOT NULL DEFAULT 1, question_key text NOT NULL, prompt text NOT NULL, help_text text, kind text NOT NULL CHECK (kind IN ('text','long_text','single_choice','multi_choice','boolean','number','date')), options jsonb NOT NULL DEFAULT '[]'::jsonb, is_required boolean NOT NULL DEFAULT true, classification text NOT NULL DEFAULT 'informational' CHECK (classification IN ('required','preferred','knockout','scored','informational')), weight numeric NOT NULL DEFAULT 0, expected jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (blueprint_id, question_key) );
CREATE TABLE IF NOT EXISTS public.rec_candidate_notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), remediation_case_id uuid REFERENCES public.rec_application_remediation_cases(id) ON DELETE SET NULL, email text NOT NULL, vacancy_slug text, kind text NOT NULL, subject text NOT NULL, body text NOT NULL, continue_url text, delivery_status text NOT NULL DEFAULT 'QUEUED', provider_message_id text, error text, build_id text, created_at timestamptz NOT NULL DEFAULT now(), dispatched_at timestamptz );
CREATE TABLE IF NOT EXISTS public.rec_comm_reconciliation_findings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.rec_comm_reconciliation_runs(id) ON DELETE CASCADE, request_id uuid REFERENCES public.rec_comm_requests(id) ON DELETE CASCADE, finding_code text NOT NULL, severity text NOT NULL DEFAULT 'warning', observed_state text, action_taken text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_document_requirement_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), set_id uuid NOT NULL REFERENCES public.rec_document_requirement_sets(id) ON DELETE CASCADE, doc_key text NOT NULL, label text NOT NULL, doc_class text NOT NULL DEFAULT 'role_specific' CHECK (doc_class IN ('universal','education','graduation','role_specific','optional')), doc_type text NOT NULL DEFAULT 'certificate' CHECK (doc_type IN ('cv','cover_letter','certificate','supporting')), mandatory boolean NOT NULL DEFAULT true, per_completed_year boolean NOT NULL DEFAULT false, allow_consolidated boolean NOT NULL DEFAULT false, requires_verification boolean NOT NULL DEFAULT true, condition jsonb NOT NULL DEFAULT '{}'::jsonb, why_required text, ord integer NOT NULL DEFAULT 100, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (set_id, doc_key) );
CREATE TABLE IF NOT EXISTS public.rec_migration_files ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.rec_migration_batches(id) ON DELETE CASCADE, original_file_name text NOT NULL, storage_path text NOT NULL, mime_type text, size_bytes bigint, sha256 text NOT NULL, file_kind text NOT NULL DEFAULT 'unknown' CHECK (file_kind IN ('structured','document','archive','unknown')), doc_type text NOT NULL DEFAULT 'cv' CHECK (doc_type IN ('cv','cover_letter','certificate','identification','portfolio','reference','other')), status text NOT NULL DEFAULT 'stored' CHECK (status IN ('stored','queued','parsing','parsed','failed','skipped')), parse_error text, extracted_text text, page_count integer, attempts integer NOT NULL DEFAULT 0, uploaded_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (batch_id, sha256, original_file_name) );
CREATE TABLE IF NOT EXISTS public.rec_migration_records ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.rec_migration_batches(id) ON DELETE CASCADE, source_row_key text NOT NULL, source_row_no integer, source_platform text, source_candidate_ref text, source_application_ref text, source_vacancy_ref text, source_status text, source_applied_at timestamptz, raw_payload jsonb NOT NULL DEFAULT '{}'::jsonb, normalized jsonb NOT NULL DEFAULT '{}'::jsonb, extraction jsonb NOT NULL DEFAULT '{}'::jsonb, extraction_confidence numeric, state text NOT NULL DEFAULT 'UPLOADED' CHECK (state IN ('UPLOADED','VALIDATING','QUEUED','PARSING','PARSED','IDENTITY_MATCHING','DUPLICATE_REVIEW','VACANCY_MAPPING','MATCHING','READY_FOR_REVIEW','APPROVED','REJECTED','IMPORTED','FAILED','EXCEPTION','ROLLED_BACK')), exception_code text, exception_reason text, candidate_id uuid REFERENCES public.rec_candidates(id) ON DELETE SET NULL, identity_match_kind text CHECK (identity_match_kind IN ('new','exact','probable','possible')), identity_similarity numeric, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, vacancy_map_kind text CHECK (vacancy_map_kind IN ('existing','historical','unmatched')), match_score numeric, match_breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, review_decision text CHECK (review_decision IN ('import','import_after_review','do_not_import')), reviewed_by uuid, reviewed_at timestamptz, review_notes text, imported_candidate_id uuid, imported_application_id uuid, imported_at timestamptz, import_outcome text, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (batch_id, source_row_key) );
CREATE TABLE IF NOT EXISTS public.rec_panel_reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'locked', evaluation_count integer NOT NULL DEFAULT 0, average_score numeric, recommendation_mix jsonb NOT NULL DEFAULT '{}'::jsonb, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, evidence_hash text, panel_decision text, decision_notes text, reason_code text REFERENCES public.rec_rejection_reasons(code), opened_by uuid, opened_at timestamptz NOT NULL DEFAULT now(), decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_panel_reviews_status_ck CHECK (status = ANY (ARRAY['locked','decided'])), CONSTRAINT rec_panel_reviews_decision_ck CHECK (panel_decision IS NULL OR panel_decision = ANY (ARRAY['advance','hold','reject'])) );
CREATE TABLE IF NOT EXISTS public.rec_paper_assessments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, interview_id uuid REFERENCES public.rec_interviews(id) ON DELETE SET NULL, evaluation_id uuid REFERENCES public.rec_evaluations(id) ON DELETE SET NULL, form_reference text NOT NULL, scan_path text, name_as_written text NOT NULL, position_as_written text, interview_date date, id_no_as_written text, highest_education_as_written text, experience_as_written text, location_as_written text, criteria_ratings jsonb NOT NULL DEFAULT '[]'::jsonb, unrated_criteria text[] NOT NULL DEFAULT '{}'::text[], recommendation_as_marked text, interviewer_comments text, interviewer_signature_present boolean NOT NULL DEFAULT false, transcription_confidence text NOT NULL DEFAULT 'medium', transcription_notes text, recorded_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_paper_conf_ck CHECK (transcription_confidence = ANY (ARRAY['high','medium','low'])), CONSTRAINT rec_paper_form_uk UNIQUE (application_id, form_reference) );
CREATE TABLE IF NOT EXISTS public.rec_profession_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL, candidate_id uuid NOT NULL, template_id uuid NOT NULL REFERENCES public.rec_assessment_templates(id), template_key text NOT NULL, template_version integer NOT NULL, attempt_no integer NOT NULL DEFAULT 1, attempt_token text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'issued', band_rules jsonb NOT NULL DEFAULT '{}'::jsonb, issued_by uuid, issued_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'), started_at timestamptz, submitted_at timestamptz, auto_score numeric, rubric_score numeric, total_score numeric, max_score numeric NOT NULL DEFAULT 0, percentage numeric, band text, gate_status jsonb NOT NULL DEFAULT '{}'::jsonb, gates_passed boolean, recommendation text, reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_profession_attempts_status_chk CHECK (status IN ('issued','in_progress','submitted','scored','expired','void')), CONSTRAINT rec_profession_attempts_unique UNIQUE (application_id, template_id, attempt_no) );
CREATE TABLE IF NOT EXISTS public.rec_question_review_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES public.rec_question_bank(id) ON DELETE CASCADE, question_key text NOT NULL, question_version integer NOT NULL, action text NOT NULL, status_before text, status_after text NOT NULL, actor_user_id uuid, note text, question_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_requirement_lifecycle_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), set_id uuid NOT NULL REFERENCES public.rec_document_requirement_sets(id) ON DELETE CASCADE, vacancy_id uuid REFERENCES public.rec_vacancies(id) ON DELETE SET NULL, version integer, action text NOT NULL, status_before text, status_after text, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_scorecard_criteria ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scorecard_id uuid NOT NULL REFERENCES public.rec_scorecards(id) ON DELETE CASCADE, code text NOT NULL, label text NOT NULL, criterion_type text NOT NULL, weight integer NOT NULL DEFAULT 0, min_threshold numeric, evidence_source text NOT NULL DEFAULT 'cv', scoring_method text NOT NULL DEFAULT 'threshold', guidance text, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_criteria_type_ck CHECK (criterion_type IN ('hard_gate','scored','preferred','evidence')), CONSTRAINT rec_criteria_method_ck CHECK (scoring_method IN ('threshold','presence','ratio','manual')), CONSTRAINT rec_criteria_weight_ck CHECK (weight >= 0 AND weight <= 100), CONSTRAINT rec_criteria_code_uk UNIQUE (scorecard_id, code) );
CREATE TABLE IF NOT EXISTS public.rec_vacancy_competencies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, competency_code text NOT NULL REFERENCES public.rec_competencies(code), weight numeric NOT NULL DEFAULT 1, min_marks numeric, mandatory boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (vacancy_id, competency_code) );
CREATE TABLE IF NOT EXISTS public.regulatory_exports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES public.regulatory_reports(id) ON DELETE CASCADE, period_start date NOT NULL, period_end date NOT NULL, format public.reg_export_format NOT NULL DEFAULT 'CSV', file_path text, sha256 text, totals jsonb NOT NULL DEFAULT '{}'::jsonb, generated_at timestamptz NOT NULL DEFAULT now(), generated_by uuid, signature_id uuid REFERENCES public.digital_signatures(id), UNIQUE (report_id, period_start, period_end, format) );
CREATE TABLE IF NOT EXISTS public.rental_control_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_code text NOT NULL REFERENCES public.rental_controls(control_code), verdict text NOT NULL CHECK (verdict IN ('PASS','FAIL','PARTIAL','BLOCKED','NOT_TESTED','REQUIRES_EXTERNAL_ACTION')), environment text NOT NULL, executed_at timestamptz NOT NULL DEFAULT now(), executed_by text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, blocked_reason text, digest text );
CREATE TABLE IF NOT EXISTS public.rental_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_code text NOT NULL REFERENCES public.rental_exception_policies(exception_code), subject_type text NOT NULL, subject_id uuid, subject_ref text, correlation_id uuid, saga_run_id uuid REFERENCES public.rental_saga_runs(id) ON DELETE SET NULL, state text NOT NULL DEFAULT 'OPEN' CHECK (state IN ('OPEN','AUTO_RESOLVED','ESCALATED','RESOLVED','PARKED')), severity text NOT NULL, attempts integer NOT NULL DEFAULT 0, detail jsonb NOT NULL DEFAULT '{}'::jsonb, resolution text, resolved_by uuid, opened_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz );
CREATE TABLE IF NOT EXISTS public.rental_gate_controls ( gate_code text NOT NULL REFERENCES public.rental_release_gates(gate_code) ON DELETE CASCADE, control_code text NOT NULL REFERENCES public.rental_controls(control_code) ON DELETE CASCADE, PRIMARY KEY (gate_code, control_code) );
CREATE TABLE IF NOT EXISTS public.rental_policy_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_code text NOT NULL REFERENCES public.rental_policies(policy_code) ON DELETE CASCADE, version integer NOT NULL, rule_type text NOT NULL DEFAULT 'CONFIGURABLE', scope jsonb NOT NULL DEFAULT '{}'::jsonb, config jsonb NOT NULL DEFAULT '{}'::jsonb, effective_from date NOT NULL DEFAULT current_date, effective_to date, state text NOT NULL DEFAULT 'PENDING_BUSINESS_APPROVAL' CHECK (state IN ('PENDING_BUSINESS_APPROVAL','ACTIVE','SUPERSEDED','REJECTED')), proposed_basis text, approval_authority text, proposed_by uuid, approved_by uuid, approved_at timestamptz, approval_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (policy_code, version) );
CREATE TABLE IF NOT EXISTS public.rental_saga_steps ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.rental_saga_runs(id) ON DELETE CASCADE, step text NOT NULL, state text NOT NULL CHECK (state IN ('DONE','FAILED','COMPENSATED','SKIPPED')), compensation text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_unit_readiness_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), unit_id uuid NOT NULL REFERENCES public.rental_fleet_units(id) ON DELETE CASCADE, check_code text NOT NULL REFERENCES public.rental_unit_readiness_checks(check_code), verdict text NOT NULL CHECK (verdict IN ('PASS','FAIL','BLOCKED','NOT_TESTED','REQUIRES_EXTERNAL_ACTION')), evidence text NOT NULL, document_ref text, valid_until date, recorded_by uuid, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE (unit_id, check_code) );
CREATE TABLE IF NOT EXISTS public.report_export_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid REFERENCES public.report_export_schedules(id) ON DELETE CASCADE, report_key text NOT NULL, format text NOT NULL, recipients jsonb NOT NULL DEFAULT '[]'::jsonb, range_from timestamptz, range_to timestamptz, row_count integer NOT NULL DEFAULT 0, csv_bytes integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', error text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.revenue_allocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.revenue_events(id) ON DELETE CASCADE, kind public.revenue_allocation_kind NOT NULL, amount_cents bigint NOT NULL, currency text NOT NULL DEFAULT 'KES', account_code text REFERENCES public.chart_of_accounts(code), memo text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.revenue_idempotency_checks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES public.revenue_idempotency_runs(id) ON DELETE CASCADE, transaction_id uuid, transaction_ref text NOT NULL, replays int NOT NULL, events_before int NOT NULL, events_after int NOT NULL, amount_before_cents bigint NOT NULL DEFAULT 0, amount_after_cents bigint NOT NULL DEFAULT 0, revenue_event_id_before uuid, revenue_event_id_after uuid, idempotent boolean NOT NULL, duplicate_detected boolean NOT NULL, emitter_responses jsonb NOT NULL DEFAULT '[]'::jsonb, detail text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.risk_predictions ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), model_id UUID REFERENCES public.risk_models(id) ON DELETE SET NULL, event_ref UUID, entity_type public.risk_entity_type NOT NULL, entity_id UUID, predicted_score NUMERIC(5,2) NOT NULL, band TEXT NOT NULL, feature_contributions JSONB NOT NULL DEFAULT '{}'::JSONB, predicted_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_commission_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_no text NOT NULL UNIQUE, source_type text NOT NULL CHECK (source_type IN ('booking','transaction','manual')), source_id text NOT NULL, booking_ref text, lead_context text, product_scope text, qualified_revenue_cents bigint NOT NULL CHECK (qualified_revenue_cents >= 0), currency text NOT NULL DEFAULT 'KES', period_month date NOT NULL, plan_id uuid NOT NULL REFERENCES public.sales_commission_plans(id), owner_position_code text NOT NULL, owner_staff_id uuid, attribution_role text NOT NULL DEFAULT 'primary' CHECK (attribution_role IN ('primary','supporting')), share_pct numeric(5,2) NOT NULL DEFAULT 100 CHECK (share_pct > 0 AND share_pct <= 100), base_rate_bp integer NOT NULL, base_commission_cents bigint NOT NULL, performance_rate_bp integer NOT NULL DEFAULT 0, performance_eligible boolean NOT NULL DEFAULT false, performance_commission_cents bigint NOT NULL DEFAULT 0, total_commission_cents bigint NOT NULL, revenue_qualification jsonb NOT NULL DEFAULT '{}'::jsonb, kpi_outcome jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_approval','approved','rejected','attributed')), approver_id uuid, decided_at timestamptz, decision_reason text, idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commission_never_for_interns CHECK (owner_position_code NOT ILIKE '%intern%' AND owner_position_code NOT LIKE 'TSI-%') );
CREATE TABLE IF NOT EXISTS public.sales_kpi_close_emails ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), close_id uuid NOT NULL UNIQUE REFERENCES public.sales_kpi_closes(id) ON DELETE CASCADE, staff_member_id uuid NOT NULL, grain text NOT NULL, period_start date NOT NULL, recipient_email text, status text NOT NULL DEFAULT 'PENDING', attempts integer NOT NULL DEFAULT 0, error_text text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT sales_kpi_close_emails_status_chk CHECK (status IN ('PENDING','SENT','FAILED','NO_EMAIL_ON_RECORD')) );
CREATE TABLE IF NOT EXISTS public.sales_lead_service_request_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.sales_lead_service_requests(id) ON DELETE CASCADE, action text NOT NULL, status_from text, status_to text, note text, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_period_adjustments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), closure_id uuid NOT NULL REFERENCES public.sales_period_closures(id) ON DELETE CASCADE, amount_kes numeric(14,2) NOT NULL, reason text NOT NULL, authorised_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_sla_clocks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), process text NOT NULL, policy_id uuid REFERENCES public.sales_sla_policies(id), entity_type text NOT NULL, entity_id uuid NOT NULL, entity_ref text, staff_member_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, work_item_id uuid, sla_minutes int NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, paused_at timestamptz, paused_minutes int NOT NULL DEFAULT 0, completed_at timestamptz, breached_at timestamptz, escalation_level int NOT NULL DEFAULT 0, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_target_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), target_id uuid REFERENCES public.sales_targets(id) ON DELETE SET NULL, action text NOT NULL, scope text, staff_member_id uuid, before_value jsonb, after_value jsonb, actor_user_id uuid, note text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.service_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_code text UNIQUE NOT NULL, service_type text NOT NULL, module_id uuid REFERENCES public.system_modules(id) ON DELETE SET NULL, endpoint text, health_status public.health_status NOT NULL DEFAULT 'UNKNOWN', last_health_check_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.social_credentials ( connection_id uuid PRIMARY KEY REFERENCES public.social_connections(id) ON DELETE CASCADE, access_token text, refresh_token text, token_type text, expires_at timestamptz, scopes text[], rotated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_media_assets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), filename text NOT NULL, mime_type text NOT NULL, size_bytes bigint, width integer, height integer, duration_ms integer, checksum text, storage_path text NOT NULL, campaign_id uuid REFERENCES public.social_campaigns(id) ON DELETE SET NULL, license text, status text NOT NULL DEFAULT 'READY' CHECK (status IN ('UPLOADING','PROCESSING','READY','BLOCKED','ARCHIVED')), validation jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_posts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid REFERENCES public.social_campaigns(id) ON DELETE SET NULL, title text NOT NULL, master_caption text NOT NULL DEFAULT '', internal_notes text, market text NOT NULL DEFAULT 'GLOBAL', template_key text, ai_assisted boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','SUBMITTED','IN_REVIEW','CHANGES_REQUESTED','APPROVED','SCHEDULED','PUBLISHING','PUBLISHED','PARTIALLY_PUBLISHED','FAILED','ARCHIVED')), version integer NOT NULL DEFAULT 1, approved_version integer, approved_by uuid, approved_at timestamptz, scheduled_at timestamptz, published_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.twin_regression_alerts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id UUID REFERENCES public.digital_twin_runs(id) ON DELETE CASCADE, severity TEXT NOT NULL DEFAULT 'warning', kind TEXT NOT NULL, message TEXT NOT NULL, readiness_score INTEGER, previous_score INTEGER, details JSONB NOT NULL DEFAULT '{}'::jsonb, acknowledged_at TIMESTAMPTZ, acknowledged_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.work_triage_norms ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_kind text NOT NULL, stage_key text NOT NULL DEFAULT 'DEFAULT', label text NOT NULL, effort_minutes integer NOT NULL, sla_minutes integer, default_band text NOT NULL DEFAULT 'P3' REFERENCES public.work_triage_bands(band), next_action_template text, expected_outcome text, notes text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (work_kind, stage_key) );
CREATE TABLE IF NOT EXISTS public.ai_recommendations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES public.ai_agents(id), agent_version_id uuid REFERENCES public.ai_agent_versions(id), recommendation_type text NOT NULL, priority public.ai_priority NOT NULL DEFAULT 'P2', entity_type text NOT NULL, entity_id uuid, entity_ref text, observation text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, reasoning_summary text NOT NULL, alternatives jsonb NOT NULL DEFAULT '[]'::jsonb, recommended_action jsonb NOT NULL, expected_impact jsonb NOT NULL DEFAULT '{}'::jsonb, confidence numeric(5,2) NOT NULL DEFAULT 0 CHECK (confidence >= 0 AND confidence <= 100), classification public.ai_action_class NOT NULL DEFAULT 'APPROVAL_REQUIRED', policy_id uuid REFERENCES public.ai_policies(id), policy_status text NOT NULL DEFAULT 'PENDING', requires_approval boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ACTIONED','DISMISSED','EXPIRED','SUPERSEDED')), dedupe_key text NOT NULL UNIQUE, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_lifecycle_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lifecycle_id uuid NOT NULL REFERENCES public.commercial_lifecycle(id) ON DELETE CASCADE, lead_ref text, from_state text, to_state text NOT NULL, amount_kes numeric, reason text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, missing_evidence jsonb NOT NULL DEFAULT '[]'::jsonb, is_override boolean NOT NULL DEFAULT false, actor_id uuid, actor_staff_id uuid, work_item_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_lifecycle_evidence ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lifecycle_id uuid NOT NULL REFERENCES public.commercial_lifecycle(id) ON DELETE CASCADE, document_type text NOT NULL, reference text, document_id uuid, document_table text, note text, recorded_by uuid, recorded_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commission_resolutions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_kind text NOT NULL, source_id text NOT NULL, idempotency_key text NOT NULL UNIQUE, schedule_id uuid NOT NULL REFERENCES public.commission_schedules(id), schedule_code text NOT NULL, schedule_version int NOT NULL, rule_id uuid REFERENCES public.commission_rules(id), rate_percent numeric NOT NULL, basis text NOT NULL, excluded_components jsonb NOT NULL DEFAULT '[]'::jsonb, currency text NOT NULL DEFAULT 'KES', base_amount numeric NOT NULL, commission_amount numeric NOT NULL, net_service_price numeric NOT NULL DEFAULT 0, tax_amount numeric NOT NULL DEFAULT 0, pass_through_amount numeric NOT NULL DEFAULT 0, customer_total numeric NOT NULL DEFAULT 0, supplier_payout numeric NOT NULL DEFAULT 0, price_stack jsonb NOT NULL DEFAULT '[]'::jsonb, account_id uuid, owner_staff_id uuid, calculated_at timestamptz NOT NULL DEFAULT now(), created_by uuid );
CREATE TABLE IF NOT EXISTS public.comms_messages ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.comms_threads(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES public.comms_accounts(id) ON DELETE CASCADE, direction public.comms_direction NOT NULL, provider_message_id text, source text NOT NULL DEFAULT 'provider', source_id text, from_address text, from_name text, to_addresses text[] NOT NULL DEFAULT '{}', cc_addresses text[] NOT NULL DEFAULT '{}', subject text, body_preview text, body_html text, has_attachments boolean NOT NULL DEFAULT false, delivery_status text, occurred_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.comms_reply_drafts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), account_id uuid NOT NULL REFERENCES public.comms_accounts(id) ON DELETE CASCADE, thread_id uuid REFERENCES public.comms_threads(id) ON DELETE SET NULL, to_address text NOT NULL, subject text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','failed')), error text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.comms_thread_resources ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid REFERENCES public.comms_threads(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('attachment','meeting','sheet','document','link')), label text NOT NULL CHECK (char_length(label) BETWEEN 1 AND 200), url text CHECK (url IS NULL OR url ~ '^https://'), storage_path text, mime_type text, size_bytes bigint CHECK (size_bytes IS NULL OR size_bytes <= 10485760), meeting_booking_id uuid REFERENCES public.public_meeting_bookings(id) ON DELETE SET NULL, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CHECK ((kind='attachment' AND storage_path IS NOT NULL) OR (kind<>'attachment' AND url IS NOT NULL)) );
CREATE TABLE IF NOT EXISTS public.compliance_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_id uuid REFERENCES public.compliance_alerts(id) ON DELETE SET NULL, driver_id uuid, vehicle_id uuid, action public.compliance_action_type NOT NULL, reason text, effective_from timestamptz NOT NULL DEFAULT now(), effective_until timestamptz, actor_id uuid, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.control_tower_alert_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_id uuid NOT NULL REFERENCES public.control_tower_alerts(id) ON DELETE CASCADE, action text NOT NULL, from_status public.ct_alert_status, to_status public.ct_alert_status, actor_id uuid, notes text, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_distributions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mark_id uuid NOT NULL REFERENCES public.doc_security_marks(id) ON DELETE RESTRICT, distribution_ref text NOT NULL UNIQUE, recipient_label text NOT NULL, recipient_role text, channel text NOT NULL DEFAULT 'download', file_hash text, purpose text, issued_to uuid, issued_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_evidence_exports ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mark_id uuid NOT NULL REFERENCES public.doc_security_marks(id) ON DELETE CASCADE, doc_number text NOT NULL, manifest_sha256 text NOT NULL, body_sha256 text NOT NULL, proof jsonb NOT NULL DEFAULT '{}'::jsonb, exported_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_security_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mark_id uuid NOT NULL REFERENCES public.doc_security_marks(id) ON DELETE RESTRICT, event_type text NOT NULL, actor_id uuid, actor_role text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, prev_chain_hash text, chain_hash text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_signatures ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mark_id uuid NOT NULL REFERENCES public.doc_security_marks(id) ON DELETE RESTRICT, key_id text NOT NULL REFERENCES public.doc_signing_keys(key_id), algorithm text NOT NULL DEFAULT 'ed25519', signed_statement text NOT NULL, statement_hash text NOT NULL, signature_b64 text NOT NULL, signed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_template_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES public.doc_template_versions(id) ON DELETE CASCADE, decision text NOT NULL CHECK (decision IN ('APPROVED','REJECTED')), decided_by uuid, decided_by_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, sole_approver boolean NOT NULL DEFAULT false, note text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_template_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid REFERENCES public.doc_template_versions(id) ON DELETE CASCADE, template_id uuid REFERENCES public.doc_templates(id) ON DELETE CASCADE, event text NOT NULL, status_before text, status_after text, actor_user_id uuid, actor_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, note text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.doc_verification_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), doc_number text NOT NULL, outcome text NOT NULL, mark_id uuid REFERENCES public.doc_security_marks(id) ON DELETE RESTRICT, client_ref text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.document_review_sla ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_id uuid NOT NULL REFERENCES public.document_review_actions(id) ON DELETE CASCADE, queue_id uuid, assigned_to uuid REFERENCES auth.users(id), sla_minutes integer NOT NULL DEFAULT 60, due_at timestamptz NOT NULL, completed_at timestamptz, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed','overdue','escalated')), escalation_level integer NOT NULL DEFAULT 0, last_escalated_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(action_id) );
CREATE TABLE IF NOT EXISTS public.lg_dossier_notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_id uuid REFERENCES public.lg_dossier_audit(id) ON DELETE SET NULL, control_id text NOT NULL, document_id text, document_version_id uuid, document_version integer, event text NOT NULL CHECK (event IN ('SEEDED','VERSION_PUBLISHED','SUPERSEDED','APPROVAL_RECORDED','BECAME_EFFECTIVE')), channel text NOT NULL CHECK (channel IN ('email','in_app')), recipient_role text, recipient_user_id uuid, recipient_email text, subject text NOT NULL, body text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sent','failed','skipped')), attempts integer NOT NULL DEFAULT 0, last_error text, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz );
CREATE TABLE IF NOT EXISTS public.opt_experiment_observations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), experiment_id uuid NOT NULL REFERENCES public.opt_experiments(id) ON DELETE CASCADE, arm text NOT NULL CHECK (arm IN ('CONTROL','TREATMENT')), measurement_id uuid NOT NULL REFERENCES public.opt_measurements(id), is_guardrail boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.opt_optimizations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, objective text NOT NULL, domain text NOT NULL, hypothesis text NOT NULL, expected_impact jsonb NOT NULL, confidence numeric NOT NULL CHECK (confidence >= 0 AND confidence <= 1), risk_class public.opt_risk_class NOT NULL, approval_required boolean NOT NULL DEFAULT true, human_only boolean NOT NULL DEFAULT false, baseline_measurement_id uuid REFERENCES public.opt_measurements(id), target_metric_code text NOT NULL REFERENCES public.opt_metrics(code), experiment_id uuid REFERENCES public.opt_experiments(id), rollback_condition text NOT NULL, simulation jsonb, simulated_at timestamptz, state public.opt_state NOT NULL DEFAULT 'DRAFT', decided_by uuid, decided_at timestamptz, decision_reason text, result_measurement_id uuid REFERENCES public.opt_measurements(id), result jsonb, adopted_at timestamptz, rolled_back_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_lifecycle_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), signal_id uuid REFERENCES public.partner_lifecycle_signals(id) ON DELETE SET NULL, session_id text NOT NULL, profile_id uuid REFERENCES public.partner_intent_profiles(id) ON DELETE SET NULL, work_item_id uuid REFERENCES public.partner_work_items(id) ON DELETE SET NULL, previous_stage text, lifecycle_stage text NOT NULL, maturity_level text, network_category text, intent_bring text, ab_variant text, page_source text, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_staff_notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, title text NOT NULL, body text, severity text NOT NULL DEFAULT 'info', work_item_id uuid REFERENCES public.partner_work_items(id) ON DELETE CASCADE, signal_id uuid REFERENCES public.partner_lifecycle_signals(id) ON DELETE CASCADE, profile_id uuid REFERENCES public.partner_intent_profiles(id) ON DELETE CASCADE, application_id uuid REFERENCES public.partner_applications(id) ON DELETE CASCADE, session_id text, context jsonb NOT NULL DEFAULT '{}'::jsonb, acknowledged_by uuid, acknowledged_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT partner_staff_notifications_kind_chk CHECK ( kind = ANY (ARRAY['lifecycle_stage_changed','intent_profile_created','intent_profile_updated','application_received']) ), CONSTRAINT partner_staff_notifications_severity_chk CHECK ( severity = ANY (ARRAY['info','warning','critical']) ) );
CREATE TABLE IF NOT EXISTS public.rec_assessment_answers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES public.rec_assessments(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.rec_question_bank(id), question_key text NOT NULL, question_version integer NOT NULL, question_snapshot jsonb NOT NULL, competency_code text NOT NULL, competency_label text NOT NULL, max_marks numeric NOT NULL, critical_min numeric, mandatory boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, answer_text text, evidence_text text, verification_status text NOT NULL DEFAULT 'unverified', evidence_confidence text NOT NULL DEFAULT 'unverified', score numeric, rationale text, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_answer_uk UNIQUE (assessment_id, question_id), CONSTRAINT rec_answer_score_ck CHECK (score IS NULL OR (score >= 0 AND score <= max_marks)), CONSTRAINT rec_answer_verif_ck CHECK (verification_status IN ('claimed','verified','demonstrated','partially_verified','unverified','contradicted','not_applicable')), CONSTRAINT rec_answer_conf_ck CHECK (evidence_confidence IN ('high','medium','low','unverified')) );
CREATE TABLE IF NOT EXISTS public.rec_claim_validations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES public.rec_cv_claims(id) ON DELETE CASCADE, assessment_id uuid REFERENCES public.rec_assessments(id) ON DELETE SET NULL, question_text text NOT NULL, response_text text, evidence_text text, verification_status text NOT NULL DEFAULT 'unverified', confidence text NOT NULL DEFAULT 'unverified', validated_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_claim_val_verif_ck CHECK (verification_status IN ('claimed','verified','demonstrated','partially_verified','unverified','contradicted','not_applicable')), CONSTRAINT rec_claim_val_conf_ck CHECK (confidence IN ('high','medium','low','unverified')) );
CREATE TABLE IF NOT EXISTS public.rec_migration_duplicates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.rec_migration_batches(id) ON DELETE CASCADE, record_id uuid NOT NULL REFERENCES public.rec_migration_records(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, classification text NOT NULL CHECK (classification IN ('exact','probable','possible','different')), similarity numeric NOT NULL DEFAULT 0, signals jsonb NOT NULL DEFAULT '[]'::jsonb, resolution text NOT NULL DEFAULT 'pending' CHECK (resolution IN ('pending','merged','kept_separate')), resolved_by uuid, resolved_at timestamptz, resolution_notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (record_id, candidate_id) );
CREATE TABLE IF NOT EXISTS public.rec_migration_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid REFERENCES public.rec_migration_batches(id) ON DELETE CASCADE, record_id uuid REFERENCES public.rec_migration_records(id) ON DELETE CASCADE, action text NOT NULL, actor_id uuid DEFAULT auth.uid(), before_state jsonb, after_state jsonb, reason text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_migration_record_files ( record_id uuid NOT NULL REFERENCES public.rec_migration_records(id) ON DELETE CASCADE, file_id uuid NOT NULL REFERENCES public.rec_migration_files(id) ON DELETE CASCADE, doc_type text NOT NULL DEFAULT 'cv', match_method text NOT NULL DEFAULT 'manual', match_confidence numeric, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (record_id, file_id) );
CREATE TABLE IF NOT EXISTS public.rec_profession_responses ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES public.rec_profession_attempts(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.rec_question_bank(id), question_key text NOT NULL, question_version integer NOT NULL, question_type text NOT NULL, question_snapshot jsonb NOT NULL, competency_code text NOT NULL, competency_label text NOT NULL, max_marks numeric NOT NULL, critical_min numeric, mandatory boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0, scoring_mode text NOT NULL DEFAULT 'rubric', response_text text, selected_options jsonb, work_sample_document_id uuid REFERENCES public.rec_candidate_documents(id) ON DELETE SET NULL, auto_score numeric, rubric_score numeric, score numeric, anchor_level text, rationale text, scored_by uuid, scored_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_profession_responses_mode_chk CHECK (scoring_mode IN ('auto','rubric')), CONSTRAINT rec_profession_responses_unique UNIQUE (attempt_id, question_id) );
CREATE TABLE IF NOT EXISTS public.rec_requirement_responses ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, rule_id uuid REFERENCES public.rec_document_requirement_rules(id) ON DELETE SET NULL, requirement_key text NOT NULL, doc_key text, declared boolean NOT NULL DEFAULT false, declared_detail text, staff_status text NOT NULL DEFAULT 'pending', staff_note text, decided_by uuid, decided_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_requirement_responses_status_check CHECK (staff_status IN ('pending','accepted','rejected')), CONSTRAINT rec_requirement_responses_unique UNIQUE (application_id, requirement_key) );
CREATE TABLE IF NOT EXISTS public.rec_selection_decisions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES public.rec_applications(id) ON DELETE CASCADE, vacancy_id uuid NOT NULL REFERENCES public.rec_vacancies(id) ON DELETE CASCADE, candidate_id uuid NOT NULL REFERENCES public.rec_candidates(id) ON DELETE CASCADE, decision text NOT NULL, stage_at_decision text NOT NULL, ai_recommendation text, ai_confidence numeric, is_override boolean NOT NULL DEFAULT false, reason_code text REFERENCES public.rec_rejection_reasons(code), reason_notes text, evaluation_id uuid REFERENCES public.rec_application_evaluations(id), evidence jsonb NOT NULL DEFAULT '{}'::jsonb, decision_maker uuid, decision_role text, decided_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_selection_decision_ck CHECK (decision IN ('advance','not_selected','selected','hold')) );
CREATE TABLE IF NOT EXISTS public.regulatory_submissions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), export_id uuid NOT NULL REFERENCES public.regulatory_exports(id) ON DELETE CASCADE, regulator public.regulator NOT NULL, submitted_at timestamptz, submitted_by uuid, acknowledgement_ref text, status public.reg_submission_status NOT NULL DEFAULT 'DRAFT', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_commission_event_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.sales_commission_events(id), action text NOT NULL, actor_id uuid, before_state jsonb, after_state jsonb, changes jsonb NOT NULL DEFAULT '{}'::jsonb, reason text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.sales_sla_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clock_id uuid REFERENCES public.sales_sla_clocks(id) ON DELETE CASCADE, action text NOT NULL, escalation_level int, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_user_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_post_variants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.social_posts(id) ON DELETE CASCADE, platform_slug text NOT NULL REFERENCES public.social_platforms(slug) ON DELETE RESTRICT, account_id uuid NOT NULL REFERENCES public.social_accounts(id) ON DELETE RESTRICT, caption text NOT NULL DEFAULT '', headline text, media_asset_ids uuid[] NOT NULL DEFAULT '{}', destination_url text, platform_options jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','VALIDATED','APPROVED','SCHEDULED','QUEUED','PUBLISHING','PUBLISHED','FAILED','CANCELLED','DELETED')), version integer NOT NULL DEFAULT 1, content_hash text, approved_hash text, external_post_id text, external_url text, published_at timestamptz, failure_code text, failure_message text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (post_id, platform_slug, account_id) );
CREATE TABLE IF NOT EXISTS public.ai_action_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recommendation_id uuid NOT NULL REFERENCES public.ai_recommendations(id), action_type text NOT NULL, classification public.ai_action_class NOT NULL, policy_id uuid REFERENCES public.ai_policies(id), policy_result jsonb NOT NULL DEFAULT '{}'::jsonb, target_service text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, entity_type text NOT NULL, entity_id uuid, requested_by uuid, requested_by_kind text NOT NULL DEFAULT 'AGENT' CHECK (requested_by_kind IN ('AGENT','OPERATOR')), state public.ai_action_state NOT NULL DEFAULT 'PROPOSED', idempotency_key text NOT NULL UNIQUE, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_context_references ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recommendation_id uuid NOT NULL REFERENCES public.ai_recommendations(id) ON DELETE CASCADE, source_table text NOT NULL, source_id uuid, source_ref text, snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, captured_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_findings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), detector_code text NOT NULL, detector_version integer NOT NULL, tenant_id uuid, source_event_table text NOT NULL, source_event_id uuid, source_event_ref text, entity_type text NOT NULL, entity_id uuid, entity_ref text, severity text NOT NULL CHECK (severity IN ('P0','P1','P2','P3')), evidence jsonb NOT NULL DEFAULT '{}'::jsonb, confidence numeric NOT NULL CHECK (confidence >= 0 AND confidence <= 1), dedupe_key text NOT NULL UNIQUE, detected_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','ASSESSED','RECOMMENDED','NO_ACTION','DISMISSED','EXPIRED')), recommendation_id uuid REFERENCES public.ai_recommendations(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.comms_email_tasks ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL REFERENCES public.comms_messages(id) ON DELETE CASCADE, thread_id uuid NOT NULL REFERENCES public.comms_threads(id) ON DELETE CASCADE, mailbox_id uuid NOT NULL REFERENCES public.comms_accounts(id) ON DELETE CASCADE, staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, title text NOT NULL CHECK (length(title) BETWEEN 1 AND 300), due_at timestamptz, status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','done','cancelled')), meeting_url text CHECK (meeting_url IS NULL OR meeting_url ~* '^https://'), meeting_at timestamptz, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, sales_lead_id uuid REFERENCES public.sales_leads(id) ON DELETE SET NULL, crm_account_id uuid REFERENCES public.crm_accounts(id) ON DELETE SET NULL, created_by uuid DEFAULT auth.uid(), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (message_id) );
CREATE TABLE IF NOT EXISTS public.document_review_escalations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sla_id uuid NOT NULL REFERENCES public.document_review_sla(id) ON DELETE CASCADE, action_id uuid NOT NULL, escalation_level integer NOT NULL, reason text NOT NULL, escalated_to uuid REFERENCES auth.users(id), triggered_by text NOT NULL DEFAULT 'system', payload jsonb NOT NULL DEFAULT '{}'::jsonb, prev_hash text, record_hash text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.opt_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, optimization_id uuid REFERENCES public.opt_optimizations(id) ON DELETE SET NULL, experiment_id uuid REFERENCES public.opt_experiments(id) ON DELETE SET NULL, measurement_id uuid REFERENCES public.opt_measurements(id) ON DELETE SET NULL, actor_id uuid, actor_kind text NOT NULL DEFAULT 'OPERATOR', detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_assessment_amendments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES public.rec_assessments(id) ON DELETE CASCADE, answer_id uuid REFERENCES public.rec_assessment_answers(id) ON DELETE SET NULL, before_value jsonb NOT NULL DEFAULT '{}'::jsonb, after_value jsonb NOT NULL DEFAULT '{}'::jsonb, reason text NOT NULL, actor_id uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.social_post_metrics ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid NOT NULL REFERENCES public.social_post_variants(id) ON DELETE CASCADE, platform_slug text NOT NULL, metric text NOT NULL, value numeric NOT NULL, source text NOT NULL DEFAULT 'PROVIDER_API', captured_at timestamptz NOT NULL DEFAULT now(), UNIQUE (variant_id, metric, captured_at) );
CREATE TABLE IF NOT EXISTS public.social_publication_jobs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid NOT NULL REFERENCES public.social_post_variants(id) ON DELETE CASCADE, post_id uuid NOT NULL REFERENCES public.social_posts(id) ON DELETE CASCADE, platform_slug text NOT NULL, account_id uuid NOT NULL, idempotency_key text NOT NULL UNIQUE, state text NOT NULL DEFAULT 'QUEUED' CHECK (state IN ('QUEUED','VALIDATING','MEDIA_UPLOADING','PUBLISHING','PLATFORM_ACCEPTED','PUBLISHED', 'FAILED','RETRY_PENDING','RETRYING','FAILED_PERMANENTLY','CANCELLED','DEAD_LETTER')), dry_run boolean NOT NULL DEFAULT false, attempt integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, scheduled_for timestamptz NOT NULL DEFAULT now(), next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_by text, locked_at timestamptz, error_code text, error_message text, provider_ref jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_action_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_request_id uuid NOT NULL REFERENCES public.ai_action_requests(id) ON DELETE CASCADE, decision text NOT NULL CHECK (decision IN ('APPROVED','REJECTED','DEFERRED','ESCALATED')), approver_id uuid NOT NULL, approver_role text, reason text NOT NULL, evidence_reviewed boolean NOT NULL DEFAULT false, decided_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_action_executions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_request_id uuid NOT NULL REFERENCES public.ai_action_requests(id) ON DELETE CASCADE, attempt integer NOT NULL DEFAULT 1, invoked_service text NOT NULL, service_result jsonb NOT NULL DEFAULT '{}'::jsonb, succeeded boolean NOT NULL DEFAULT false, verified boolean NOT NULL DEFAULT false, verification jsonb NOT NULL DEFAULT '{}'::jsonb, error_code text, error_message text, executed_by uuid, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, UNIQUE (action_request_id, attempt) );
CREATE TABLE IF NOT EXISTS public.ai_action_outcomes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action_request_id uuid NOT NULL UNIQUE REFERENCES public.ai_action_requests(id) ON DELETE CASCADE, expected jsonb NOT NULL DEFAULT '{}'::jsonb, actual jsonb NOT NULL DEFAULT '{}'::jsonb, variance jsonb NOT NULL DEFAULT '{}'::jsonb, success boolean, measured_at timestamptz NOT NULL DEFAULT now(), notes text );
CREATE TABLE IF NOT EXISTS public.ai_audit_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, agent_id uuid REFERENCES public.ai_agents(id), agent_version_id uuid REFERENCES public.ai_agent_versions(id), recommendation_id uuid REFERENCES public.ai_recommendations(id) ON DELETE SET NULL, action_request_id uuid REFERENCES public.ai_action_requests(id) ON DELETE SET NULL, actor_id uuid, actor_kind text NOT NULL DEFAULT 'AGENT', policy_result jsonb, detail jsonb NOT NULL DEFAULT '{}'::jsonb, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_context_snapshots ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), finding_id uuid NOT NULL REFERENCES public.ai_findings(id) ON DELETE CASCADE, context_version integer NOT NULL DEFAULT 1, sources jsonb NOT NULL, snapshot jsonb NOT NULL, context_hash text NOT NULL, assembled_at timestamptz NOT NULL DEFAULT now(), UNIQUE (finding_id, context_version) );
CREATE TABLE IF NOT EXISTS public.ai_domain_commands ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), command_key text NOT NULL UNIQUE, action_request_id uuid NOT NULL REFERENCES public.ai_action_requests(id) ON DELETE CASCADE, adapter_code text NOT NULL, target_function text NOT NULL, result jsonb NOT NULL DEFAULT '{}'::jsonb, invoked_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_non_actions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL CHECK (code IN ( 'ACTION_NOT_REQUIRED','ACTION_NOT_POSSIBLE','ACTION_BLOCKED', 'ACTION_EXPIRED','STALE_CONTEXT','INSUFFICIENT_EVIDENCE')), finding_id uuid REFERENCES public.ai_findings(id) ON DELETE CASCADE, recommendation_id uuid REFERENCES public.ai_recommendations(id) ON DELETE SET NULL, action_request_id uuid REFERENCES public.ai_action_requests(id) ON DELETE SET NULL, entity_type text, entity_id uuid, reason text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, candidates_evaluated jsonb NOT NULL DEFAULT '[]'::jsonb, policy_id uuid REFERENCES public.ai_policies(id), next_step text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ai_model_invocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), model_code text NOT NULL REFERENCES public.ai_model_registry(code), agent_id uuid REFERENCES public.ai_agents(id), agent_version_id uuid REFERENCES public.ai_agent_versions(id), finding_id uuid REFERENCES public.ai_findings(id) ON DELETE SET NULL, context_snapshot_id uuid REFERENCES public.ai_context_snapshots(id) ON DELETE SET NULL, context_hash text, prompt_version text NOT NULL, tool_version text NOT NULL, policy_version integer, outcome text NOT NULL CHECK (outcome IN ('OK','FAILED','TIMEOUT','UNAVAILABLE','NOT_CONFIGURED','FALLBACK_USED','LOW_CONFIDENCE')), latency_ms integer, tokens_in integer, tokens_out integer, cost_usd numeric, confidence numeric, fallback_of text, error_message text, invoked_at timestamptz NOT NULL DEFAULT now() );
