ALTER TABLE public.sales_engine_settings ADD COLUMN IF NOT EXISTS eligible_position_codes text[] NOT NULL DEFAULT ARRAY['YML-SAL-CSS-001','SLS-MOB','SLS-SUP','SLS-PRT','SLS-LEAD'];
ALTER TABLE public.sales_engine_settings ADD COLUMN IF NOT EXISTS revenue_basis text NOT NULL DEFAULT 'RECOGNISED', ADD COLUMN IF NOT EXISTS require_state_evidence boolean NOT NULL DEFAULT true;
ALTER TABLE public.sales_engine_settings ADD COLUMN IF NOT EXISTS reminder_days_to_meeting integer NOT NULL DEFAULT 5, ADD COLUMN IF NOT EXISTS reminder_days_meeting_to_quote integer NOT NULL DEFAULT 3, ADD COLUMN IF NOT EXISTS reminder_days_quote_to_contract integer NOT NULL DEFAULT 5, ADD COLUMN IF NOT EXISTS reminder_days_contract_to_signed integer NOT NULL DEFAULT 7;
ALTER TABLE public.social_webhook_events ADD COLUMN IF NOT EXISTS event_kind text NOT NULL DEFAULT 'UNKNOWN', ADD COLUMN IF NOT EXISTS external_post_id text, ADD COLUMN IF NOT EXISTS variant_id uuid, ADD COLUMN IF NOT EXISTS result text NOT NULL DEFAULT 'RECEIVED', ADD COLUMN IF NOT EXISTS detail jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.alerts_events ADD COLUMN IF NOT EXISTS is_test boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS channels_dispatched jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.alerts_events ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
ALTER TABLE public.commercial_quotation_lines ADD COLUMN IF NOT EXISTS recommended_unit_amount numeric(14,2), ADD COLUMN IF NOT EXISTS price_source text NOT NULL DEFAULT 'RECOMMENDED', ADD COLUMN IF NOT EXISTS variance_percent numeric(8,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS commercial_reason text;
ALTER TABLE public.doc_security_marks ADD COLUMN IF NOT EXISTS revoked_at timestamptz, ADD COLUMN IF NOT EXISTS revoked_reason text, ADD COLUMN IF NOT EXISTS revoked_by uuid;
ALTER TABLE public.fraud_alerts ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.meeting_type_hosts ADD COLUMN IF NOT EXISTS calendar_status text NOT NULL DEFAULT 'unknown' CHECK (calendar_status IN ('verified','not_shared','unknown')), ADD COLUMN IF NOT EXISTS calendar_checked_at timestamptz;
ALTER TABLE public.meeting_type_hosts ADD COLUMN IF NOT EXISTS max_per_day integer NOT NULL DEFAULT 6 CHECK (max_per_day BETWEEN 1 AND 20);
ALTER TABLE public.paf_remediation_applications ADD COLUMN IF NOT EXISTS idempotency_key text, ADD COLUMN IF NOT EXISTS batch_id uuid;
ALTER TABLE public.partner_lifecycle_signals ADD COLUMN IF NOT EXISTS dispatch_state text NOT NULL DEFAULT 'dispatched', ADD COLUMN IF NOT EXISTS dispatch_reason text, ADD COLUMN IF NOT EXISTS batched_into_signal_id uuid, ADD COLUMN IF NOT EXISTS notified_at timestamptz;
ALTER TABLE public.rec_document_requirement_rules ADD COLUMN IF NOT EXISTS requirement_text text, ADD COLUMN IF NOT EXISTS hard_requirement boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS evidence_kind text NOT NULL DEFAULT 'document', ADD COLUMN IF NOT EXISTS accepted_evidence_types text[] NOT NULL DEFAULT '{}', ADD COLUMN IF NOT EXISTS declaration_prompt text, ADD COLUMN IF NOT EXISTS response_required boolean NOT NULL DEFAULT false;
ALTER TABLE public.rental_exceptions ADD COLUMN IF NOT EXISTS decision_class text, ADD COLUMN IF NOT EXISTS owner_role text, ADD COLUMN IF NOT EXISTS sla_minutes integer, ADD COLUMN IF NOT EXISTS sla_due_at timestamptz, ADD COLUMN IF NOT EXISTS sla_breached boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS escalated_at timestamptz, ADD COLUMN IF NOT EXISTS escalated_to text;
ALTER TABLE public.report_export_runs ADD COLUMN IF NOT EXISTS attempt integer NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS max_attempts integer NOT NULL DEFAULT 3, ADD COLUMN IF NOT EXISTS next_retry_at timestamptz, ADD COLUMN IF NOT EXISTS artifact_path text, ADD COLUMN IF NOT EXISTS artifact_bytes integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS content_hash text, ADD COLUMN IF NOT EXISTS download_count integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS last_error_code text, ADD COLUMN IF NOT EXISTS completed_at timestamptz;
ALTER TABLE public.ai_recommendations ADD COLUMN IF NOT EXISTS finding_id uuid REFERENCES public.ai_findings(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS context_snapshot_id uuid REFERENCES public.ai_context_snapshots(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS context_hash text, ADD COLUMN IF NOT EXISTS model_invocation_id uuid REFERENCES public.ai_model_invocations(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS grounded boolean NOT NULL DEFAULT false;
ALTER TABLE public.doc_verification_attempts ADD COLUMN IF NOT EXISTS client_fingerprint text, ADD COLUMN IF NOT EXISTS state text, ADD COLUMN IF NOT EXISTS relyable boolean;
ALTER TABLE public.document_review_sla ADD COLUMN IF NOT EXISTS grace_minutes integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS rule_key text;
ALTER TABLE public.ai_action_requests ADD COLUMN IF NOT EXISTS context_hash text, ADD COLUMN IF NOT EXISTS context_snapshot_id uuid REFERENCES public.ai_context_snapshots(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS policy_version integer, ADD COLUMN IF NOT EXISTS adapter_id uuid REFERENCES public.ai_adapters(id);
